INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Blagor možu, ki ne hodi po sovetu krivičnih in ne stopa na grešnikov pot ter ne sedeva v zboru zasmehovalcev;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Nego veselje njegovo je v postavi Gospodovi, in postavo njegovo premišljuje noč in dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Je namreč kakor drevo zasajeno ob vodnih potocih, katero sad svoj rodi o svojem času, in listje njegovo ne odpada: zatorej karkoli bode počel, posrečilo se mu bode.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ne tako krivični; nego kakor pleve, katere veter raznaša.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Zatorej ne ostanejo krivični v óni sodbi; ne grešniki v zboru pravičnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Ker Gospod pozna pravičnih pot; pot pa krivičnih izgine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Zakaj hrumé narodi in ljudstva si izmišljajo prazno?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Zemlje kralji vstajajo in prvaki se posvetujejo skupaj zoper Gospoda in zoper maziljenca njegovega:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Raztrgajmo njih vezí in sè sebe vrzimo njih debele vrvi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Sedeči v nebesih se smeje; zasmehuje jih Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Tedaj jih ogovorí v jezi svoji, in v srdu svojem jih prestraši:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Saj sem jaz pomazilil kralja svojega ter postavil čez Sijon, gôro svetosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Oznanim naj sklep: Gospod mi je rekel: Sin si moj, jaz sem te danes rodil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Prosi me, in narode ti dam v posest in kraje zemlje v pravico posesti tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Zdrobiš jih s šibo železno; kakor prsteno posodo jih razsuješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Zdaj torej, kralji, poslušajte; poduk sprejmite, o zemlje sodniki!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'V svetem strahu služite Gospodu, in radujte se v trepetu!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Poljubite Sina, da se ne razsrdi in ne poginete na potu, ako se le kolikaj razvname jeza njegova; blagor vsem, kateri pribegajo do njega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Psalm Davidov, ko je bežal pred Absalomom, sinom svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Gospod, koliko je sovražnikov mojih, koliko jih vstaja proti meni!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Koliko jih govori za dušo mojo: Ni je pomoči njej v Bogu nobene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Ti pa, Gospod, ščit si meni, slava moja, in glavo mojo vzdiguješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Z glasom svojim vpijočemu v Gospoda odgovoril mi je z gore svetosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Jaz sem ležal in spal, zbudil sem se, ker Gospod me podpira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Ne bodem se bal ljudstva tisočin, katere bodo okrog razpostavili proti meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Vstani, Gospod; reši me, moj Bog, ki si udaril vse sovražnike moje po čeljusti, zobe zdrobil krivičnim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Gospodovo je rešenje; nad ljudstvom tvojim blagoslov tvoj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Načelniku godbe na strune; psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Ko te kličem, usliši me, Bog pravice moje; v stiski dal si mi prostora; milosten mi bodi in poslušaj molitev mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Sinovi človeški, doklej bodi slava moja v nečast? ljubili bodete ničnost? hodili za lažjo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Spoznajte vendar, da si je Gospod posebe odbral njega, katerega prijazno sprejema; da bode uslišal Gospod, ko ga bodem zaklical.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Prestrašite se in ne grešite; mislite v srci svojem, na ležišči svojem in mirujte!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Darujte daritve pravice, in zaupanje imejte v Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 7, 'Mnogi govoré: O da bi vživali dobro! Dvigni nad nas svetlobo obličja svojega, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 8, 'Vlij radost v srce moje, večjo nego o času, ko spravljajo žito svoje in vino svoje obilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 9, 'V miru ležem in zdajci zaspim; ker ti sam, Gospod, daješ, da prebivam brez skrbi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Načelniku godbe na piščali; psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Besede moje čuj, Gospod; ozri se na premišljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Poslušaj vpitja mojega glas, kralj moj in Bog moj: ker pri tebi imam molitev.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Gospod, zgodaj bodeš slišal glas moj; zgodaj bodem govoril pred teboj in čakal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Ker ti nisi Bog mogočni, kateri bi se radoval krivice; pred teboj ne bode prebivalo hudo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Blazni ne stopajo ti pred óči; sovražiš vse, kateri delajo krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Pogubiti hočeš nje, ki laž govoré; moža krvoželjnega in zvijačnega studi Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Jaz pa vnidem obdan z obilnostjo milosti tvoje v hišo tvojo; priklonim se proti hramu svetosti tvoje v svetem strahu tvojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Gospod, spremljaj me v pravici svoji zavoljo zalezovalcev mojih; pot svojo ugladi pred menoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Ker v ustih njihovih ni pravice; notranjost njih: nadloge, grob odprt njih grlo; z jezikom svojim se dobrikajo zvijačno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Pokôri jih, o Bog; izpodleté naj v naklepih svojih; pahni jih dol po obilosti njih pregréh, ker upirajo se zoper tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'In veselili se bodo vsi, kateri pribegajo k tebi; na veke bodo prepevali, katerim bodeš bramba, in radovali se bodo v tebi ljubitelji tvojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Ker ti blagoslavljaš pravičnega, Gospod, delaš, da ga milost krije kakor ščit.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Načelniku godbe na strune po osmini; psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Gospod, v jezi svoji ne pokôri me; in v srdu svojem ne tepi me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Milosten mi bodi, Gospod, ker opešal sem: ozdravi me, Gospod, ker preplašene so kosti moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'In duša moja je preplašena silno, ti torej, Gospod, doklej?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Povrni se, Gospod; otmi dušo mojo, po milosti svoji reši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Ker spomina nate ni v smrti sami; v grobu kdo te bode slavil?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Utrujen sem v zdihovanji svojem; storil sem, da plava vso noč postelja moja; sè solzami svojimi sem raztopil ležišče svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Otemnelo je od žalovanja moje oko; postaralo se je med vsemi mojimi zatiralci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Poberite se od mene vsi, ki delate krivico; ker Gospod posluša glas mojega joka.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Gospod posluša prošnjo mojo; Gospodu je prijetna molitev moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Osramoté se naj in preplašijo silno vsi sovražniki moji; vrnejo se naj, osramoté pri tej priči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Pesem meševita Davidova, katero je pel Gospodu na besede Kusa Benjaminca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Gospod, Bog moj, k tebi pribegam; reši me vseh preganjalcev mojih in oprosti me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Da ne zgrabi kakor lev duše moje in raztrga, ko ni pomočnika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Gospod, Bog moj, ako sem storil tisto, ako je krivica na rokah mojih:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Ako sem storil hudo v miru živečemu z menoj, ki sem mu rad pomagal, kateri me je zatiral po krivem:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Preganja naj sovražnik dušo mojo in dohiti ter potepta na tleh življenje moje; in storí naj, da v prahu biva slava moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Vstani, Gospod, v jezi svoji; dvigni se silno razkačen proti njim, ki me zatirajo; in čuj nad menoj, sodbo si zapovedal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Torej narodov zbor naj te obdá in nad njim vrni se v višavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Gospod sodi ljudstva; sodi me, Gospod, po pravičnosti moji in po nedolžnosti moji razsodi zame.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Propade naj, prosim, zlo krivičnih, in pravičnega utrdi; kakor preiskuješ srca in obisti, Bog pravični.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Ščit moj je v Bogu, ki daje blaginjo pravičnim v srci,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'V Bogu, ki je pravičnemu bramba in Bogu mogočnem, ki se srdi vsak dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Ako se ne izpreobrne krivični, nabrusi svoj meč; lok svoj je napél in pomeril vanj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Pomeril je vanj smrtno orožje; pušice svoje zgrabi zoper divjajoče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Glej, rodil bode ničemurnost; kakor je spočel nadlogo, tako bode rodil laž.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Vodnjak je kopal in izglobal ga; vanj je planil, v jami opravljat delo svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Povrne se nadloga njegova na glavo njegovo in nad téme njegovo pride njegova krivica.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Slaviti hočem Gospoda po pravici njegovi in prepeval bodem imenu Gospoda najvišjega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Načelniku godbe pri postaji Gitajski, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Gospod, kralj naš, kako veličastno je ime tvoje na vesoljni zemlji, kateri razodevaš nadnebeško lepoto svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Iz ust otrok in dojencev si ustanovil si utrjeno hvalo, zavoljo sovražnikov svojih, da krotiš neprijatelja in maščevalca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Ko ogledujem nebesa tvoja, prstov tvojih delo, mesec in zvezde, ki si jih napravil;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Kaj je človek, da se ga spominjaš, ali sin človekov, da ga obiskuješ!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Malo si ga sicer postavil pod angele, a venčal si ga sè slavo in veličastvom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Postavil si ga čez dela svojih rók; vse si položil pod noge njegove:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Drobnico in goveda, kolikor jih je, in tudi poljske živali;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Tice pod nebom in ribe v morji; karkoli se izprehaja po morskih stezah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Gospod, kralj naš, kako veličastno je ime tvoje na vesoljni zemlji!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Načelniku godbe, visoke do srednje, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Slavil bodem, Gospod, iz vsega srca svojega, oznanjal vsa čudovita dela tvoja,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Veselil se bodem in radoval v tebi, prepeval bodem tvojemu imenu, Najvišji:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Da sovražniki moji umikajoč se padajo in ginejo pred obličjem tvojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Ker sodil si pravico mojo in pravdo mojo, sedel si na prestolu, o branitelj pravice.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Pokaral si narode, pogubil krivičnega, ime njih si izbrisal na večne čase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, '0 sovražnik, konec je razdevanja na veke, in uničil si mesta njih, njih spomin je poginil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'A Gospod bode sedel na veke, pripravljajoč na sodbo prestol svoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'In sam bode sodil svet pravično, pravde razsojal narodom po vsej pravici.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'In Gospod bode grad na višini siromaku, grad na višini v časih, ko je v stiski.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Zaupanje torej bodo imeli v té, kateri poznajo ime tvoje, ker ne zapustiš, Gospod, njih, kateri te iščejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Prepevajte Gospoda, ki sedí na Sijonu, oznanjujte ljudstvom dela njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'On, ki maščuje kri v moritvi prelito, spominja se njih, ne zabi vpitja siromakov ubozih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Milost mi izkaži, Gospod, ozri se v ponižanje moje od sovražnikov mojih, dvigni me izpred smrtnih vrât:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Da oznanjam vesoljno slavo tvojo med vrati hčere Sijonske, radujem se v blaginji tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Pogreznili so se narodi v jamo, katero so bili napravili; v mrežo, katero zo bili skrili, vjela se je njih noga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Pokazal se je Gospod po sodbi, katero je storil; v svojem lastnem delu zapletel se je krivični; vsega pomiselka vredno!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Nazaj se bodo podili krivični noter do groba; vsi narodi, ki so pozabili Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Ker siromak naj se ne pozabi nikdar: ubogih upanje ne pogine vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Vstani, Gospod, da se ne ojači človek; sodba pridi nad narode pred obličjem tvojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'V strah jih primi, Gospod; siloma naj spoznajo narodi, da so umrjoči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Zakaj bivaš v daljavi, Gospod! zakaj se skrivaš v časih, ko smo v stiski?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Prevzetnost krivičnega hudo straši siromaka ubozega; zgrabijo se naj v naklepih, katere izmišljajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Ker krivični hvali dušo svojo v njenem hrepenenji, in njega, ki išče dobička, blagoslavlja, draži Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Krivični v napuhu svojega obraza: On ne kaznuje, ni Boga, té so vse misli njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Varna so pota njegova v vsakem času; previsoko so pogledu njegovemu sodbe tvoje: kateri koli so sovražniki njegovi, vanje piha žarjavico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'V srci svojem govori: Ne umaknem se, v nobeni dobi ne bodem v nesreči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Preklinjanja polna so usta njegova in zvijač in goljufije; pod jezikom njegovim je nadlega in ničemurnost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Poseda v votlini vašî, v zatišji, da bi ubil nedolžnega; oči njegove se skrivajo zoper onemoglega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'V zatišji preži, kakor lev v svojem brlogu; preži, da zgrabi siromaka ubozega; zgrabil bi rad siromaka ubozega, potegnil ga v mrežo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Sklujči se, potuhne se; in s krepkimi udi svojimi se zgrudi, kakor da so onemogli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'V srci svojem govori: Pozabil je Bog mogočni; obličje svoje skriva, ne ozré se nikoli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Vstani, Gospod, Bog mogočni, dvigni roko svojo; ne pozabi siromakov ubozih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Zakaj draži krivični Boga? v srci svojem govori, da ne bodeš térjal?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Zazdelo se je tebi, ko gledaš nadlego in gorjé, vzeti jih v roko svojo; brambi tvoji se izroča onemogli; siroti si tí pomočnik.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Zdrôbi roko krivičnemu in hudobnemu; preiskuj krivico njegovo, dokler je ne najdeš več.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Gospod je kralj večni; poginili so narodi sè zemlje njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Hrepenenje krotkih si uslišal, Gospod; potolaži tem srce, nagni svoje uho,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Maščujoč siroto in siromaka, da ga ne bode dalje izganjal človek silovito iz dežele.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Načelniku godbe, Davidova. Gospod je pribežališče moje, kako govorite duši moji: Zapústi goro vašo, tičica?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Ker glej, tisti krivični natezajo lok, pušico svojo pokladajo na struno, da streljajo v temì na pravične v srci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Ko se bodo celo stebri podirali, kaj naj počne pravični?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Gospod je v svetišči svetosti svoje, Gospod, katerega prestol je v nebesih, katerega oči vidijo, katerega trepalnice preiskujejo sinove človeške.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Gospod preiskuje pravičnega, krivičnega pa in siloljubnega sovraži srce njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Vsipal bode žarjavico nad krivične, ogenj in žveplo; in najviharnejši veter bode njih kupe delež.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Ker pravični Gospod ljubi, kar je pravično; pravičnega gleda obličje njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Načelniku godbe po osmini, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Daj rešenje, Gospod, ker minil je dobrodelnik; ker izginili so resnični izmed sinov človeških.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Prazno govoré drug z drugim, s priliznenimi ustnami, z vojnim srcem govoré.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Pokončal bode Gospod vse priliznene ustne, jezik visokobesedni;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Njih, ki govoré: Našega jezika pravica bode obveljala, ustne naše so v naši oblasti, kdo bi bil nam gospod?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Od zatiranja siromakov ubozih, od vpitja revežev vstanem skoraj, govori Gospod; pomagal bodem njemu, v katerega bode pihal žarjavico krivični.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 7, 'Besede Gospodove so čiste besede, srebro očiščeno v izbrani prsteni posodi, osnaženo sedemkrat.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 8, 'Ti, Gospod, ohrani jih; vsakega izmed njih brani tega rodu na veke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 9, 'Krivični hodijo okrog povsodi, ko se povzdiguje malopridna reč med človeškimi sinovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Doklej, Gospod? Bodeš li pozabljal me večno? Doklej bodeš skrival obličje svoje pred menoj?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Doklej naj skrivam naklepe svoje v srci svojem; žalovanje v prsih svojih podnevi? Doklej se bode spenjal sovražnik moj proti meni?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Poglej, usliši me, Gospod, moj Bog; razsvetli oči moje, da ne spavam v smrti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Da ne poreče neprijatelj moj: Premagal sem ga; ne radujejo se sovražniki moji, ko bodem omahnil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Ker jaz imam zaupanje v milost tvojo; raduje se naj moj duh v blaginji tvoji; prepeval bodem Gospodu, ko mi bode storil dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Načelniku godbe; Davidova. Nespametni govori v srci svojem: Ni ga Boga: pohujšujejo, ostudna dela doprinašajo, ni ga, da bi delal dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Gospod gleda z nebes na sinove človeške, da bi videl, je li kateri, ki bi bil razumen, ki bi iskal Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Vsak je odstopil, izpridili so se vsi vkup; ni ga, da bi delal dobro, enega samega ne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Ali si niso v svesti vsi, kateri delajo krivico, ker žró ljudstvo moje kruh jedóč, ne kličejo Gospoda?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Tu se preplašijo od groze, ker Bog je na strani pravičnemu rodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Naklep siromaka ubozega bodete osramotili, seveda! ker Gospod je zavetje njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Kdo naj dá rešenje sè Sijona Izraelu? Ko bode nazaj peljal iz sužnjosti ljudstva svojega krdelo, radoval se bode Jakob, veselil se Izrael.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Psalm Davidov. Gospod, kdo naj prebiva v šatoru tvojem; kdo naj stanuje na gori svetosti tvoje?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Kdor hodi pošteno in dela pravico ter govori resnico iz svojega srca;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Ne obrekuje z jezikom svojim, ne dela hudega bližnjemu svojemu, in ne sramoti svojega soseda:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'V očeh njegovih je zaničevan krivični, česti pa njé, ki se bojé Gospoda; ko je prisegel v škodo svojo, vendar ne gane;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Denarja svojega ne posoja na obresti, in darila ne prejema zoper nedolžnega; kdor tako ravna, ne omahne nikdar.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Odlična pesem Davidova. Reši me, Bog mogočni; ker k tebi pribegam:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Gospodu govoriš: Gospod si moj, blaga mojega ne bodeš hranil pri sebi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Svetim, ki so v deželi in veličastnim ga podeliš; na katerih je vse razveseljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Njim množijo bolečine kateri drugemu delé; daroval ne bodem njih krvavih daritev, ne jemal njih imen na ustne svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Gospod je delež pristave moje in mojega ljudstva; ti vzdržuješ osodo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Mérne vrvi so mi pale v preprijetnih krajih; tudi posestvo je sprelepo, katero me je doletelo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Blagoslavljal bodem Gospoda, kateri mi je dal sovèt; tudi ponoči me podučujejo obisti moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Predočujem si Gospoda neprestano; ker je na desnici moji, ne omahnem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Zatorej se veseli srce moje in raduje se slava moja; tudi meso moje prebiva brez skrbi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Ker duše moje ne bodeš pustil v grobu, ne pripustil ljubljencu svojemu, da vidi trohnobo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Naznanjaš mi življenja stezo; najslajših radosti obilost pred obličjem tvojim, na desnici tvoji vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Molitev Davidova: Čuj, Gospod, pravico, poslušaj vpitje moje; uho nagni molitvi moji brez ustnic zvijačnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Od obličja tvojega izidi pravica moja; oči tvoje naj gledajo, kar je pravično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Ko bodeš preiskal srce moje, obiskal ponoči, preskušal me, ne najdeš; kar mislim, ne prestopi mojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Pri delih človeških, po besedi ustnic tvojih opazujem steze silovitega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Ohrani korake moje na stezah svojih, da ne zaidejo moje noge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Jaz te kličem, ker me slišiš, Bog mogočni; nagni k meni uho svoje, poslušaj govor moj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Odloči milosti svoje, o ti, ki otimaš preganjalcev pribegajoče na desnico tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Hrani me kakor zenico v očesu; sè senco peroti svojih skrivaj me:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Zaradi krivičnih, ki me napadajo, sovražnikov mojih glavnih, ki me obdajajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Mast svojo masté, z usti svojimi govoré prevzetno:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Hojo našo zdaj obdajajo nam; oči svoje obračajo vpirajoč v tla.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Podoba je vsakega kakor leva želečega zgrabiti, in kakor mladega leva čepečega v zakotji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Vstani, Gospod, prehítí obličje njegovo; trešči ga, izpuli dušo mojo z mečem svojim krivičnemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Ljudém izpuli v roko svojo, Gospod, ljudém od svetá, katerih delež je v tem življenji, katerim trebuh polniš sè skrivnim zakladom svojim; sitijo se sinovi in preobilost svojo zapuščajo otrokom svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 15, 'Jaz bodem v pravičnosti videl obličje tvoje, sitil se bodem, ko se zbudim, s podobo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Načelniku godbe, Davida hlapca Gospodovega; kateri je govoril Gospodu té pesmi besede v dan, ko ga je bil rešil Gospod iz roke vseh sovražnikov njegovih, kakor iz roke Savlove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'In rekel je: Iz osrčja svojega bodem te ljubil, Gospod, moja krepost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Gospod, skala moja in grad moj in rešitelj moj; Bog mogočni moj, pečina moja, kamor pribegam, ščit moj in blaginje moje rog, višina moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Hvaljenega kličem Gospoda in rešujem se sovražnikov svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Obdajajo me smrtne bolečine in malopridnih hudourniki me strašijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Groba bolečine me obhajajo, smrtne zanke so mi na poti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'V stiski svoji kličem Gospoda, in do Boga svojega vpijem; iz svetišča svojega usliši moj glas, in vpitje moje predenj pride do ušes njegovih:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 8, 'In stresa se in giblje zemlja, in podloge gorâ se majó; stresajo se pa, ko se mu vname jeza.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 9, 'Dim se vali skozi nos njegov in ogenj požrešen iz ust njegovih; žarjavica goreča gre od njega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 10, 'In nagne nebo ter stopi dol, z mrakom pod svojimi nogami,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 11, 'In sedeč na kerubih leti, in plava na vétrovih perotih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 12, 'Temo si napravi v zavetje svoje, okolo sebe za šator svoj; temotne vode, gošče gornjih oblakov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 13, 'Od svita pred njim prehajajo gosti oblaki njegovi, toča in žarjavica ognjena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 14, 'Na nebesih grmi Gospod in z višave izhaja glas njegov, toča in žarjavica ognjena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 15, 'Tako proži pušice svoje, razsipa jih in strele meče ter jih podi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 16, 'Prikazujejo se tudi najnižje struge vodâ, in razgrinjajo se podloge vesoljne zemlje od hudovanja tvojega, Gospod, od sape tvojega nosú.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 17, 'Iz višine poseže ter me potegne gor, izvleče me iz mnogih vodâ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 18, 'Reši me neprijatelja mojega močnejšega, in sovražnikov mojih, ko so krepkejši od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 19, 'Srečujejo me ob času nadloge moje, tedaj mi je za palico Gospod:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 20, 'In izpelje me na prosto; reši me, ker me ima rad.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 21, 'Podeljuje mi Gospod po pravičnosti moji; po čistosti mojih rok mi povrača.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 22, 'Ker se držim potov Gospodovih, ter se ne obračam krivično od svojega Boga;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 23, 'Ker so vse sodbe njegove pred mojimi očmi; in postav njegovih ne odvračam od sebe:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 24, 'Ker sem pošten pred njim, in se varujem, da ne ravnam krivično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 25, 'Povrača mi Gospod po pravičnosti moji; po čistosti mojih rok pred njegovimi očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 26, 'Z dobrotljivim izkazuješ se dobrotljivega, s poštenim možem izkazuješ se poštenega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 27, 'S čistim kažeš se čistega, ali popačenemu nasprotuješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 28, 'Ker ti otimaš ljudstvo ubogo, prevzetne pa oči ponižuješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 29, 'Dà, svetilo moje razsvetljuješ; Gospod, moj Bog razjasnjuje moje temé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 30, 'S teboj namreč prodiram skozi krdelo, in z Bogom svojim preskakujem zid.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 31, 'Tega Boga mogočnega pot je poštena; govor Gospodov ves čist; ščit je vsem, kateri pribegajo k njemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 32, 'Ker kdo je Bog razen Gospod? in kdo skala razen naš Bog?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 33, 'Ta je Bog mogočni, ki me opasuje z močjo, in dela pošteno mojo pot:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 34, 'Storivši noge moje kakor jelenom, da me stavi na višino mojo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 35, 'Boja uči roke moje; tako da zlomi lok jekleni roka moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 36, 'Ker daješ mi ščit blaginje svoje, in desnica tvoja me podpira, in krotkost tvoja me povišuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 37, 'Hoji moji razširjaš prostor moj; in členki mojih nog ne omahujejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 38, 'Sovražnike svoje podim in dohajam jih; in ne povrnem se, dokler jih nisem uničil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 39, 'Zdrobim jih tako, da ne morejo več vstati, padajoč pod noge moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 40, 'Opasuješ me namreč z močjo za vojsko; pod me podiraš nje, ki se spenjajo zoper mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 41, 'In neprijateljev mojih tilnik mi podajaš; da ugonobim sovražnike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 42, 'Vpijejo, a ni ga, da jih reši; h Gospodu, a ne usliši jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 43, 'Zatorej jih razmeljem kakor prah pred vetrom; kakor blato na ulicah jih drobim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 44, 'Oproščaš me prepirov ljudstva; staviš me narodom na čelo; ljudstvo, katerega nisem poznal, služi mi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 45, 'Na sluh ušesa so mi pokorni; tujci se mi udajajo lažnjivo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 46, 'Tujci padajo in pritrepetavajo iz gradov svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 47, 'Gospod živi in blagoslovljena skala moja; zatorej naj se povišuje Bog blaginje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 48, 'Bog ta mogočni, ki mi daje maščevanje, in spravlja ljudstva pód me;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 49, 'Rešuje me sovražnikov mojih; tudi nad nje, ki se spenjajo zoper mene, povzdignil si me; možu silovitemu si me iztrgal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 50, 'Zatorej te bodem slavil med narodi, Gospod, in prepeval bodem tvojemu imenu:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 51, 'Da veliko blaginjo vsakoršno podeljuješ svojemu kralju, in izkazuješ milost maziljencu svojemu, Davidu in semenu njegovemu na veke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Nebesa oznanjajo slavo Boga mogočnega; in delo rok njegovih kaže njih razsežje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Dan dnevu bruha govorico, in noč noči kaže znanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Govorice nimajo, ne besed; in brez njih umé se njih glas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Po vsej zemlji gre njih oznanilo, do kraja vesoljnega sveta šle so njih govorice; odkar je solncu šator postavil na njih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Ker ono je kakor ženin, ki gre iz stanice svoje; raduje se kakor korenjak, ko se pripravlja na tek.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Od kraja nebá je vzhod njegov; in ték njegov do njihovih krajev; in nič ni, kar bi bilo skrito njegovemu žaru.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Nauk Gospodov je pošten, oživljajoč dušo; pričanje Gospodovo resnično, modrost daje nevednemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Zapovedi Gospodove so pravične, srce razveseljujejo; postava Gospodova čista, razsvetljuje oči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Sveti strah Gospodov je čist, vekomaj ostane; sodbe Gospodove zgolj resnica, pravične so vse:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Zaželene, bolj ko zlato, in to kakor zlato prečisto, premnogo, in slajše ko med, in to ko čisti med.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Tedaj je bil služabnik tvoj opominjan po njih; njih poslušati je velik dobiček.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, '(Zmote, kdo bi jih razumel?) Mene odveži skrivnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Potem iz trdovratnosti potegni služabnika svojega, da ne gospoduje v meni; tedaj bodem pošten in čist velike pregrehe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Po volji naj bodejo ust mojih besede, in srca mojega premišljevanje pred teboj; Gospod skala moja in rešitelj moj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Usliši te naj Gospod ob času stiske; na višavo naj te postavi ime Boga Jakobovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Pošlje naj ti pomoč iz svetišča, in sè Sijona naj te podpira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Dúha naj vse dari tvoje, in upepeli naj žgalno daritev tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Dá ti naj po srci tvojem, in izpolni naj vsak sklep tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Prepevajmo o blaginji tvoji; in v imenu Boga našega nosimo zastave; izpolni naj Gospod vse prošnje tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 7, 'Zdaj spoznavam, da Gospod brani maziljenca svojega, usliši ga z nebes svetosti svoje; po največji kreposti, blaginji desnice svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 8, 'Ti vóz, in oni kónj, mi pa se spominjamo imena Gospoda, Boga našega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 9, 'Oni se pripogibajo in padajo; mi pa vstajamo in stojimo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 10, 'Gospod, reši! kralj sam naj usliši nas ob času, ko ga bodemo klicali.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Načelniku godbe; psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Gospod, moči tvoje veseli se kralj, in blaginje tvoje kako se silno raduje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Željo srca njegovega mu daješ, in kar so ustne njegove govorile, ne odrékaš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Dà, prehitevaš ga z blagodari, na glavo njegovo pokladaš venec iz zlata prečistega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Življenja te je prosil, dal si mu; tudi dnî dolgost na vedno večne čase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Velika je slava njegova po blaginji tvoji; díko in veličastvo si položil nanj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Ker pripravil si mu blagoslove na vekomaj; razjasnil ga z radostjo od svojega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Ker kralj sam upa v Gospoda; zato v zaupanji na milost Najvišjega ne omahne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Z roko svojo dosežeš vse neprijatelje svoje; z desnico svojo dosežeš vse svoje sovražnike.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Narediš, da so kakor peč ognjena ob času srditega obličja tvojega; Gospod jih pogoltne v jezi svoji, kakor da jih ogenj uniči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Sad njih pokončaš sè zemlje, in njih seme izmed sinov človeških.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Ker nameravali so ti hudo; izmišljali so naklep: ne morejo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ker staviš jih kakor gomilo; na strune svoje pokladaš pušice ter jih streljaš proti njih obličjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Dvigni se, Gospod, v moči svoji; pojmo in prepevajmo o hrabrosti tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Načelniku godbe o prvi zarji; psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Bog moj mogočni, Bog moj mogočni, zakaj si me zapustil? daleč od blaginje moje, od stoka mojega besed?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Bog moj, zakaj me ne uslišiš, ko te kličem podnevi? in ponoči ni mi pokoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Saj si vendar svet, stanoviten, popolna hvala Izraelova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Tebi so zaupali očetje naši; zaupali so, in osvobodil si jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'K tebi so vpili, in oteti so bili, v té so zaupali in ni jih bilo sram.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Jaz pa sem črv, in ne mož; sramota ljudém in zaničevanje ljudstvu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Vsi, ki me vidijo, namrdavajo se mi; režé se, glavó majó:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'H Gospodu pribega, reši ga naj; otmè ga naj, ker ima veselje nad njim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Saj ti si, ki si me potegnil iz materinega telesa, storil si, da sem brez skrbi živel na prsih matere svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'K tebi sem bil zagnan od rojstva, od telesa matere moje bodi Bog moj mogočni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Ne bivaj daleč od mene, ko je blizu stiska, ko ni pomočnika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Obdajajo me junci mnogi, krepki junci Bazanski obsipljejo me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Žrelo svoje odpirajo zoper mene, kakor lev zgrabljiv in rujoveč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Kakor voda se razlivam, in vse kosti moje se razklepajo; srce moje je podobno vosku, taja se v osrčji mojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Moja moč je suha kakor čepinja, in jezik moj se prijemlje neba mojega, in devaš me v smrtni prah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Ker obdali so me psi; hudobnikov krdela so me obsula; prebodli so moje roke in noge moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Seštel bi lahko vse svoje kosti; oni gledajo, ozirajo se v mé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Oblačila moja delé med seboj, in za suknjo mojo mečejo kocko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Ti torej, Gospod, ne bivaj daleč, krepost moja, hiti na pomoč mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Otmi meča dušo mojo, psa edino mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Reši me žrela levovega, in rogov samorogov, uslišavši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Ime tvoje bodem oznanjal bratom svojim; sredi zbora bodem te hvalil:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Vi, ki se bojite Gospoda, hvalite ga; vse seme Jakobovo hvali ga; in boj se ga vse seme Izraelovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Ker ne zameta in ne zaničuje siromaštva siromakovega, in pred njim ne skriva obličja svojega; temuč ko vpije do njega, usliši ga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 26, 'O dobrotah tvojih bode hvala moja v zboru velikem; obljube svoje bodem opravljal v pričo njih, ki se ga bojé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 27, 'Jedli bodejo krotki in nasitili se; hvalili bodejo Gospoda, kateri ga iščejo; srce vaše bode živelo vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 28, 'Spomnijo se in povrnejo se h Gospodu vse meje zemlje, in priklonijo se pred teboj vse družine narodov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 29, 'Ker Gospodovo je kraljestvo samo, in gospostvo ima nad narodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 30, 'Jedli bodo in priklanjali se vsi zemlje bogatini; pred njim bodejo padali, katerikoli pojdejo dol v prah; kateri ni ohranil duše svoje v življenji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 31, 'Teh seme bode ga čestilo, prištevalo se bode Gospodu vsak čas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 32, 'Prihajali bodo in oznanjali pravico njegovo ljudstvu, ki se rodi, da je pravičen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Psalm Davidov; Gospod je pastir moj; slabo se mi ne more goditi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Na pašnikih travnatih skrbi da ležim, poleg tihih vodâ me vodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Pokojno dela dušo mojo, po pravice stezah me vodi, zavoljo svojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Tudi ko bi hodil po dolini smrtne sence, ne bal bi se zlega, ker ti si z menoj; šiba tvoja in palica tvoja tolažiti me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Pred menoj napravljaš mizo, sovražnikom mojim nasproti; z mazilom maziliš glavo mojo, kupa moja je polna do vrha.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Zgolj dobrota in milost bodeti me spremljale vse dnî življenja mojega; in pokojen bodem v hiši Gospodovi, dokler bodejo dolgi časi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Psalm Davidov; Gospodova je zemlja in česar je polna, vesoljni svet, prebivalci njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Ker sam jo je ustanovil nad morja, in nad reke jo utrdil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Kdo naj gre gor na goro Gospodovo, in kdo naj stoji na mestu svetosti njegove?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Kdor je nedolžnih rok in srca čistega; kateri ne dviga k ničemurnosti duše svoje, in ne priseza na goljufijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Ta dobiva blagoslov od Gospoda, in pravico od Boga blaginje svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Ta je zarod čestilcev njegovih, ki iščejo obličje tvoje, zarod Jakobov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Dvignite, vrata, glave svoje in dvignite se, večne duri, da vnide slave kralj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Kdo je ta slave kralj? Gospod prekrepki in premogočni; Gospod vojskovalec premogočni,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Dvignite, vrata, glave svoje, dvignite, pravim, večne duri, da vnide slave kralj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Kdo je ta slave kralj? Gospod vojnih krdél, on je slave kralj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Pesem Davidova: K tebi, Gospod, dvigam dušo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Bog moj, v té zaupam, naj se ne osramotim, sovražniki moji naj se ne radujejo nad mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Tudi kdor čaka tebe, naj se ne osramoti; osramoté se naj, kateri izdajalsko ravnajo po krivem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Pota svoja mi kaži, Gospod; steze svoje úči me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Daj, da hodim po resnici tvoji, in úči me; ker ti si Bog blaginje moje, tebe čakam ves dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Spomni se usmiljenja svojega, Gospod, in milosti svojih, da so od vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Grehov mladosti moje in pregreškov mojih ne spominjaj se; po milosti svoji spominjaj se me ti, zavoljo dobrote svoje, Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Dober in pravičen je Gospod: zatorej uči grešnike pot;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Dela, da hodijo krotki po pravici, in krotke uči pot svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Vse steze Gospodove so milost in zvestoba njim, ki hranijo zavezo njegovo in pričanja njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Zavoljo imena svojega, Gospod, bodeš torej prizanesel krivici moji, ker velika je.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Kakošen bode mož tisti, kateri se boji Gospoda, ki ga uči, katero pot naj izvoli?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 13, 'Duša njegova bode prenočevala v dobrem, in seme njegovo bode dedovalo deželo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 14, 'Skrivnost Gospodova biva pri njih, ki se ga bojé, in zaveza njegova, da po izkušnji priča zanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 15, 'Oči moje gledajo neprestano v Gospoda; ker on potegne iz mreže noge moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 16, 'Ozri se v mé, in milost mi stóri; ker samoten sem in ubožen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 17, 'Stiske srca mojega se razširjajo; iz nadlog mojih potegni me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 18, 'Poglej siromaštvo moje in težavo mojo; in odpusti vse grehe moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 19, 'Ozri se v sovražnike moje, ker močneji so; in s hudim sovraštvom me sovražijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 20, 'Reši dušo mojo in otmi me; naj se ne osramotim, ker pribegam k tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 21, 'Poštenost naj me brani in pravica, ker tebe čakam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 22, 'Reši, Bog, Izraela vseh zatiranj njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Pesem Davidova. Za sodnika mi bodi, Gospod, ker jaz hodim v poštenosti svoji, in v Gospoda zaupam, da ne omahnem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Izkušaj me Gospod, in preišči me; preglej obisti moje in srce moje;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Ker milost tvoja je pred mojimi očmi, in neprestano hodim v resnici tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Ne sedevam z ničemurnimi ljudmi in z licemérci se ne shajam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Hudobnikov zbor sovražim, in s krivičnimi ne sedevam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'V nedolžnosti umivam roke svoje, in oltar tvoj obhajam, Gospod,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Prepevajoč hvalno pesem, in oznanjajoč vsa čuda tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Gospod, prebivališče ljubim hiše tvoje, in mesto, šator slave.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Ne pridrúži grešnikom duše moje, in možem krvoželjnim mojega življenja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'V njih rokah je pregreha, desnica njih je polna daril podkupnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Jaz pa hodim v poštenosti svoji; reši me in milost mi stóri.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Noga moja stoji na ravnem, v zborih bodem blagoslavljal Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Pesem Davidova; Gospod je luč moja in blaginja moja, koga bi se bal? Gospod je življenja mojega moč, koga bi se plašil?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Vojskujejo se proti meni hudobniki, da pojedó moje meso, sovražniki moji in neprijatelji moji proti meni; oni se zgruzajo in padajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ko bi šatorišče stavili proti meni, ne bi se balo srce moje; ko bi se spela vojska zoper mene, bil bi brez skrbi za to.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Eno sem prosil Gospoda, tega samo želim: da naj sedevam v hiši Gospodovi vse dnî življenja svojega, da gledam lepoto Gospodovo in preiskujem v svetišči njegovem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ker skriva me v koči svoji ob času nadloge; skriva me v skrivnem kraji šatora svojega, dviguje me na skalo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Že se spenja glava moja nad sovražnike moje, stoječe okrog mene; da darujem v šatoru njegovem daritve z veselim hrupom, pojem in prepevam Gospodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Sliši me, Gospod, ko kličem z glasom svojim: in milost mi storí, usliši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Tvojo besedo: \"Iščite obličje moje,\" premišlja srce moje; obličje tvoje iščem, Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Ne skrivaj mi obličja svojega, ne obračaj se v jezi od svojega hlapca; pomoč moja si bil, ne zapusti me in ne ostavi blaginje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Ker oče moj in mati moja me zapuščata, Gospod pa me sprejme.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Uči me, Gospod, svoj pot, in vodi me po ravni stezi zavoljo njih, ki v mé preže.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Ne izdajaj me želji sovražnikov mojih; ker zoper mene stojé lažnjive priče, in ki pihajo silovitost;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Ko bi ne veroval, da bodem užival dobroto Gospodovo v deželi živečih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 14, 'Čakaj Gospoda, potolaži se, in pokrepčal bode srce tvoje; torej čakaj Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Pesem Davidova. Tebe, Gospod, kličem, skala moja; ne delaj se gluhega obrnen od mene, da ne postanem, ako bodeš nem, od mene obrnen, podoben njim, ki v grob gredó.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Čuj prošenj mojih glas, ko vpijem k tebi; ko molím roke svoje proti hramu tvoje svetosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Ne potegni me med hudobne in njé, ki delajo krivico; ki govoré mir z bližnjimi svojimi, hudobija pa biva v njih srci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Daj jim po njih delu, in po hudobnosti njih dejanj; po delu njih rók jim daj, povrni jim povračilo svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Ker ne menijo se za dela Gospodova, in za stvarjenje rok njegovih: podere jih, a postavi jih ne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Blagoslovljen Gospod, ker je uslišal prošenj mojih glas;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Gospod moč moja in ščit moj; njemu zaupa srce moje, in pomaga mi; zatorej se raduje srce moje, da ga slavim s pesmijo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Gospod je moč moja, in preblaga moč je Maziljenec njegov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Reši ljudstvo svoje, in blagoslovi svojo last; in pasi jih ter povzdigni jih na veke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Psalm Davidov. Dajajte Gospodu, sinovi mogočnih, dajajte Gospodu slavo in hvalo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Dajajte Gospodu slavo njegovega imena; priklanjajte se ter izkazujte čast Gospodu v diki svetosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Glas Gospodov čez vode, glas Boga mogočnega, slavnega grmi, glas Gospodov čez mnoge vode.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Glas Gospodov močan, glas Gospodov krasen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Glas Gospodov lomi cedre, Gospod podira tudi cedre na Libanu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'In dela, da skačejo kakor tele, Libanon in Sirijon, kakor mladič samorogov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Glas Gospodov kreše plamene ognjene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Glas Gospodov prešinja puščavo, prešinja puščavo Kadeško.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Glas Gospodov dela, da rodé košute, in listje otresa gozdom; ali v svetišči svojem izreka vso slavo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Gospod je sedel o potopu, in Gospod kralj sedi vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Gospod daje moč svojemu ljudstvu; Gospod blagoslavlja ljudstvo svoje z mirom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Psalm Davidov, pesem posvečevanja hiše njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Poveličeval te bodem, Gospod, ker si me povzdignil, in sovražnikom mojim nisi dal radovati se nad mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Gospod, Bog moj, ko sem vpil do tebe, ozdravil si me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Gospod, izpeljal si iz groba dušo mojo, ohranil me živega, da ne idem v grob.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Prepevajte Gospodu, katerim on deli milost, in slavite spomin svetosti njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Ko je bil trenotje v jezi svoji, pride življenje po dobroti njegovi; ako se zvečer oglasi jok, zjutraj petje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Ker jaz sem govoril v mirnosti svoji: Ne omahnem vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Gospod, po dobroti svoji si bil na goro postavil mojo moč; ko si skrival obličje svoje, bil sem zbegan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'K tebi sem klical, Gospod, in Gospoda sem prosil:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Kaj prida bode v krvi moji, ko pojdem dol v jamo? ali te bode prah slavil? bode li oznanjal resnico tvojo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Čuj, Gospod, in milost mi stórí; Gospod, bodi mi pomočnik.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Izpreobrnil si mi jok moj v ples; razpasal si raševnik moj in opasal me z radostjo:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Da ti prepeva slava in ne umolkne. Gospod, Bog moj, slavil te bodem vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'K tebi, Gospod, pribegam, naj se ne osramotim vekomaj; s pravico svojo osvobodi me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Nagni mi uho svoje, hitro me reši; močna skala mi bodi, trden grad, da se rešim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Ker skala moja si in trdnjava moja, torej zavoljo imena svojega vodi me in spremljaj me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Izpelji me iz mreže, katero so skrili zoper mene: ker ti si moja moč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'V roko tvojo izročam svoj duh; otél si me, Gospod, Bog mogočni, resnični.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Sovražim nje, ki česté ničemurnosti prazne; ker jaz zaupam v Gospoda,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Da se bodem radoval in veselil dobrote tvoje, ko se bodeš ozrl v siromaštvo moje, spoznal duše moje stiske,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'In ne izdal me sovražniku v roko, na široko postavil noge moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 10, 'Milost mi stórí, Gospod, ker v stiski sem; od žalovanja hira oko moje, duša moja in telo moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 11, 'Ker od žalosti peša življenje moje in leta moja od zdihovanja; od kazni krivice, katero trpim, hira krepost moja; in kosti moje ginejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 12, 'Pri vseh sovražnikih svojih sem v sramoto, in pri sosedih svojih jako, in strah znancem svojim; zagledavši me zunaj bežé od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 13, 'V pozabljenje me zagrebava srce, kakor mrtvega; jaz sem kakor orodje potrto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 14, 'Ker zasramovanje čujem od mnogih, strah okrog in okrog; posvetujoč se vkup zoper mene mislijo, kako bi prestregli dušo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 15, 'Jaz pa v té zaupam, Gospod, govoreč: Bog si moj;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 16, 'V rokah tvojih so časi moji; potegni me iz rok sovražnikov mojih in njih, ki me preganjajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 17, 'Daj, da sveti obličje tvoje nad tvojim hlapcem; reši me po milosti svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 18, 'Gospod, naj se ne osramotim, ker te kličem; osramoté se naj krivični, pogubé se v grob.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 19, 'Neme naj postanejo ustne lažnjive, katere govoré zoper pravičnega trdó, z napuhom in zaničevanjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 20, 'Kako obila je dobrota tvoja, katero hraniš njim, ki te česté; izkazuješ njim, ki pribegajo k tebi pred sinovi človeškimi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 21, 'Skrivaš jih v skrivališči pričujočnosti svoje pred móž napuhom; skrivaš jih v koči pred prepirom jezikov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 22, 'Blagoslovljen Gospod, ker mi izkazuje čudovito milost svojo; stavi me kakor v trdno mesto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 23, 'Jaz sem bil sicer rekel v naglici svoji; Iztrebljen sem izpred tvojih oči; vendar si slišal molitev mojih glas, ko semi vpil k tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 24, 'Ljubite Gospoda vsi, katerim izkazuje dobroto; Gospoda, ki varuje zveste, in povrača preobilno, dela reči veličastne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 25, 'Potolažite se, in pokrepčal bode srce vaše, vsi, ki upate v Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Davidova pesem ukovita: Blagor oproščenemu pregreška, kogar greh je poravnán.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Blagor človeku, kateremu Gospod ne všteva krivice, in katerega duh nima v sebi zvijače.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Ko sem molčal, starale so se kosti moje, v stoku mojem ves dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Ker podnevi in ponoči bila je težka nad mano roka tvoja; in sok moj najboljši preobračal se je v suše poletne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Greh svoj ti razodenem, in krivice svoje ne bodem pokrival (dejal sem). Izpovém se pregreškov svojih Gospodu, in ti si izbrisal kazen mojega greha.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Zavoljo tega bode te molil, komurkoli deliš milost, kader se zgodi; (o povodnji mnogih vodâ ne doidejo njega);');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Ti si zavetje meni; stiske me brani; s pesmami oproščenja me obdajaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Podučeval te bodem in kazal ti, po kateri poti bodeš hodil; svetoval ti bodem, v te vpirajoč svoje oko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ne bodite kakor konj, kakor mezeg, brez razuma, katerima je z uzdo in vajetom brzdati gobec, da se, ne približa tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Velike bolečine ima krivični; kdor pa ima zaupanje v Gospoda, njega obdaja milost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Veselite se v Gospodu in radujte, pravični; in prepevajte, vsi pošteni v srci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Prepevajte, pravični v Gospodu, poštenim se spodobi hvalno petje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Slavite Gospoda sè strunami, s citrami in desetostrunjem mu pojte.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Pojte mu novo pesem, krepko bijte na strune, da doni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Ker prava je beseda Gospodova; in stanovitno vse delo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Pravico ljubi in sodbo; milosti Gospodove polna je zemlja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Z besedo Gospodovo ustvarjena so nebesa, in z dihom ust njegovih vsa vojska nebeška.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Morske vode znaša kakor kup in v shrambe deva valove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Gospoda naj se bojé vse dežele, pred njim naj trepetajo vsi sveta prebivalci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Ker na besedo njegovo je, karkoli je, na zapoved njegovo postane.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Gospod uničuje narodov sklep, misli ljudstev podira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Sklep pa Gospodov ostane vekomaj, misli srca njegovega od roda do roda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Blagor narodu, katerega Bog je Gospod, ljudstvo, katero si je izvolil v last.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Z nebes gleda Gospod, vidi vse sinove človeške.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Z mesta prebivališča svojega gleda dol na vse zemlje prebivalce.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'In obrazovatelj tudi njih src, pazi na vsa njihova dela.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ni ga kralja, da bi se rešil z množico krdél; mogočni se ne otme z množico moči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Goljufiv je konj za rešitev in z množico moči svoje ne oprosti jezdeca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Glej, oko Gospodovo pazi na nje, kateri se ga bojé, na njé, kateri čakajo milosti njegove;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Da reši smrti njih dušo, in jih žive ohrani v lakoti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Duša naša čaka Gospoda; pomoč je naša in ščit naš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Ker v njem se raduje srce naše, kajti zaupamo njegovemu svetemu imenu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Milost tvoja, Gospod, bodi nad nami, kakor te pričakujemo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Pesem Davidova, ko je bil izpremenil lice svoje pred Abimelekom, in je bil odšel, ker ga je on podil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Blagoslavljal bodem Gospoda vsak čas; vedno bode hvala njegova v ustih mojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'V Gospodu se bode ponašala duša moja; čuli bodejo krotki ter se veselili;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Poveličujte Gospoda z menoj, in vkup povišujmo ime njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Iskal sem Gospoda in uslišal me je, in iz vseh strahov mojih me je rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Kateri gledajo vanj in pritekajo, obličja njih naj se ne osramoté, govoré naj:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Ta ubogi je klical, in Gospod je uslišal; in rešil ga je iz vseh stisek njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Šatorišče stavijo angeli Gospodovi okrog njih, kateri se ga bojé, in otme jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Pokusite in vidite, da je dober Gospod; blagor možu, kateri pribega k njemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Bojte se Gospoda, svetniki njegovi, ker stradanja ni njim, ki se ga bojé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Mladi levi beračijo in stradajo; kateri pa iščejo Gospoda, ne pogrešajo nobenega blaga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Dejte, sinovi, poslušajte me: strah Gospodov vas bodem učil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Kdo je ón mož, kateri se veseli življenja, ljubi dní, rad uživa dobro?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Varuj jezik svoj hudega, in ustne tvoje naj ne govoré zvijače.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Umikaj se hudemu in delaj dobro; išči mirú in hodi za njim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Oči Gospodove pazijo na pravične, in ušesa njegova na njih vpitje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Srdito pa je njim, ki delajo hudo, obličje Gospodovo, da iztrebi sè zemlje njihov spomin.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 18, 'Ko kličejo, sliši jih Gospod, in jih iz vseh njih stisek otima.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 19, 'Blizu je Gospod pobitim v srci; in potrte v duhu rešuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 20, 'Mnoge so pravičnega nadloge, ali iz njih vseh ga reši Gospod:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 21, 'Vse kosti njegovo ohrani, ena izmed njih se ne zlomi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 22, 'Krivične pa zadeva sè smrtjo nadloga, in kateri sovražijo pravičnega, pogubé se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 23, 'Gospod otima dušo hlapcev svojih, in ne pogubi se nobeden, ki pribega k njemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Pesem Davidova. Bojuj se, Gospod, zoper njé, ki se bojujejo z menoj; napadi jih, ki napadajo mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Zgrabi ščit veliki ali mali, in vstani v mojo pomoč:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'In potegni sulico, in prestrezi njé, ki me preganjajo: reci duši moji: Blaginja sem tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Osramoté se naj in z rudečico oblijó, kateri iščejo duše moje: nazaj naj se zapodé in zarudé, kateri mi nameravajo hudo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Bodejo naj kakor pleve pred vetrom, ko ga zažene angelj Gospodov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Temna bodi njih pot in prepolzka, in angelj Gospodov naj jih preganja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Ker po krivem mi skrivajo v jami mrežo svojo, po krivem kopljejo jamo duši moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Pride naj mu, da ne bode vedel, poguba, da ga vjame mreža njegova, katero skriva: v pogubo naj pade vanjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Tako naj se duša moja raduje v Gospodu, veseli se naj v blaginji njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Vse kosti moje naj govoré: Gospod, kdo je tebi enak? Siromaka otimaš iz rok močnejega od njega; siromaka, pravim, in ubožca iz rok njega, ki ga pleni?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 11, 'Priče vstajajo krivične; česar si nisem v svesti, terjajo od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 12, 'Hudo mi vračajo za dobro, zapuščenost duši moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 13, 'In vendar sem jaz, ko so bili bolni, v raševini za obleko, s postom pokoril dušo svojo, in molitev moja se je vračala v nedrije moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 14, 'Kakor k bližnjemu, kakor k bratu sem hodéval neprestano, kakor žalujoč po materi hodil sem sključen v črni obleki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 15, 'Ko pa pešam, zbirajo se in se radujejo; zbirajo se pri meni in se plazijo, da ne čutim; parajo obleko, in ne molčé:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 16, 'Med igralci šaljivci šegavi; sè svojimi zobmí režé proti meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 17, 'Gospod, doklej bodeš gledal? Reši dušo mojo njih pogube, mladih levov edino mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 18, 'Slavil te bodem v velikem zboru, med ljudstvom obilim bodem te hvalil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 19, 'Naj se ne radujejo nad menoj, kateri so mi neprijatelji iz krivih vzrokov; kateri me sovražijo po krivem, naj ne mežikajo z očesom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 20, 'Mirú namreč ne govoré, temuč zoper pokojne v deželi izmišljajo najhujše zvijače.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 21, 'In proti meni režé, govoreč: Prav, prav, oko naše vidi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 22, 'Vidiš, Gospod, ne mólči; Gospod, ne bivaj daleč od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 23, 'Zbúdi se in vstani na sodbo mojo; Bog moj in Gospod moj, na pravdo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 24, 'Sodi me po pravici svoji, Gospod Bog moj, in naj ne radujejo se nad mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 25, 'Naj ne govoré v srci svojem: Prav, duša naša; ne govoré naj: Pogoltnili smo ga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 26, 'Osramoté se naj in zarudé vkup, ker se veselé nesreče moje; sè sramoto naj se ogrnejo in nečastjo, kateri se povzdigujejo proti meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 27, 'Prepevali bodejo in se radovali, kateri se veselé pravice moje, in govorili bodejo vedno: Poveličan Gospod, ki se veseli mirú svojega hlapca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 28, 'In jezik moj bode oznanjal pravičnost tvojo, ves dan hvalo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Načelniku godbe; pesem hlapca Gospodovega, Davida.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Beseda pregrehe krivičnega je v srca mojega globočini: Pred očmi njegovimi ni strahu Božjega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Slepí se v svojih očéh, ko doseže krivico svojo, katero naj bi sovražil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Besede ust njegovih so prazne in zvijačne; rabiti jenja razum, da bi delal dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Ničemurnost misli v postelji svoji, stopa na pot, ki ni dobra: hudega ne zameta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Gospod, v nebesih je milost tvoja, zvestoba tvoja noter do gornjih oblakov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Pravica tvoja kakor največje gore, sodbe tvoje valovi veliki; ljudî in živali ohranjaš, Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Kako dražestna je milost tvoja, Bog, ko sinovi človeški pribegajo v senco peróti tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Preobilno se napolnjujejo z obilostjo hiše tvoje, in iz potoka svojih slasti jih napajaš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Ker pri tebi je življenja vir, v svetlobi tvoji uživamo svetlobo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Pomóli milost svojo njim, ki te spoznavajo, in pravico svojo pravičnim v srci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Ne zadeni me prevzetnega noga, in roka krivičnih naj me ne zapelje, da zaidem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Ko padejo hudodelniki, zaženó se tako, da ne morejo vstati.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Pesem Davidova. Ne razsrdi se zaradi hudobnih, ne zavidaj njih, ki delajo krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Ker hitro se pokosé kakor seno, in kakor nežne trave zelenje odpadejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Zaupaj v Gospoda in delaj dobro; prebivaj v deželi in v poštenosti se pasi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'In razveseljuj se v Gospodu, ki ti bode dal srca tvojega prošnje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Izróči Gospodu svojo pot in zaupaj vanj; on bode že storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Kakor luč bode pokazal pravičnost tvojo, in pravico tvojo kakor poldan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Zanašaj se na Gospoda in čakaj ga neprestano: ne razsrdi se zaradi njega, ki ima srečo na poti svoji; zaradi moža, ki doprinaša, kar misli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Odjenjaj od jeze, in pústí togoto, ne razsrdi se, da bi le hudo storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Ker hudobniki se bodejo iztrebili: čakajoči pa Gospoda dedovali bodejo sami deželo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'In še malo, in celo ne bode krivičnega: ko bodeš ogledoval mesto njegovo, ne bode ga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Krotki pa bodejo dedovali deželo, in radovali se bodejo v obilosti mirú.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ko misli krivični zoper pravičnega, in škriplje sè zobmí svojimi proti njemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Smeje se mu Gospod, ker vidi, da prihaja dan njegov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Meč naj so potegnili krivični in lok svoj napéli, da poderó ubozega in siromaka, da pobijejo poštene na potu:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Meč njihov predere njih srce, in zdrobé se njihovi loki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Dobro je vsakemu pravičnemu malo, bolje nego obilost mnogim krivičnim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Ker roke krivičnih se zdrobé, pravične pa podpira Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Gospod pozna čase poštenih, tako da bode posest njihova vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Osramoté se ne o hudem času; temuč nasitijo se o lakoti času,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Ko krivični poginejo in sovražniki Gospoda kakor kar je drazega v jagnjetih, kakor to mine v dim, minejo oni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Na pósodo jemlje krivični, a vrniti ne more; pravični pa je milosten in daruje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Ker blagoslovljeni po njem podedovajo deželo, prokleti pa po njem pogubé se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Gospod stavi stopinje možu, katerega poti se raduje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Ko pada, ne zvrne se; ker Gospod podpira roko njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Otrok sem bil, postaral sem se tudi, ali videl nisem pravičnege zapuščenega tako, da bi kruha iskalo seme njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Ves dan deli milost in posoja, in v blagoslovu je seme njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Odstopi od hudega, in delaj dobro; tako prebivaj vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Ker Gospod ljubi pravico, in ne zapusti njih, katerim je dobrovoljen; na veke se ohrani, seme pa krivičnih se iztrebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Pravični bodo podedovali deželo, in prebivali bodo večno v njej.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Pravičnega usta premišljajo modrost, in jezik njegov govori pravico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'V srci njegovem je postava njegovega Boga, noga njegova ne omahuje na hojah svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Krivični pa zalezuje pravičnega in želi ga umoriti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Gospod ga ne zapusti v roki njegovi, ne dovoli, da se obsodi, ko se sodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Pazi na Gospoda in drži se poti njegove: tedaj te povzdigne, da bodeš podedoval deželo, videl krivičnih pogubo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Videl sem krivičnega, ko je pognal z veliko močjo, in se razvijal kakor domače drevo zeleneče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Potem je minil, in glej, ni ga bilo več: ker iskal sem ga, a našel se ni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Opazuj poštenega, in glej pravičnega, konec tega moža je mir.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Grešniki pa se pogubljajo vsi vkup; konec krivičnih se iztrebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 39, 'Ker blaginja njih je od Gospoda, moč njih o času stiske.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 40, 'In pomaga jim Gospod ter otima jih; otima jih krivičnih ter jih ohranja, ker pribegajo k njemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Psalm Davidov za spomin.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Gospod, v srdu svojem ne dólži me, in v togoti svoji ne pokôri me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ker pušice tvoje so zasajene v mé, in nadme si spustil roko svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Nič celega ni na mesu mojem zavoljo srdú tvojega; mirú ni v mojih kostéh zavoljo greha mojega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Ker krivice moje presezajo glavo mojo, kakor težko breme; pretežke so, da bi jih prenašati mogel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Segnjile so in usmradile se bule moje, zavoljo nespameti moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Mučim se, krivim se presilno, ves dan pohajam v črni obleki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Ker drob moj je poln prisada, tako da ni nič celega na mesu mojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Oslabljen sem in potrt presilno; tulim od stokanja svojega srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Gospod, pred teboj je vse hrepenenje moje; in zdihovanje ni ti skrito.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Srce moje utriplje, zapušča me moja krepost, in luč mojih očî, tudi one niso v moji oblasti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Prijátelji moji in bližnji moji stojé nadlogi moji nasproti, in sorodniki moji stojé od daleč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Stavijo pa zanke, kateri iščejo duše moje: in kateri iščejo hudega meni, govoré nadloge in izmišljajo ves dan zvijače.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jaz pa jih ne slišim kakor gluh, in kakor nem ne odprem svojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Ampak sem kakor ón, ki ne sliši, in kateremu ní dokazov v ustih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Ker tebe čakam, Gospod; da me ti uslišiš, Gospod, Bog moj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Ker pravim: Naj se ne radujejo nad menoj; ko omahuje noga moja, naj se ne povzdigujejo proti meni,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Ako bodem jaz za omahnenje pripravljen, in bolečina moja bode vedno pred mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Ker krivico svojo oznanjam, skrbi me moj greh.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Neprijatelji pa moji krepčajo se živi, in množijo se, kateri me sovražijo iz krivih vzrokov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'In vračajoč hudo za dobro nasprotujejo mi, zato ker hodim za dobrim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ne zapústi me, Gospod, Bog moj; ne bivaj daleč od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 23, 'Hiti na pomoč mojo, Gospod, blaginja moja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Načelniku godbe Jedutunov, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Rekel sem: Pazil bodem na pota svoja, da ne grešim z jezikom svojim; uzdo bodem imel okrog svojih ust, dokler bode krivični pred menoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Umolknil sem bil molčeč, tih sem bil tudi dobremu; ali hujšala se je bolečina moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Ko pa se je vnemalo srce moje v meni, ko je v premišljevanji mojem užigal se ogenj, govoril sem z jezikom svojim:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Daj, da zvem, Gospod, konec svoj, kaj je mera mojih dní, zvem, kako sem trpežen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Glej, po dlan dolge si naredil dnî moje, in čas moj je kakor nič pred teboj, zares, prava ničevost je vsak človek, še tako trden.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Zarés, kakor senca mine človek, zares, zastonj tako ropotajo; zbira vsak, a ne vé, kdo bode to prejel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'A kaj še čakam, Gospod? up moj je v tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 9, 'Vseh pregreh mojih reši me, nespametnim na sramoto ne izpostavi me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 10, 'Umolknem, ne zinem, ker ti si storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 11, 'Odvrni od mene udarec svoj, od udarca roke tvoje jaz omahujem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 12, 'Ako bi s kaznimi po krivičnosti pokoril vsakega, uničil bi kakor mola, kar je vrednega v njem: zares, ničevost je vsak človek.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 13, 'Čuj molitev mojo, Gospod, in vpitje moje; uho nagni solzam mojim, ne delaj se gluhega; ker tujec sem pred teboj, naselnik kakor vsi očetje moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 14, 'Odstopi od mene, da se okrepčam: ko še ne odhajam, da me ne bode več.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Stanovitno sem čakal Gospoda, kateri je nagnivši se k meni slišal vpitje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'In izpeljavši me iz jezera viharnega, iz blatne luže, postavil je nogo mojo na skalo, utrdil korake moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'V usta moja je položil novo pesem, hvalno pesem našemu Bogu: videli bodo mnogi in bali se ter zaupali v Gospoda, govoreč:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Blagor možu, kateri stavi v Gospoda zaupanje svoje, ter se ne ozira v prevzetnike in lažnjivce.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Mnoga čuda svoja nam ti deliš, Gospod, Bog moj, in misli svoje za nas: nihče, ko jih pregledujem, ni tebi enak; če jih bodem oznanjal in pripovedoval, preštevilna so, da bi jih naštel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Daritve in darú se nisi veselil, ušesa si mi prebodel; žgalne žrtve in daritve za greh nisi zahteval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Tedaj sem rekel: Glej, tu sem; v zvitku knjige je pisano o meni:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Veseli me delati voljo tvojo, Bog moj; in postava tvoja je v mojem osrčji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Pravico oznanjam v zboru velikem; glej, ustnam svojim ne branim, Gospod, ti veš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Pravice tvoje ne skrivam v srci svojem: zvestobo tvojo in blaginjo tvojo pravim; ne prikrivam milosti tvoje in resnice tvoje velikemu zboru.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Ti, Gospod, ne odtezaj mi usmiljenja svojega; milost tvoja in resnica tvoja naj me hraniti vedno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Ker obdajajo me in napadajo nadloge brez števila; dohajajo me krivice moje tako, da pregledati ne morem; več jih je, ko glave moje làs; tudi srce moje me zapušča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Blagovoli me oteti, Gospod; na pomoč mojo hiti, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Osramoté se naj in z rudečino oblijó vsi vkup, ki iščejo duše moje, da jo pogubé; umaknejo se naj in onečastijo, kateri se veselé moje nadloge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Zapuščeni naj bodo za plačilo sramote svoje, kateri pravijo meni: Prav, prav!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Veselé se naj in radujejo v tebi vsi, kateri te iščejo; govoré naj vedno: Poveličuj se Gospod, kateri ljubijo blaginjo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Ubog sem res in potreben, ali Gospod misli name: pomoč si moja in rešitelj moj: Bog moj, ne múdi se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Blagor mu, kdor se spominja siromaka, govoreč: O času nadloge bode ga otél Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Gospod ga bode rešil, ohranil življenju; srečen bode na zemlji, in ne izdajaj ga želji sovražnikov njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Gospod naj ga podpira na postelji slabosti: vse ležišče njegovo vsled bolezni njegove preméni,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Ko govorim: Gospod, milost mi stóri, ozdravi dušo mojo, ker tebi sem grešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Sovražniki moji so slabo govorili o meni: Kdaj bode umrl in bode izginilo ime njegovo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Ko je tedaj prihajal obiskat me kdó, govorilo je laž srce njegovo; zbiralo si je krivico: šel je ven in právil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Vkup so šepetali zoper mene vsi sovražniki moji; zoper mene so izmišljali, kar bi mi bilo v zlo, govoreč:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Stvar silno malopridna tiči v njem globoko, in ker leži, več ne vstane.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Tudi mož, ki je živel v miru z menoj, v katerega sem zaupal, kateri je jedel mojo jed, vzdignil je peto proti meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Ti pa, Gospod, storí mi milost, in zbúdi me, da jim povrnem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Načelniku godbe med nasledniki Koretovimi; ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Kakor jelen koprni po vodnih potokih, tako duša moja koprni po tebi, Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Žejna je duša moja Boga, mogočnega, živega, govoreč: Kdaj se približam, da se prikažem pred obličjem Božjim?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Solzé moje so mi za hrano podnevi in ponoči; ko se mi pravi vsak dan: Kje je, tvoj Bog?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'To mi je v mislih, ko izlivam v sebi dušo svojo, da bi se bil izprehajal v krdelu, hodil z njimi noter do hiše Božje z glasom petja in hvale, v praznični množici.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Kaj si pobita, duša moja, in tako ropočeš v meni? Upaj v Boga, ker še ga bodem slavil in vso blaginjo njegovega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Bog moj, pobita je v meni duša moja; zatorej se spominjam tebe iz dežele Jordanove in Hermonske, z male gorice.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Brezno kliče brezno o slapov tvojih glasu; vse vodé tvoje in valovi tvoji pridirajo in valé se čez me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Podnevi pošlje Gospod milost svojo, in ponoči hvalno pesem svojo k meni; v molitvi svoji k Bogu mogočnemu življenja mojega prebijem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Govoril bodem Bogu mogočnemu, skali svoji: Zakaj me pozabljaš? zakaj hodim žalujoč zaradi zatiranja sovražnikovega?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Suhe kosti moje napadajo, sramoté me sovražniki moji, govoré mi vsak dan: Kje Bog je tvoj?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Kaj si pobita, duša moja, in kaj tako ropočeš v meni? Upaj v Boga, ker še ga bodem slavil, vso blaginjo obličja mojega in mojega Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Maščuj me, Bog, in prevzemi pravdo mojo; ljudstva hudobnega, moža zvijačnega in krivičnega reši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Ker ti si Bog moči moje, zakaj bi me zamétal? zakaj bi žalujoč hodil neprestano zaradi zatiranja sovražnikovega?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Pošlji luč svojo in resnico svojo, oné naj me spremljati, pripeljati naj me na goro svetosti tvoje, in v šatore tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Da stopim pred oltár Božji, pred Boga mogočnega, veselje radosti moje, in te slavim sè strunami, o Bog, Bog moj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Kaj si pobita, duša moja, in kaj tako ropočeš v meni? Upaj v Boga, ker še ga bodem slavil, vso blaginjo obličja mojega in mojega Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Načelniku godbe med nasledniki Koretovimi; ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, '0 Bog, z ušesi svojimi smo slišali, očetje naši so nam pravili, káko delo si storil o njih časih, časih nekdanjih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Z roko svojo si izgnal narode in naselil njé: pokoril si ljudstva in razširil njé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Niso namreč z mečem svojim dobili dežele v oblast, in njih dlan ni jim dala blaginje; nego desnica tvoja in dlan tvoja in obličja tvojega luč; ker blagovoljen si jim bil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ti sam si kralj moj, o Bog; pošlji vsakoršno blaginjo Jakobu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'S teboj bodemo z rogom udarili sovražnike svoje; z imenom tvojim bodemo pogazili njé, ki se spenjajo v nas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Ker na lok svoj se ne zanašam, in meč moj ne bode me rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ko nas bodeš otél neprijateljev naših, in osramotil sovražnike naše,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Hvalili bodemo ves dan Boga, ime tvoje bodemo slavili vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'In vendar si nas zavrgel in onečastil, ker nisi hodil z našimi vojskami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Storil si, da smo se umaknili sovražniku, in neprijatelji naši si plenijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Predal si nas kakor drobnico za hrano, in med ljudstva si nas razkropil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Prodal si ljudstvo svoje za malo, in povišal nisi cene njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Izpostavil si nas v sramoto sosedom našim, v zasramovanje in zasmehovanje njim, ki nas obdajajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Za pregovor si nas postavil ljudstvom, v majanje z glavo med narodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Ves dan mi je nečast moja pred očmi, in obličja mojega sramota me pokriva;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Zaradi glasú zasramovalca in preklinjalca; zaradi sovražnika in maščevalca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Vse to nas je zadelo, in vendar te ne zabimo; in lažnjivo se ne vedemo zoper zavezo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Ne odmika se srce naše, in stopinja naša ne zavija v stran od steze tvoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Če tudi si nas potrl v kraj sômov in pokril nas z mrtvaško senco.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Ako bi bili pozabili imena Boga našega, ali razpeli roke svoje proti bogu mogočnemu tujemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Ali bi ne bil Bog tega preiskal? Ker on pozná srca skrivnosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Ali zavoljo tebe nas pobijajo vsak dan; cenijo nas kakor drobnico za klanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Zbúdi se, zakaj bi spal, Gospod? vstani, ne zametaj nas na večno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Zakaj bi skrival obličje svoje, pozabljal nadloge naše in stiske naše?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Ker v prah je ponižano življenje naše, tál se tišči trebuh naš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Vstani na pomoč nam, in reši nas zavoljo milosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Načelniku godbe med nasledniki Koretovimi, na šestero strun, prijateljic pesem ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Iz srca mojega vre dobra beseda; pel bodem pesmi svoje o kralji, z jezikom svojim in peresom, ročen pisar.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Mnogo lepši si ustvarjen od sinóv človeških; miloba je razlita po ustnah tvojih; zatôrej te je Bog blagoslovil vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Meč svoj opaši okolo ledja, o premočni; meč slave svoje in dike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'In z diko svojo srečno jahaj z besedo resnice, in izrekaj pravico, in stavi si spomenike sè strašnimi deli desnice svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Z ostrimi pušicami tvojimi bodo padala pód te ljudsta, po volji bodo padali sovražniki kraljevi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Prestol tvoj, o Bog, je na večne čase; žezlo pravično je žezlo tvojega kraljestva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Ljubiš pravico, in krivico sovražiš; zatorej te je pomazilil Bog, Bog tvoj z oljem veselja pred tvojimi tovariši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Mira in aloe in kasija so vsa oblačila tvoja, ko izhajaš iz svetišč slonokoščenih, pred njimi, ki razveseljujejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Hčere kraljeve so med dragimi tvojimi; žena tvoja je postavljena tebi na desno z odličnim zlatom Ofirskim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Čuj, hči, in glej, in nagni uho svoje, ter pozabi ljudstva svojega in hiše očetove svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'In radoval se bode kralj lepote tvoje; in ker je kralj tvoj, pokloni se njemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Tedaj bodejo hčere Tirske z darilom molile obličje tvoje, bogati med ljudstvom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Vsa čestita je notri hči kraljeva, v obleki predelani zlatom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'S Frigijskimi ogrinjali nesó jo h kralju; device prijateljice za njo peljejo se k tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Vodijo jih z največjim veseljem in radovanjem, stopajo v grad kraljevi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Na mestu roditeljev tvojih bodejo sinovi tvoji: za prvake jih postaviš po vsej deželi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Oznanjal bodem ime tvoje v vsaki dobi; zatorej te bodejo slavila ljudstva na vedno večno čase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Načelniku godbe med nasledniki Koretovimi, po visoki godbi, hvalna pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Bog nam je zavetje in moč; pomoč v stiskah najkrepkejša.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Zato bi se ne bali, ako bi se premaknila zemlja, ali ko bi se gore pogreznile v globočino morja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Šumele bi, kalile se vodé njih vseh, gibale se goré od njegovega vzdigovanja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Reka, potoki njeni razveseljujejo mesto Božje, kraj presveti, Najvišjega prebivališče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Bog je v sredi njegovi, ne gane se; Bog mu pomaga rano zjutraj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Ko hrumé narodi, gibljejo se kraljestva, oglasi se on, taja se zemlja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Gospod vojnih krdel je z nami, grad je nam Bog Jakobov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Pridite, glejte dela Gospodova, kako razgraja po zemlji!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Vojske mirí noter do skrajnosti zemlje, lok lomi in sulico krši, vozove sežiga z ognjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Govoreč: Stojte in spoznajte, da sem jaz Bog; da se bodem poveličeval med narodi, poveličeval na zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Gospod vojnih krdél je z nami, grad nam Bog Jakobov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Načelniku gódbe; med nasledniki Koretovimi, psalm.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Vsa ljudstva ploskajte z roko, ukajte Bogu z donečim glasom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Ker Gospod najvišji, čestiti, kralj velik je nad vso zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'V hlev goni ljudstva, v naš kraj, in narode v kraj naših nóg.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Odbira nam posestvo naše, diko Jakoba, katerega ljubi nad vse.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Gor gré Bog z veselim glasom, Gospod s trombe bučanjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Prepevajte Bogu, prepevajte; prepevajte kralju našemu, prepevajte!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Ker vse zemlje kralj je Bog, prepevajte s pesmijo ukovito!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Bog kraljuje nad narodi; Bog sedí na prestolu svetosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Radovoljni se zbirajo iz ljudstev, ljudstvo Boga Abrahamovega, ker Božje so hrambe dežele; silno je vzvišen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Pesem in psalm naslednikom Koretovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Velik je Gospod in hvaljen silno, v mestu Boga našega, na gori svetosti svoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'V lepoti kraja, veselji vse zemlje, na gori Sijonski, na severni strani v mestu kralja vélikega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Bog v dvorih njegovih spoznava se za grad.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Ker, glej, sešli so se kralji, šli so vkup.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Sami so videli, vkup so strmeli, zmedli so se, izbežali urno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Trepet jih je obšel tam, bolečina kakor porodnico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Z burjo razbijaš ladije morske.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Kakor smo slišali, tako smo videli v mestu Gospoda vojnih krdél, v mestu Boga našega; Bog ga utrjuje na veke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Milost tvojo premišljamo, o Bog, sredi tvojega svetišča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Kakor ime tvoje, tako je slava tvoja noter do krajev zemlje; pravice je polna desnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Veselí se naj gora Sijonska, radujejo se hčere Judove zavoljo sodeb tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Obhajajte Sijon, in obdajajte ga; štejte stolpe njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Upirajte misli svoje na trdnjavo, povzdignite oči k dvorom njegovim, da oznanjate prihodnjemu rodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ker ta je naš Bog na vedno večne čase; ta nas bode vodil noter do smrti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Načelniku godbe med nasledniki Koretovimi, psalm.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Čujte to, vsa ljudstva, poslušajte, vsi sveta prebivalci:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Nizki in visoki; bogatin in siromak enako.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Usta moja bodejo govorila razno modrost, in srca mojega premišljevanje mnogotero razumnost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Uho svoje nagnem k priliki, na strunah bodem razodeval uganko svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Kaj bi se bal o hudem času, da me ne obdá sledóv mojih krivica,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Njih, ki zaupajo v mogočnost svojo, in se ponašajo v obilosti svojega bogastva?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Brata nikakor ne more odkupiti nihče, ne dati Bogu odkupnine njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, '(Drag namreč je njih življenja odkup, dà, ni ga vekomaj!)');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Da bi živel še večno, ne izkusil trohnobe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Vidi namreč, da mrjó modri, enako pogine nespametni in neumni, in drugim pušča bogastvo svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Menili so, da se hiše njih stavijo za veke, prebivališča njih za vse rodove, ko so jih imenovali po svojih imenih po deželah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'In vendar človek v časti ne bode ostal; podoben postane živalim, ki poginejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Ta je njih pot, njih upanje; in nasledniki njih odobravajo njih usta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Kakor živino pasla jih bode smrt razpostavljene v grobu, dokler jim gospodujejo pravični tisto jutro, in obliko njih pokonča pekel, iz prebivališča njegovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Ali Bog bode rešil dušo mojo groba, ko me bode sprejel mogočno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Ne bój se, ko kdo bogat postane, ko se pomnoži domača slava njegova;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Ker v smrti ne vzame nič tega sè seboj; za njim ne pojde slava njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Ko bode blagoslavljal dušo svojo v življenji svojem, in te bodejo slavili, ker si privoščiš:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Da pride noter do dobe očetov svojih, vekomaj vendar ne bodejo uživali luči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Človek, ki je v čisli a ni razumen, podoben je živini, katera pogine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Psalm Asafu; Bog mogočni, Bog Gospod govori in kliče zemljo od vzhoda solnčnega do zahoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Sè Sijona, najvišje lepote, proseva Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, '(Pridi, naš Bog, in ne delaj se gluhega); ogenj razsaja pred njim, in silno viharno je okrog njega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Nebesa kliče od zgoraj, in zemljo, da sodi ljudstvo svoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Zberite mi jih, katerim sem delil milost, kateri so storili zavezo z menoj po daritvi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Ko so nebesa oznanjala pravico njegovo, da je Bog sodnik,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Čuj, ljudstvo moje, in govoril bodem, Izrael, in na pričo te klical; Bog, Bog naj bodem tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Ne zavoljo daritev tvojih te bodem svaril, da naj bodejo žgalne daritve tvoje vedno pred menoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Ne sprejmem iz hiše tvoje junca, kozličev iz tvojih ograj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Ker moja je vsaka gozdna zver, živali v gorah tisoč,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Vse tiče gorske poznam, in živali poljske so v moji oblasti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 12, 'Ko bi bil gladen, ne rekel bi tebi; ker moja je zemlja vesoljna in njena obilost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 13, 'Ali živim o mesu krepkih juncev, ali pijem kozlov kri?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 14, 'Hvalo daruj Bogu, in najvišjemu opravljaj obljube svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 15, 'In kliči me o času stiske; rešil te bodem, da me čestiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 16, 'Krivičnemu pa pravi Bog: Kaj da naštevaš zapovedi moje in jemlješ zavezo mojo v svoja usta?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 17, 'Ker ti sovražiš poštenje, in besede moje si vrgel zá se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 18, 'Kakor hitro vidiš tatú, sprijazniš se z njim; in s prešestniki je delež tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 19, 'Usta svoja rabiš za húdo, in z jezikom svojim spletaš zvijačo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 20, 'Sedé obrekuješ svojega brata, sina matere svoje sramotiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 21, 'Ko si to počel, delal sem se gluhega; zato meniš, da sem prav tebi podoben: svarim te in govorim ti v óči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 22, 'Pázite vendar na to vi, ki zábite Boga, da ne zgrabim in ga ne bode, da bi rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 23, 'Kdor daruje hvalo, česti me, in kdor uravnava pot, storil bodem, da uživa blaginjo Božjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 24, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Načelniku godbe, psalm Davidov,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Ko je prišel k njemu Natan prerok, potem ko se je bil sešèl z Betsebo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Milosten mi bodi, o Bog, po dobroti svoji; po obilosti svojega usmiljenja izbriši pregrehe moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Dobro me operi krivice moje, in greha mojega očisti me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Ker pregrehe svoje jaz spoznavam, in greh moj biva mi vedno pred očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Tebi, tebi samemu sem grešil, in storil kar se zlo vidi v tvojih očeh; da se opravičiš v govorih svojih; čist si, kader ti sodiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Glej, v krivici sem storjen in v grehu me je spočela mati moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Glej, resnice se raduješ v osrčji; in skrivaj si mi razodél modrost svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Očisti me z isopom, da bodem čist; operi me, da bodem bel nad sneg.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Stóri, da čujem veselje in radost, radujejo se kosti, katere si potrl.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Skrij srdito obličje svoje grehom mojim, in vse krivice moje izbriši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Srce mi čisto ustvari, Bog, in duh krepak ponovi v meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Ne zavrzi me izpred svojega obličja; in svojega svetega duha ne jemlji od mene nazaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Daj mi nazaj veselje blaginje svoje; in z duhom blagodušnosti podpiraj me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Učil bodem krivičnike pota tvoja, da se grešniki povrnejo k tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Reši me krvi, o Bog, Bog blaginje moje; jezik moj naj poje pravico tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Gospod, odpri moje ustne, in usta moja bodejo oznanjala hvalo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Ker ne veseliš se daritve; nočeš, da dajem žgalni dar.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Daritve Božje so duh potrt; srca potrtega in pobitega, o Bog, ne zametaš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Oblagodari po dobri volji Sijon; sezidaj zidovje Jeruzalemsko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Tedaj se bodeš veselil daritev pravice, žgalnih in celih daritev; tedaj bodo pobožni pokladali junce na tvoj oltar.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Načelniku godbe, pesem Davidova ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Ko je Doeg Idumejec prišel in naznanil Savlu ter rekel mu: David je obiskal hišo Abimelekovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Kaj se šopiriš v hudobi, o mogočni? Milost Boga mogočnega trpi vsak dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Bridkosti izmišljene napravljaš z jezikom svojim; podoben je ostri britvi, ti zvijače snovatelj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Hudo ljubiš bolj ko dobro, laž bolj ko govoriti pravico, presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Ljubil si vse besede pogubne, jezik zvijačen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Tudi to Bog mogočni podere na vekomaj; zgrabi te in izdere iz šatora; in s kórena te izpuli iz dežele živečih, presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'To bodejo videli pravični v Božjem strahu, in njemu se smijali:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Glej onega moža, ki si ni bil vzel Boga za brambo; nego zanašal se je na bogastva svojega obilost, in utrjal se v hudobi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Jaz pa, kakor oljka zeleneča v hiši Božji, zaupam milosti Božji na vedno večne čase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Slavil te bodem vekomaj, ker si storil to; in čakal bodem imena tvojega, ker si dober, pred njimi, katerim deliš milost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Načelniku godbe na piščal; pesem Davidova ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Nespametni govori v srci svojem: Ni ga Boga; pohujšujejo in ostudno krivico doprinašajo, ni ga, da bi delal dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Bog z neba gleda dol na sinove človeške, da bi videl, je li kateri, da bi bil razumen, da bi iskal Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Vsak je odstopil, izpridili so se vsi vkup: ni ga, da bi delal dobro, ne enega samega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Ali si niso v svesti, kateri delajo krivico, ker žró ljudstvo moje kruh jedóč, ne kličejo Boga?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Tam se preplašijo od groze, kjer ni groze; ker Bog razsuje kosti vsakega, kateri ima šatorišče svoje zoper tebe; osramotiš jih, ker Bog jih zameta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'O kdó naj dá blaginjo sè Sijona Izraelu? Ko bode nazaj peljal iz sužnjosti ljudstva svojega krdelo, veselil se bode Jakob, radoval se Izrael.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Načelniku godbe na strune; pesem Davidova, ukovita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Ko so prišli Zifejci in rekli Savlu: Ali ne tiči David pri nas?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Bog, zavoljo imena svojega reši me, in po kreposti svoji potegni se zame.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Bog, čuj molitev mojo, uho nagni besedam mojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Ker tujci spenjajo se proti meni in silovitniki iščejo življenje moje; Boga nimajo pred očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Glej, Bog mi pomaga, Gospod je med njimi, ki podpirajo življenje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Sovražnikom mojim vrni tisto zlo, po resničnosti svoji jih pokončaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Obilo ti bodem daroval; slavil bodem ime tvoje, Gospod, ker je dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Ker reši me vsake stiske, in sovražnike moje gleda moje oko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Načelniku godbe na strune, pesem Davidova ukovita,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Sliši, Bog, molitev mojo, in prošnji moji se ne skrivaj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Ozri se v mé in usliši me; glasno jokam v premišljevanji in zdihujem:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Zavoljo glasú sovražnikovega, zavoljo krivičnega stiske; ker v mé obračajo krivico, in srditi me preganjajo sè srčnim sovraštvom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Srce moje me boli v meni, in smrtni strahovi me obhajajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Strah in trepet me napada, in groza me pokriva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Tako da pravim: O da bi mi dal kdó perot kakor golobu; zletel bi, kjer bi mogel prebivati.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Glej, kar najdalje bi pobegnil, prebivat v puščavi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Hitreje bi pobegnil od vetra viharnega, od vrtinca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Pogúbi, Gospod, razdeli njih jezik; ker silovitost in prepir vidim v mestu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Podnevi in ponoči ga obdajajo na zidovji njegovem; in krivica in hudobnost sta sredi njega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Težave so sredi njega, in ne umakneta se z ulic njegovih goljufija in zvijača.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Ker ne nasprotnik me sramotí, to bi prenašal; ne sovražnik moj se spenja proti meni, njemu bi se skril:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 14, 'Temuč tí, človek, meni enak, vodnik moj in znanec moj,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 15, 'Ki sva skupaj sladkó se posvetovala, v hišo Božjo hodila z množico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 16, 'Napadla jih bode smrt terjalka, živi pogreznejo se v grob; ker hudobija je, kjer bivajo oni, v njih sredi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 17, 'Jaz bodem klical Boga, in Gospod me bode rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 18, 'Zvečer in zjutraj in o poludné bodem premišljal in stokal, dokler ne bode slišal mojega glasu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 19, 'Rešil je življenje moje, da se ne vojskujejo zoper mene, postavil ga v mir; ko so z mnogimi krdeli vojskovali se, bili so poleg mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 20, 'Slišal bode Bog mogočni in jih zarotil, kakor ostane vekomaj; v katerih ni prememb in se ne bojé Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 21, 'Roko svojo steza nad njé, ki živé v miru med seboj, oskrunja zavezo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 22, 'Sladke so, maslene besede njegove, a vojska tiči v njegovem srci; mehkeji od olja so njegove besede, ali goli meči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 23, 'Nad Gospoda zváli, karkoli ti dá, in on te bode podpiral; nikdar ne pripustí pravičnemu, da omahne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 24, 'Ti torej, Bog, pahneš jih v jamo gnjilobe: ljudje krvoločni in zvijačni ne doživé dní svojih polovice, jaz pa bodem tebi zaupal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Načelniku godbe, o duši, ki silo trpi od tujcev krdela, odlična pesem Davidova, ko so ga prijeli Filistejci v Gatu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Milosten mi bodi, Bog, ker rohneč me preganja človek, ves dan me stiska oblegovatelj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Rohné zalezovalci moji vés dan, ker mnogo jih je; z višave naj mi pomagajo borilci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Ko se bodem bal, zaupal bodem v tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'V Bogu bodem hvalil besedo njegovo; v Boga bodem zaupal, ne bodem se bal: Kaj naj bi mi storilo meso?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Ves dan žalijo mojo stvar; zoper mene merijo vse njih misli v hudo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Zbirajo, skrivajo se oni; na moj sled prežé, kakor ki iščejo življenje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Poleg krivičnosti jim stóri, v jezi pahni ljudstva, Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Ti imaš sešteto tavanje moje; v meh svoj deni vsako solzo mojo, ali bi jih ne imel seštetih?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Tedaj se povrnejo sovražniki moji nazaj; tisti dan, ko bodem vpil: To vém, da mi bode Bog na strani.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'V Bogu bodem hvalil besedo, v Gospodu hvalil besedo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'V Boga zaupam, ne bodem se bal; kaj bi mi storil človek?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 13, 'Z menoj bodejo, o Bog, obljube tvoje; zahvaljeval se bodem tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 14, 'Ker dušo mojo otimaš smrti; ali bi ne rešil nóg mojih padca? da neprestano hodim pred Bogom v tega življenja luči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Načelniku godbe: \"Ne pogubi\", Davidova pesem odlična, ko je bežal pred Savlom v brlog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Milosten mi bodi, Bog, milosten mi bodi; ker k tebi je pribežala duša moja, in v senco peroti tvojih hočem pribežati, dokler ne minejo težave.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Klical bodem Boga najvišjega, mogočnega, ki zvršuje za me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Poslal bode z nebes rešit me, osramotil bode njega, ki me rohneč preganja silovito. Poslal bode Bog milost svojo in resnico svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Jaz sem med levi groznimi, med požigalci ležim, med ljudmi, katerih zobje so sulice in pušice, in jezik njih je oster meč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Povišaj se nad nebesa, o Bog; nad vso zemljo v slavi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Mrežo so bili nastavili stopinjam mojim; potlačil je bil dušo mojo; jamo so bili skopali pred menoj, vanjo padajo silno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'S povzdignenim srcem svojim, o Bog, s povzdignenim srcem bodem pel in prepeval:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Vstani, slava moja, vstanite brenklje in strune, budil bodem sè zarijo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Slavil te bodem med ljudstvi, Gospod; prepeval med narodi;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Velika je do nebés milost tvoja, in noter do gornjih oblakov resnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Povišaj se nad nebesa, o Bog; nad vso zemljo v slavi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Načelniku godbe: \"Ne pogubi\"; Davidova pesem odlična.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Ali zares, o krdelo, govorite pravico? po pravici sodite, sinovi človeški?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Ne, celo iz srca počenjate krivice; v tej deželi tehtate rok svojih silovitost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'V stran zavijajo krivični od rojstva; tavajo od materinega telesa laž govoreč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Strup imajo podoben kačjemu strupu; kakor gada gluhega, ki si maši uho svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Kateri ne posluša glasú mrmrajočih, njega, ki zna zagovarjati jako.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'O Bog, zdróbi jim zobe v njih ustih; mladih levov kočnike poderi, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Stopé se naj kakor voda, odidejo naj neprestano; njemu, ki napenja pušice svoje, izpremené se naj kakor v klasje pušice.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Kakor polž, ki se topi, bode naj vsak, kakor žene splav, kakor ki niso videli solnca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Ko se ne bode še čutilo trnje vaše, trnje ščipkovo, tako zeleno kakor suho podrl bode vse.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Radoval se bode pravični, ko bode videl maščevanje; noge svoje bode umival v krivičnega krvi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'In človek poreče: Vendar ima sad pravični, vendar je sodnik na zemlji!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Načelniku godbe: \"Ne pogubi\"; Davidova pesem odlična; ko je bil poslal Savel može, ki so ogledavali hišo njegovo, da bi ga umorili.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Reši me sovražnikov mojih, moj Bog; nad nje, ki se spenjajo v méne, povzdigni me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Reši me njih, ki delajo krivico, in ljudî krvoločnih otmi me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Ker, glej, življenje moje zalezujejo, shajajo se zoper mene krepki, brez hudobije moje, brez greha mojega, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Brez krivice moje se zbirajo in pripravljajo: vstani meni naproti in ozri se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Ti torej, Gospod, Bog vojnih krdél, Bog Izraelov, zbúdi se, obiskat vse one narode: ne bodi milosten nikomur, ki dela krivico, nezvesto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Povračajo se zvečer; bevkajo kakor pes, in obdajajo mesto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Glej, bljujejo z usti svojimi, z mečem na ustnah svojih; ker kdo sliši? pravijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Ti pa, Gospod, bodeš se jim smijal, zasmehoval bodeš vse tiste narode.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Ko ima on moč, gledal bodem v té, ker Bog je moj grad.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Bog milosti moje bode me prestregel; Bog storí, da bodem gledal sovražnike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Ne pobij jih, da ne pozabijo rojaki moji; izženi jih s krepostjo svojo, in pahni jih dol, ščit naš, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Greh njih ust je njih ustnic beseda; ko bodejo vjeti v napuhu svojem, tedaj naj oznanjajo od prekletstva, tedaj od slabosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Pokončaj v srdu, pokončaj, da jih ne bode več; vedó naj, da Bog gospoduje v Jakobu do mej zemlje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Ko se povračajo zvečer, bevkajo naj kakor pes, in obdajajo mesto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Sami se naj gonijo, da bi jedli; ko ne bodejo nasíteni, tedaj primorani naj bodejo prenočevati.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Jaz pa bodem prepeval moč tvojo, in pel bodem do vsakega jutra milost tvojo, da si ti mi bil grad moj in pribežališče, ko sem bil v stiski.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'O moč moja, tebi bodem prepeval, da je Bog grad moj, Bog milosti moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Načelniku godbe, na šestostrunje pričanja, pesem odlična Davidova, za uk.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Ko se je boril sè Sirci Mezopotamijskimi, in Sirci Zobejskimi in je Joab vrnivši se pobil Edomejcev v solni dolini dvanajst tisoč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'O Bog, zavrgel si nas bil, raztrgal nas, srdit si bil, povrni se nam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Zmajal si bil deželo, razdrobil jo; sceli kosove njene, ker omahuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Storil si bil, da je ljudstvo tvoje čutilo trdóst, dál si nam bil piti grozo kakor vino.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Dal si njim, ki se tebe bojé, zastavo, katero naj rabijo, zaradi resnice mogočno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Da se rešijo ljubljenci tvoji; reši z desnico svojo in usliši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Bog je govoril po svetosti svoji, radoval se bodem; v delež dobim Sihem, in dolino Sukotsko merim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Moj je Gilead in moj Manase in Efraim glave moje moč, Juda postavodajalec moj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Moab umivalnica moja, na Edomejca vržem čevelj svoj, nad máno, Palestina, ukaj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Kdo bi me popeljal v mesto trdno, kdo bi me peljal noter do Edomeje?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Ali nisi bil ti, Bog, zavrgel nas; da nisi hodil, Bog, med našimi vojskámi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Daj nam pomoč zoper sovražnika; ker ničeva je pomoč človeška.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'V Bogu delajmo vrlo, in on bode poteptal sovražnike naše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Načelniku godbe na strune, pesem Davidova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Sliši Bog, vpitje moje, ozri se v molitev mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Od skrajnosti dežele te kličem, ko se pogreza srce moje; na skalo, ki bodi višja od mene, pelji me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Ker bil si mi pribežališče, stolp krepak zoper sovražnika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Bival bodem v šatoru tvojem na veke; pribežal bodem pod peróti tvojih zatišje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ker ti, Bog, si poslušal obljube moje, dal si dedovino spoštujočim ime tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Dni dodaj dnevom kraljevim; leta njegova naj bodejo kakor mnogih rodov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Ostane naj vekomaj pred Bogom; milost in zvestobo pripravi, da naj ga varujeti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Tako bodem prepeval tvojemu imenu večno, opravljajoč vsak dan obljube svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Načelniku godbe v Jedutunu, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Samo v Bogu počiva duša moja, od njega je moja blaginja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Samo on je skala moja in blaginja moja; grad moj, ne omahnem mnogo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Doklej bodete snovali težave nad moža? pobiti bodete vsi, podobni nagnenemu zidu, ograji omajani.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Samo z visokosti njegove pahniti ga ukrepljejo, veselé se laži; z usti svojimi blagoslavljajo, znotraj v sebi pa preklinjajo hudo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Samo v Bogu počivaj, duša moja, ker od njega je upanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Samo on je skala moja in blaginja moja, grad moj; ne omahnem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'V Bogu je blaginja moja in slava moja; krepka skala moja, pribežališče moje je v Bogu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Zaupajte mu vsak čas, o ljudstvo; pred njim izlijte srce svoje: Bog nam je v pribežališče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Sama ničevost so prostega človeka otroci, laž so odličnega moža otroci; na tehtnico vkup položeni, poskočili bi nad ničevost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Ne zaupajte zatiranju, in zaradi ropa ne bodite prevzetni; ako se množi bogastvo, ne navezujte nanj srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Enkrat je govoril Bog, dvakrat sem slišal isto, da je moč Božja,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 13, 'In da je milost tvoja, Gospod, da bodeš ti povrnil vsakemu po delu svojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Psalm Davidov, ko je bil v puščavi Judovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'O Bog, Bog mogočni si moj, zgodaj te iščem; dušo mojo žeja po tebi; po tebi hrepeni moje meso, v deželi suhi in onemogli brez vodá:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Gledati tvojo moč in slavo: tvojo, kakor sem te gledal v svetem kraji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, '(Ker milost tvoja je boljša od življenja), hvalijo naj te ustne moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Tako te bodem blagoslavljal v življenji svojem, v imenu tvojem bodem povzdigaval svoje roke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Kakor tolšče in masti bode se nasitila duša moja, in z blagoglasnimi ustnami bodo te hvalila usta moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Ko se spomnim tebe na ležišči svojem, čujem in premišljam tebe:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Da si bil velika pomoč meni, tako da sem prepeval v senci tvojih peroti;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Ko se duša moja tebe drži in gre za teboj, podpira me desnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Zatorej bodejo oni, ki iščejo pogubljenja duše moje, prišli v najspodnje kraje zemlje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Storili bodo, da vsak iz med njih pogine z mečem; lesicam bodejo delež.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Kralj pa sam bode se radoval v Bogu; ponašal se bode, kdorkoli priseza pri njem, ko se bodejo zamašila usta laž govorečim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Čuj, o Bog, glas moj, ko premišljujem; strahu sovražnikovega varuj življenje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Skrivaj me skrivnemu naklepu hudobnih, ropotanju njih, ki delajo krivico:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Ki brusijo kakor meč jezik svoj, napenjajo kakor pušico svojo bridko besedo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'S kopjem napadajo poštenjaka iz zakotja; nenadoma ga napadajo s kopjem in se ne bojé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Potrjujejo si reč hudobno; o skrivanji zank govoré; pravijo: Kdo bi jih videl?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Preiskujejo krivice; oslabeli smo po tem, kar so tako zvito preiskali; tako globoko je osrčje moža in srce.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ali ko jih bode Bog napadel s kopjem, pušica nagla bodejo njih udarci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'In storili bodejo, da sè samim jezikom svojim udarijo sebe; razkropljeni se bodejo spustili v beg, kdorkoli jih bode videl.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Katerikoli pa ljudjé se bojé, oznanjali bodo delo Božje in dejanje njegovo stavili pred óči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Veselil se bode pravični v Gospodu, in pribežal k njemu; ponašali se bodo vsi, ki so pravega srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Načelniku godbe, psalm Davidov, pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Tebi gré gotova hvala, o Bog, ki si na Sijonu, in tebi je opravljati obljubo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'O ki slušaš molitev, noter do tebe pride vse meso.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Premagale so me bile hudobije, grehe naše tí opiraš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Blagor mu, kogar izvoliš in pripuščaš, da bode prebival v vežah tvojih: sitimo se z dobroto hiše tvoje, sè svetimi rečmi tvojega svetišča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Čestitljive reči nam govoriš v pravici, o Bog blaginje naše; zaupanje vseh dalnjih pokrajin zemlje in morja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Gore utrjuješ v kreposti svoji, z močjo opasan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Šum morja strahuješ, šum vodá njegovih, in narodov hrup;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Ki delaš, da prepevajo jutranje vzhode in večerne prebivalci pokrajin, boječ se znamenj tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Obiskuješ to zemljo in je želiš, močno jo bogatiš; s potokom Božjim polnim vodé; pripravljaš njih žito, ko si jo tako obdelal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Razore njene namakaš, brazde njene poravnavaš; z deževjem jo raztapljaš, kal njeno blagoslavljaš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Venčaš dobrote svoje leto, in sledovi tvoji kapljajo maščobo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Kapljajo v ograje puščave in z radostjo se ogrinjajo griči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Pašniki se odevajo s čedami, in doline se pokrivajo s pšenico; ukajoč delajo in tudi pojó.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Načelniku godbe, pesem in psalm. Ukajte Bogu, vsi zemljani.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Prepevajte slavo njegovega imena; slavo pridevajte hvali njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Govorite Bogu: Kako čestitljiv si v delih svojih: zavoljo obilosti moči tvoje se ti lažnjivo udajajo sovražniki tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Vsi zemljani naj se ti klanjajo in ti prepevajo; prepevajo naj tvojemu imenu, presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Pridite in glejte dela Božja; čestitljiv je v dejanji proti sinovom človeškim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Morje izpreminja v suho; reko so pregazile noge, tam smo radovali se v njem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Z močjo svojo gospoduje vekomaj; oči njegove gledajo narode: kateri so uporni, naj se ne povišujejo preveč pri sebi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Blagoslavljajte Boga našega, ljudstva, in glas hvale njegove naj se razlega;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Kateri je dušo našo nazaj postavil v življenje, in ne pripusti, da omahnejo noge naše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Potem, ko si nas izkušal, Bog, raztopil si nas, kakor se topi srebro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Peljal si nas v samo mrežo; dél si nam podprsnico okolo ledja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Storil si, da je sédel človek na glavo našo, šli smo skozi ogenj in skozi vodo; slednjič si nas pripeljal do té sitosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Sè žgalnimi darovi pojdem v hišo tvojo in opravim svoje obljube,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Katere so izrekle odprte ustne moje, in govorila moja usta v stiski moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Žgalne darí tolstih ovnov bodem ti daroval s kadilom; pripravil vole s kozli, močno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Pridite, poslušajte, kateri koli se bojite Boga, da povem, kaj je storil duši moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Njega sem klical sè svojimi usti, in povišan sem bil za govore svojega jezika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Ako bi se bil v krivico obrnil sè srcem svojim, Gospod bi ne bil slišal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Ali vendar slišal je Bog, ozrl se v prošnje moje glas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Blagoslovljen Bog, kateri ni zavrgel prošnje moje in mi ni odtegnil milosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 1, 'Načelniku godbe na strune, psalm in pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 2, 'Bog nam stórí milost in blagoslavljaj nas, razsvetli naj obličje svoje proti nam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 3, 'Da spoznamo na zemlji tvoj pot, v vseh narodih blaginjo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 4, 'Slavé te naj ljudstva, Bog, slavé te ljudstva vsa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 5, 'Veselé se naj in pojó narodi, ko bodeš prav sodil ljudstva, in narode same bodeš vodil po zemlji mogočno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 6, 'Slavé te naj ljudstva, Bog, slavé te ljudstva vsa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 7, 'Zemlja daje sad svoj; blagoslovi nas Bog, naš Bog:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 8, 'Blagoslóvi nas Bog, in bojé se ga naj vse meje zemljé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 1, 'Načelniku godbe, Davidov psalm in pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 2, 'Ko vstane Bog, razkropé se neprijatelji njegovi, in srditi sovražniki njegovi bežé pred njegovim obličjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 3, 'Kakor bi puhnil dim, puhneš jih, kakor se staja vosek v ognji, izginejo krivični izpred Božjega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 4, 'Pravični pa se veséli radujejo pred Bogom, in se veselé v radosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 5, 'Pojte Bogu, prepevajte njegovemu imenu; povišujte ga, ki sedí v sami lepoti, ime mu je Gospod, in radujte se pred njim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 6, 'Oče je sirotam in bramba vdovam, Bog v prebivališči svetosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 7, 'Bog stavi v rodovino samotarje; izpeljuje zvezane iz vezî; in uporniki prebivajo v kraji presuhem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 8, 'O Bog, ko si hodil pred ljudstvom svojim, ko si stopal po samoti izvrstno;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 9, 'Tresla se je zemlja, tudi nebesa so se rosila od pričujočnosti Božje, sam Sinaji od pričujočnosti Božje, Boga Izraelovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 10, 'Dež preobilen si rosil, Bog; posestvo svoje, in to hirajoče, si oživljal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 11, 'Tvoji so krdeloma prebivali v njem; ti ga pripravljaš po dobroti svoji onemu ubozemu siromaku, Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 12, 'Bog je dajal govor; one, ki so oznanjale, dejale so v veliki vojni:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 13, 'Kralji vojnih krdél bežé, bežé; in ona, ki biva domá, plén deli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 14, 'Če ste tudi ležali med dvema kupoma kamenja, bodete podobni perotim goloba srebrom kritega, katerega pérje je iz rumenega zlata izkopanega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 15, 'Ko bode vsemogočni razkropil kralje v tej deželi, bodeš bel kakor sneg na Salmonu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 16, 'Največji gori, gori Basanski; gori grbasti, gori Basanski.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 17, 'Zakaj bi se podrle, grbaste gore? té gorske kraje želi Bog za sedež svoj, Gospod tudi bode prebival v njih vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 18, 'Vozov Božjih je dvakrat deset tisoč, tisoč in tisoč: Gospod z njimi, Gospod Sinaji v svetišči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 19, 'Dvigajoč se v višavo dobil si v pest vjetnikov množino, prejemajoč dal si darí ljudém; tudi upornike bivajoč dobivaš v pest, Gospod Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 20, 'Blagoslovljen Gospod, kateri nas vsak dan obklada z darovi; Bog ón mogočni, blaginja naša.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 21, 'Bog ón mogočni nam je Bog mogočni, za vsakatero blaginjo, in Gospodovi so izhodi zoper smrt sámo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 22, 'Samo Bog razbija glavo sovražnikov svojih; téme lasato njega, ki hodi neprestano v krivicah svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 23, 'Rekel je bil Gospod: Iz Basana pripeljem nazaj, nazaj pripeljem iz globočin morjá,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 24, 'Da razbijajoč pomočiš nogo svojo v kri; jezik psov svojih v kri sovražnika vsakega izmed njih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 25, 'Ko so videli hojo tvojo, o Bog, hojo mojega Boga mogočnega, kralja mojega, kateri je v svetišči;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 26, 'Šli so spredaj pevci, potem godci; med deklicami, ki so bíle na tambure.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 27, 'V zborih blagoslavljajte Boga, Gospoda, kateri ste iz vira Izraelovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 28, 'Ondi bodi Benjamin mali in gospodar njih; prvaki Judovski in njih krdela, prvaki Zabulonovi, Naftalijevi prvaki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 29, 'Bog tvoj zapoveduje, da bodi krepák; okrepčaj, o Bog, ker si deloval v nas,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 30, 'Iz svetišča svojega zavoljo Jeruzalema. Tebi prinesó kralji darilo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 31, 'Pogúbi krdelo trstonosno, čedo krepkih juncev s teleti ljudstev, ki se na videz udaje s kosovi srebra; razkropi ljudstva, ki jih vojske veselé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 32, 'Pridejo naj velikaši iz Egipta, Etiopija naj hitro pošlje rok svojih dar Bogu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 33, 'Kraljestva zemeljska, pojte Bogu; prepevajte Gospodu silno,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 34, 'Kateri sedí v starodavnih nebés nebesih: glej, z glasom svojim daje glas krepak od sebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 35, 'Dajajte moč Bogu, veličastvo njegovo je nad Izraelom, in moč njegova v gornjih oblakih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 36, 'Strašán si, o Bog, iz svetišč svojih; Bog mogočni Izraelov sam daje moč in sile temu ljudstvu: slava Bogu!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 1, 'Načelniku godbe na šestero strun, pesem Davidova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 2, 'Reši me, Bog, ker vode mi prihajajo noter do duše,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 3, 'Pogrezam se v blato pregloboko; kjer ni trdnega pod nogo; zahajam v globočine vodâ; in val poplaveč me požira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 4, 'Trudim se vpijoč, suši se grlo moje; oči moje pešajo, ko upam v svojega Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 5, 'Več jih je ko glave moje lâs, ki me sovražijo po krivem; mogočneji so, ki me hočejo ubiti, ki so mi sovražniki po krivici; tedaj me silijo vrniti, česar nisem vzel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 6, 'O Bog, ti poznaš nespamet mojo, in krivice moje niso ti skrite.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 7, 'Ne bodi jih mene sram, kateri čakajo tebe; Gospod, Bog vojnih krdél, rudečica naj ne oblije zaradi mene njih, ki iščejo tebe, Bog Izraelov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 8, 'Ker zavoljo tebe prenašam zasmehovanje; sramota pokriva obličje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 9, 'Tujec sem postal bratom svojim, in neznan matere moje sinovom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 10, 'Ker gorečnost za hišo tvojo me razjéda, in zasmehovanje njih, ki tebe zasmehujejo, mene zadeva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 11, 'Ko jokajoč pokorim s postom dušo svojo, tedaj se mi to šteje za najhujšo sramoto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 12, 'Ko se oblačim v raševino, tedaj sem jim v pregovor.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 13, 'O meni govoričijo vkup sedeči pri vratih, in pesmi pojó, ko pijejo opojno pijačo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 14, 'O meni torej je prošnja moja tá do tebe, Gospod: čas je milosti, Bog, po obilnosti milosti svoje usliši me, po blagi zvestobi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 15, 'Potegni me iz blata, in naj se ne pogreznem; otet naj bodem sovražnikov svojih, in iz globočin vodâ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 16, 'Valovje vodâ naj me poplaveč ne odnese, in globočina naj me ne pogoltne, in jama naj ne zapre ust svojih nad mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 17, 'Usliši me, Gospod, ker dobra je milost tvoja; po obilosti usmiljenja svojega ozri se v mé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 18, 'In ne skrivaj obličja svojega svojemu hlapcu; ker v stiski sem, hiti, usliši me!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 19, 'Približaj se duši moji, ótmi jo; zavoljo sovražnikov mojih réši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 20, 'Ti poznaš zasramovanje moje in mojo sramoto ter nečast mojo; pred teboj so vsi sovražniki moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 21, 'Zasramovanje tare srce moje, tako da sem bolan; in ko ga čakam, da bi me miloval, nikogar ni; ali tolažiteljev, vendar ne najdem jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 22, 'Dà, za živež mi dajó želča, in v žeji moji dajó mi piti octa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 23, 'Njih miza bodi pred njimi za zanko, in za povračila, za zadrgo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 24, 'Otemné naj njih oči, da ne vidijo; in daj, da ledja njih omahujejo neprestano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 25, 'Razlij na nje jezo svojo, in srd tvoj naj jih dohiti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 26, 'Pusti naj bodejo njih gradovi, v šatorih njih ne bodi prebivalca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 27, 'Ker preganjajo njega, kateregi si tí udaril, in po bolečini prebodencev tvojih spletajo pripovedke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 28, 'Pridevaj kazen kazni njih krivici, in naj ne pridejo v pravico tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 29, 'Izbrišejo naj se iz življenja knjige, in s pravičnimi naj se ne zapisujejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 30, 'Jaz pa ubožen in trpeč, blaginja tvoja, Bog, postavila me bode na višavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 31, 'Hvalil bodem ime Božje s pesmijo, in poveličeval ga bodem sè zahvaljevanjem,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 32, 'Kar se bode bolje zdelo Gospodu, ko vol, junec rogat z razklanimi parklji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 33, 'Ko bodejo to videli krotki, veselili se bodo; in oživelo bode srce vaše, ki iščete Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 34, 'Ker Gospod se ozira na potrebne, in jetnikov svojih ne zameta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 35, 'Hvalila ga bodo nebesa in zemlja, morja in karkoli lazi po njih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 36, 'Ker Bog otima Sijon in zida z nova mesta Judovska, da stanujejo tam, in podedujejo ono deželo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 37, 'Nasledniki, pravim, hlapcev njegovih naj jo posedajo, in ljubitelji imena njegovega naj prebivajo v njej,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 1, 'Načelniku godbe, pesem Davidova, za spomin.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 2, 'Bog, otet me, Gospod, pomagat mi híti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 3, 'Osramoté se naj in z rudečico oblijó, kateri iščejo duše moje; zavrnejo se naj in onečastijo, ki se veselé nesreče moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 4, 'Umikajo se naj za plačílo sramote svoje, kateri govoré: Prav, prav!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 5, 'Veselé se naj in radujejo v tebi vsi, ki te iščejo, in govoré naj vedno: Poveličuj se Bog, kateri ljubijo blaginjo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 6, 'Jaz pa sem ubožen in potreben, o Bog; híti za voljo mene, in pomoč moja bodi, rešitelj moj; Gospod, ne múdi se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 1, 'K tebi, Gospod, pribegam, sram me ne bodi nikdar.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 2, 'Po pravici tvoji ótmi me in oprosti me; nagni k meni uho svoje in réši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 3, 'Bodi mi skala, na kateri naj prebivam, kamor naj zahajam vedno; zapoved si dal, da naj se rešim, ker skala moja si in trdnjava moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 4, 'Bog moj, reši me iz roke njegove, ki dela nepravično in neusmiljeno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 5, 'Ker ti si nada moja, Bog Gospod; upanje moje od moje mladosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 6, 'Nate se opiram od poroda; od osrčja matere moje odtrgal si me tí; v tebi je hvala moja neprestano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 7, 'Kakor čudo bil sem mnogim; tako si mi krepko zavetje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 8, 'Napolnijo naj se s hvalo tvojo usta moja, ves dan sè slavo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 9, 'Ne zavrzi me o starosti času; ko peša krepost moja, ne zapústi me;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 10, 'Ker sovražniki moji govoré o meni, in oni, ki prežé na dušo mojo, posvetujejo se vkup,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 11, 'Govoreč: Bog ga zapušča, podite in zgrabite ga; ker ni ga, da bi ga rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 12, 'Bog, ne bivaj daleč od mene, Bog moj, na pomoč mi hiti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 13, 'Osramoté se naj in poginejo nasprotniki duše moje; pokrijejo naj se z nečastjo in sramoto, kateri iščejo hudega meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 14, 'Jaz pa sem v nadi neprestano o vsej hvali tvoji, in bodem stanoviten.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 15, 'Usta moja hočejo oznanjati pravico tvojo, vsak dan blaginjo tvojo: dasi ne znam števil njenih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 16, 'Poprijel se bodem vsake kreposti, Bog Gospod; oznanjal bodem pravico samega tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 17, 'Bog, učil si me od mladosti moje, in do sedaj sem oznanjal čuda tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 18, 'Torej tudi toliko časa, ko sem star in siv, Bog, ne zapústi me; dokler bodem oznanjal roko tvojo temu rodu, vsakemu prihodnjemu rodu krepost tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 19, 'Ker pravica tvoja, Bog, seza do višav; ker stvari delaš velike, Bog; kdó je tebi enak?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 20, 'Ker potem ko si dal, da sem izkusil stiske velike in hude, poživljaš me zopet, in iz brezen zemlje daješ da zopet vstajam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 21, 'Velikost mojo množiš, in ustaviš se ter me tolažiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 22, 'Tudi jaz te bodem slavil sè strunami, in zvestobo tvojo, moj Bog; prepeval ti bodem s citrami, o svetnik Izraelov!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 23, 'Pevale bodo ustne moje, ko ti bodem prepeval, in duša moja, k si jo otél.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 24, 'Tudi jezik moj bode vsak dan oznanjal pravico tvojo, ker bodo se sramovali, ker sè sramoto bodo obliti, ki iščejo hudega meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 1, 'Za Salomona: Bog, sodbe svoje kralju daj in pravico svojo sinu kraljevemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 2, 'Sodi naj ljudstvo tvoje pravično, in uboge tvoje po pravici.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 3, 'Mir naj ljudstvu gore rodé, in griči zavoljo pravice.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 4, 'Rešil bode ljudstva siromake, otél ubogih sinove, a zdrobil zatiralca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 5, 'Čestili te bodejo, dokler bode solnce, in dokler bode trajal mesec do večnega róda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 6, 'Kakor ko pride dež nad travo pokošeno, ko deževje, moča zemlji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 7, 'Bode v cvetu o času njegovem pravični, in mirú obilost, dokler da ne bode meseca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 8, 'In gospodoval bode od morja do morja in od reke do mej zemljé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 9, 'Pred njim se bodo klanjali in čestili ga tujci; in prah bodejo lizali sovražniki njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 10, 'Kralji morski in otočani nosili mu bodejo darí; kralji iz Sabeje in Sabe prinesó mu darilo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 11, 'Dâ, klanjali se bodo vsi kralji; vsi narodi mu bodejo služili.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 12, 'Ker rešil bode ljudstvo vpijoče, in ubozega, kateremu ne bode pomočnika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 13, 'Prizanašal bode siromaku in potrebnemu, in duše potrebnih bode rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 14, 'Zvijače in silovitosti bode otél njih dušo; tako draga je njih kri v očeh njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 15, 'Torej, dokler bode živel, dajal mu bode zlata Sabejskega, in prosil bode zanj neprestano, ves dan ga blagoslavljal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 16, 'Kjer bode peščica pšenice na zemlji, na vrhu gorâ, majal se bode kakor Libanon sad njegov, in cveli bodejo meščani kakor trava zemeljska.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 17, 'Imé njegovo bode vekomaj; dokler bode solnce, poganjalo bode ime njegovo; in blagoslavljajoč se v njem bodo ga blagrovali vsi narodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 18, 'Slava Gospodu, Bogu, Izraelovemu, kateri sam dela čuda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 19, 'In blagoslovljeno ime slave njegove vekomaj, in slave njegove naj se napolni vsa zemlja; zgôdi se, in zgôdi se!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 20, 'Konec je molitev Davidovih, sina Izajevega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 1, 'Psalm Asafov. Dá, dober je Bog Izraelu, čistim v srci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 2, 'Jaz pa, malo da se niso izpotaknile noge moje, skoraj nič, da niso izpodrsnili koraki moji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 3, 'Ko sem zavidal blazne, gledal krivičnih blagostanje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 4, 'Ker ni ga vozla notri do njih smrti, temuč tolsta je njih moč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 5, 'V trudu človeškem niso, in z drugimi ljudmi ne tepó jih nadloge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 6, 'Zatorej jih obdajajo prevzetnosti verige, pokriva jih kakor dika silovitost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 7, 'Svétiti se jim od tolšče obé očesi, kipé misli srčne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 8, 'Kužni so, in hudobno govoré zatiranje, in z višave govoré.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 9, 'V nebo dvigajo usta svoja, in jezik njih prehaja zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 10, 'Zatorej se vrača sem ljudstvo njegovo, ko se čaše, vode polne, iztiskajo jim,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 11, 'Da pravijo: Kako bi poznal Bog mogočni? ali bi bilo znanje v višavi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 12, 'Glej tiste krivične, kako mirni vekomaj množijo močí.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 13, 'Vendar zastonj čistim svoje srce, in v snagi umivam rok svoje;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 14, 'Ko me tepe vsak dan, in pokora moja mi je gotova vsako jutro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 15, 'Ako rečem: Pravil bodem to; glej, izdajalec bi bil zarodu tvojih sinov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 16, 'Ako bi mislil spoznati to, težavno se mi je zdelo v mojih očéh;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 17, 'Dokler sem stopil v svetišča Boga mogočnega, zagledal njih konec.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 18, 'Ali na polzlo jih staviš, mečeš jih dol v podrtije.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 19, 'Kako ginejo v zapuščenost, kakor v hipu minejo, konec jih je v grozah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 20, 'Kakor sanje, ko se je zbudil kdo: Bog, ko se zbudiš, zaničuješ njih podobo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 21, 'Ko se razdraži srce moje, in ko sem se v ledvicah svojih samega zbadal,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 22, 'Tedaj sem bil brezpameten, ko nisem vedel: kakor živina bil sem pri tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 23, 'Zatorej bodem jaz vedno s teboj; prijel si roko desno mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 24, 'Sè sovetom svojim me spremljaj, da me potem v slavo sprejmeš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 25, 'Kdo bi mi bil v nebesih razen tebe? in razen tebe se nikogar ne veselim na zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 26, 'Ko peša meso moje in srce moje, skala srca mojega in delež moj je Bog vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 27, 'Ker glej, kateri so daleč od tebe, ginejo; pokončaš ga, kdor koli se s prešestvovanjem izneveri tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 28, 'Meni torej je dobro, da sem blizu Bogu; v Gospoda stavim svoje pribežališče, da oznanjam vsa dela tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 1, 'Pesem ukovita, Asafu. Zakaj, Bog, zametaš vekomaj, vedno kadí se jeza tvoja v čedo paše tvoje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 2, 'Spomni se občine svoje; da si prej pridobil, odkupil rod posesti svoje, da je to gora Sijonska, na kateri si prebival.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 3, 'Vzdigni noge svoje na večne podrtije, na vse zlo, kar ga dela sovražnik v svetem kraji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 4, 'Rujoveč so sovražniki tvoji sredi zbirališč tvojih postavili znamenja svoja, za znamenja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 5, 'Za plemenitega so imeli izmed njih vsakega, kakor je dvigal kvišku nad zapleteno lesovje sekire.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 6, 'Še zdaj bijejo izdolbene podobe njegove vkup s kolom in s kladivi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 7, 'Zažgali so svetišča tvoja, pahnili so na tla in oskrunili prebivališče tvojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 8, 'Rekli so v srci svojem: Zgrabimo ga vsi vkup; zapalili so vsa zbirališča Boga mogočnega, in pahnili jih na tla.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 9, 'Znamenj naših ne vidimo, ni več preroka, in ni ga pri nas, ki bi vedel, doklej.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 10, 'Doklej, o Bog, bode zasramoval sovražnik, dražil bode neprijatelj ime tvoje vekomaj?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 11, 'Zakaj odtezaš roko svojo, in desnico svojo? Iz srede nedrija svojega strahúj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 12, 'Saj Bog je kralj moj že od nekdaj, delajoč blaginjo sredi zemlje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 13, 'Ti si razklal v moči svoji morje; razbil si zmajem glave v vodah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 14, 'Ti si razbil somu glave, dajal si hrane samemu ljudstvu, potujočemu skozi puščavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 15, 'Ti si odprl studenec in potok; ti posušaš reke mogočne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 16, 'Tvoj je dan, in tvoja noč; ti si napravil luč njeno in solnce.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 17, 'Ti si postavil vse meje zemlji; samo poletje in zimo napravil si tí.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 18, 'Spomni se vendar tega, da sovražnik zasramuje, o Gospod, in da ljudstvo nespametno draži ime tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 19, 'Ne dajaj tistemu krdelu življenja grlice svoje, krdela ubozih svojih ne pozabi vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 20, 'Ozri se na zavezo, ker napolnjeni so najskrivnejši kraji zemlje, silovitosti so jama.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 21, 'Kdor je ponižan, naj se ne vrne zmeden; ubogi in potrebni naj hvalita ime tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 22, 'Vstani, o Bog; potegni se za pravdo svojo; spomni se zasramovanja svojega, katero ti dela nespametni vsak dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 23, 'Ne pozabi glasú sovražnikov svojih; ropota spenjajočih se v té, ki se množi vedno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 1, 'Načelniku godbe: \"Ne pogubi!\" psalm Asafu in pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 2, 'Slavimo te, Bog, slavimo; ker blizu je ime tvoje, čuda tvoja oznanjamo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 3, 'Ko bodem sprejel zbor, sodil bodem najbolj pravično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 4, 'Zemlje in vseh njenih prebivalcev stebre omajane utrdil bodem jaz.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 5, 'Govoreč blaznim: Ne bodite blazni, in krivičnim: Ne dvigujte roga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 6, 'Ne dvigujte roga svojega zoper Najvišjega; ne govorite s trdim vratom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 7, 'Ker od vzhoda ali od zahoda, tudi od puščave ni povišanja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 8, 'Temuč Bog sodnik: tega poniža, onega poviša.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 9, 'Ker čaša je v roki Gospodovi in vino kalno, polno mešanice, iz katere je izlil; vendar goščo njeno, katero bodo iztisnili, pili bodo vsi krivični na zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 10, 'Jaz torej naj oznanjam vekomaj, prepevam Bogu Jakobovemu:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 11, 'In vse rogove bodem polomil krivičnim; zvišajo naj se pravičnemu rogovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 1, 'Načelniku godbe na strune, psalm Asafu in pesem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 2, 'Plemenit je v Judi Bog, v Izraelu veliko ime njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 3, 'V Salemu je koča njegova, in prebivališče na Sijonu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 4, 'Ondi je zlomil loke bliskajoče, ščit in meč in vojsko presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 5, 'Svetál si postal, veličasten, z gorâ plenjenja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 6, 'V plen so se dali krepki v srci; spali so spanje svoje; tako da niso našli nobeni možje vojaki svojih rók.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 7, 'Od hudovanja tvojega, o Bog Jakobov, onemogel je voz in konj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 8, 'Ti, tí si strašán, ali bi kdo obstal pred teboj, odkar se jeziš?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 9, 'Z neba daješ, da se čuje sodba, zemlja se boji in se je umirila,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 10, 'Ko vstane na sodbo Bog, branit vse krotke na zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 11, 'Ker srd človeški te slaví, z ostanki srda opasuješ svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 12, 'Delajte in opravljajte obljube Gospodu Bogu svojemu; katerikoli stojé okolo njega, prinesó naj mu dar strašnemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 13, 'Kateri žanje napuh prvakov, strašán zemeljskim kraljem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 1, 'Načelniku godbe, naslednikov Idutunskih; psalm Asafov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 2, 'Glas moj gre do Boga, ko zavpijem; glas moj do Boga, da nagne uho k meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 3, 'Ob času stiske svoje iščem Gospoda; roka moja je ponoči polita neprestano, duša moja se brani pripustiti tolažbo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 4, 'Spominjam se Boga, ko trepetam in stokam; premišljam, ko duh moj omaguje presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 5, 'Ko mi ne daš zatisniti očî, zbegan sem, tako da povedati ne morem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 6, 'Čase premišljujem starodavne, prejšnjih vekov leta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 7, 'Spominjam se godbe svoje ponočnje; v srci svojem premišljam, in duh moj preiskuje govoreč:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 8, 'Ali bi vekomaj zametal Gospod; ali ne bode dalje dobrovoljen?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 9, 'Ali bi vekomaj opešala milost njegova; konec bilo govora od roda do roda?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 10, 'Ali bi bil pozabil Bog mogočni deliti milost; ali bi zapiral v jezi usmiljenje svoje?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 11, 'Slednjič pravim: To me slabi, ko se je izpremenila Najvišjega desnica.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 12, 'Spominjal so bodem dejanj Gospodovih; dà, spominjal se bodem od starodavnosti vseh čudežev tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 13, 'In premišljal bodem vsakatero délo tvoje; o dejanjih tvojih bodem pripovedoval:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 14, 'O Bog, v svetosti je steza tvoja, kdo je Bog mogočni kakor Bog?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 15, 'Ti, o Bog mogočni, čudoviti, pokazal si moč svojo na narodih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 16, 'Rešil si z roko ljudstvo svoje, sinove Jakobove, tudi Jožefa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 17, 'Videle so te vode, Bog, videle so te vode in se tresle, dà, potresla so se brezna.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 18, 'Izlili so oblaki vode, glas so zagnali gornji oblaki; priletele so tudi pušice tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 19, 'Bobnel je grom tvoj v tistem krogu, razsvetljali so bliski vesoljni svet; potresla se je zemlja in trepetala.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 20, 'Skozi morje pot tvoja, in steza tvoja skozi prostorne vode, kjer sledovi tvoji niso znani,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 21, 'Vodil si kakor čedo ljudstvo svoje, po Mojzu in Aronu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 1, 'Pesem ukovita Asafova. Poslušaj, ljudstvo moje, nauk moj; nagnite uho svoje govoru mojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 2, 'V priliki odprem usta svoja; od sebe dam skrivnosti časov nekdanjih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 3, 'Kar smo slišali in znali, ko so nam pravili pradedje naši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 4, 'Prikrivali ne bodemo njih otrokom, naslednjemu rodu, da oznanjajo hvalo Gospodovo in moč njegovo, in čudovita dela njegova, katera je storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 5, 'Ker ustanovil je pričanje v Jakobu in postavil zakon v Izraelu, ko je zapovedal pradedom našim, oznanjati svojim otrokom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 6, 'Da vedó, naslednji rod, otroci prihodnji, in vstanejo ter oznanjajo otrokom svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 7, 'Upanje svoje naj stavijo v Boga, in ne pozabijo naj dejanj Boga mogočnega, temuč hranijo naj zapovedi njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 8, 'In ne bodejo naj kakor njih pradedje, rod trdovraten in uporen; rod, kateri ni popravil srca svojega, in katerega duh ni bil stanoviten proti Bogu mogočnemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 9, 'Kakor nasledniki Efrajmovi, kateri oboroženi streljajo z lokom in hrbte obračajo ob času bitve.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 10, 'Ohranili niso zaveze Božje, in branili so se hoditi po zakonu njegovem,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 11, 'Pozabivši dejanj njegovih, in čudovitih del njegovih, katera jim je bil pokazal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 12, 'Pred pradedi njihovimi je delal čuda, v deželi Egiptovski, na polji Taniškem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 13, 'Razklal je bil morje, da jih je prepeljal čez, in postavil je vode, kakor kùp.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 14, 'In spremljal jih je z oblakom podnevi, in vso noč sè svetlim ognjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 15, 'Razklal je bil skale v puščavi, da bi pijačo pripravil v valovih preobilo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 16, 'Valove je izpeljal iz skale, in vode dol spuščal kakor reke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 17, 'Vendar so dalje grešili še zoper njega, in dražili Najvišjega v sami suhi deželi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 18, 'In izkušajoč Boga mogočnega v srci svojem, térjali so jedi po svojega srca želji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 19, 'In grdo govoreč zoper Boga, rekli so: \"Ali bi mogel Bog mogočni napraviti mizo v tej puščavi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 20, 'Glej, tako je udaril skalo, da so tekle vode, in potoki so se udrli, ali bi mogel dati tudi živeža? ali bi pripravil mesa svojemu ljudstvu?\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 21, 'Zato je Gospod slišal in se razjaril; in ogenj se je bil vnel zoper Jakoba, in jeza je tudi gorela zoper Izraela.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 22, 'Ker niso verovali v Boga, in niso zaupali v blaginjo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 23, 'Dasi je bil zapovedal gornjim oblakom zgoraj in odprl vrata nebeška,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 24, 'In dežil nad nje máno za jed in dajal žito nebeško;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 25, 'Kruh najmočnejših je jedel vsak; popotnico jim je pošiljal do sitega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 26, 'Zagnal je sever na nebesih, in z močjo svojo pripeljal jug.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 27, 'Ko je dežil nad nje meso kakor prah, in kakor morski pések tiče krilate;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 28, 'Metal jih je med šatore, okolo prebivališč svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 29, 'In jedli so in bili so nasiteni močno, in česar so poželeli, prinesel jim je.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 30, 'Še niso bili iznebili se poželenja svojega, še je bila jed njih v njihovih ustih;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 31, 'Ko je jeza Božja goreča proti njim morila med najmočnejimi iz med njih in pokončavala mladeniče Izraelske.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 32, 'Po vsem tem so še grešili in niso verovali zavoljo čudovitih dél njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 33, 'Zatorej je pogubljal v ničemurnosti njih dní, in njih leta v strahu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 34, 'Ko jih je pobijal, ako so popraševali po njem in izpreobrnivši se zjutraj iskali Boga mogočnega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 35, 'Spomnivši se, da je bil Bog njih skala in Bog mogočni najvišji njih rešnik;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 36, 'Če tudi so ga hoteli varati z usti svojimi, in so z jezikom svojim lagali se njemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 37, 'In srce njihovo ni bilo obrneno proti njemu, in niso bili stanovitni v zavezi njegovi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 38, 'Vendar je on usmiljen opíral krivico, tako da jih ni pogubil; in odvračal je svoj srd obilo, in ní vnemal vse jeze svoje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 39, 'Spomnivši se, da so meso, veter, ki gre in se ne vrne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 40, 'Kolikokrat so ga razdražili v puščavi; žalili so ga v samoti!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 41, 'Ki so hitro izkušali Boga mogočnega, in žalili Svetega Izraelovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 42, 'Ne spomnivši se roke njegove, dné, ko jih je bil otél sovražnika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 43, 'Ko je v Egiptu delal znamenja svoja, in čuda svoja na polji Taniškem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 44, 'Ko je v kri izpremenil njih potoke, in reke njih, da bi ne mogli piti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 45, 'Izpustil je nad njé živali krdelo, da bi jih pokončalo, in žabe, da jih uničijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 46, 'In dal je njih sad murnu in kobilici njih delo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 47, 'Pobil je s točo njih trte in smokve njih z ognjem, ki je pokončal vse, kamor je prišel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 48, 'Dal je tudi isti toči njih živali, in njih čede žarjavici ognjeni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 49, 'Izpustil je nad nje jeze svoje žar, srd in nevoljo in stisko, pošiljajoč oznanovalce nesreče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 50, 'Pretehtal je k jezi svoji pot, smrti ni ubranil njih življenja; in živali njih izročil je kugi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 51, 'In udaril je vse prvorojeno v Egiptu; prvino moči v šatorih Kamovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 52, 'In prepeljal je kakor ovce ljudstvo svoje, in vodil jih je kakor čede po puščavi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 53, 'In peljal jih je varno tako, da se niso bali, potem ko je bilo morje pokrilo njih sovražnike.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 54, 'Pripeljal jih je do meje svetosti svoje, gore té, katero je pridobila desnica njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 55, 'Izgnal je izpred njih obličja narode in storil, da so pripali vrvi posesti in prebivali so v njih šatorih Izraelovi rodovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 56, 'Vendar so izkušali in razdražili Boga najvišjega, in pričanj njegovih niso se držali.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 57, 'Temuč obrnili so se ter ravnali izdajalsko, kakor njih pradedje; obrnili so se kakor lok goljufen,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 58, 'Ker dražili so ga z višinami svojimi in svojimi maliki, do ljubosumnosti so ga razvneli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 59, 'Slišal je Bog in se razsrdil, in zavrgel je silno Izraela.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 60, 'Tako, da je zapustivši prebivališče v Silu, šator, katerega je bil postavil med ljudmi,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 61, 'Dal v sužnjost svojo moč, in slavo svojo sovražniku v pest.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 62, 'In izročil je meču ljudstvo svoje, ker se je bil razsrdil zoper posestvo svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 63, 'Ogenj je pokončal mladeniče njegove, in device njegove niso se hvalile.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 64, 'Duhovniki njegovi padli so pod mečem, in vdove njegove niso jokale.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 65, 'Potem se je zbudil Gospod, kakor da bi bil spal, kakor korenjak, pojoč po vinu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 66, 'In udaril je sovražnike svoje nazaj; sramoto večno jim je naložil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 67, 'Slednjič je zavrgel šator Jožefov in rodú Efrajmovega ni izvolil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 68, 'Izvolil pa je rod Judov, goro Sijonsko, da bi jo ljubil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 69, 'Zidal je enako najvišjim gradovom svetišče svoje, namreč v deželi, katero je utrdil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 70, 'In izvolil je Davida hlapca svojega, in vzel ga iz ograje čede,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 71, 'Peljal ga je od doječih, da bi pasel Jakoba, ljudstvo svoje in Izraela, posestvo svoje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 72, 'Kateri jih je pasel po poštenosti srca svojega, in vodil jih je z najvišjo razumnostjo svojih rok.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 1, 'Psalm Asafu. O Bog, prišli so narodi v posestvo tvoje, oskrunili so hram svetosti tvoje, v groblje izpremenili so Jeruzalem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 2, 'Dali so hlapcev tvojih truplo za hrano tičem nebeškim; meso njih, katerim si milosten, zemeljskim zverém.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 3, 'Prelivali so kri njihovo kakor vodo okrog Jeruzalema, in ni ga bilo, da bi pokopaval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 4, 'V zasramovanje smo sosedom našim, v zasmehovanje in norčevanje njim, kateri so okolo nas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 5, 'Doklej, Gospod? bodeš-li jezil se večno? bode li gorela kakor ogenj gorečnost tvoja?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 6, 'Izlij srd svoj nad one narode, kateri te ne spoznavajo, in nad kraljestva, katera ne kličejo tvojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 7, 'Ker pojedli so Jakoba, in razdejali so prebivališče njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 8, 'Ne spomínjaj se zoper nas krivic preteklih časov, hiti naj in prehití nas usmiljenje tvoje, ker obožali smo silno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 9, 'Pomagaj nam, Bog, blaginje naše, zavoljo česti svojega imena, in reši nas ter prizanesi nam grehe naše zavoljo svojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 10, 'Zakaj naj bi govorili oni narodi: \"Kje je njih Bog?\" Znano bodi med onimi narodi pred našimi očmi maščevanje krvi prelite hlapcev tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 11, 'Pred obličje tvoje naj pride zdihovanje jetnika, po velikosti roke svoje stóri, da ostanejo, kateri se že izročajo smrti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 12, 'Povrni torej sosedom našim sedemkrat v njih naročje sramoto njih, katero so ti delali, Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 13, 'In mi ljudstvo tvoje, in čeda paše tvoje, bodemo slavili te večno; od roda do roda bodemo oznanjali hvalo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 1, 'Načelniku godbe na šestero strun: psalm pričanja Asafu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 2, 'O pastir Izraelov, poslušaj, ki vodiš Jožefa kakor čedo, sedeč na Kerubih prisvéti!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 3, 'Pred Efrajmom, Benjaminom in Manasom zbudi moč svojo in pridi in prinesi nam polno blaginjo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 4, 'Bog, pomagaj nam zopet na noge; daj, da sveti obličje tvoje, in rešeni bomo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 5, 'Gospod, Bog vojnih krdél, doklej bodeš kadil proti molitvi svojega ljudstva?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 6, 'Paseš jih sè solznim kruhom, in piti jim daješ sólz obilo mero.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 7, 'Prepuščaš nas v prepir sosedom našim, in sovražniki naši zasmehujejo nas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 8, 'O Bog vojnih krdel, pomagaj nam zopet na noge, in daj, da sveti obličje tvoje, rešeni bomo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 9, 'Trto si bil prestavil iz Egipta, pregnal si bil ljudstva, da bi jo zasadil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 10, 'Pospravil si bil pred njo, in storil si, da je poganjala korenine svoje, in napolnila je bila deželo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 11, 'Gore so se pokrivale sè senco njeno, in mladik njenih cedre največje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 12, 'Stezala je veje svoje noter do morja, in do reke mladike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 13, 'Zakaj si podrl ograje njene, tako da jo obirajo vsi popotniki?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 14, 'Izpodriva jo gozdna svinja, in žival poljska jo objeda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 15, 'O Bog vojnih krdél, povrni se skoraj, ozri se z nebes ter glej, in obišči to trto,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 16, 'In mladiko, katero je bila vsadila desnica tvoja, in to zavoljo sina, katerega si potrdil sebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 17, 'Posmojena je z ognjem, odrezana; od hudovanja obličja tvojega ginejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 18, 'Roka tvoja bodi nad možem desnice tvoje, sinom človeškim, katerega si potrdil sebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 19, 'In umaknili se ne bodemo od tebe; v življenji nas ohrani, da kličemo ime tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 20, 'Gospod Bog vojnih krdél, pomagaj nam na noge; daj, da sveti obličje tvoje, in rešeni bomo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 1, 'Načelniku godbe pri Gitaji, pesem Asafu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 2, 'Pojte Bogu, móči naši, vpijte Bogu Jakobovemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 3, 'Primite psalmovanje in vzemite boben, strune prijetne in brenklje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 4, 'Trobite o mlaji, o vseh stalnih praznikih, o godovih naših.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 5, 'Ker ustanovljeno je v Izraelu, postava od Boga Jakobovega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 6, 'Kateri jo je za pričanje postavil v Jožefu, ko je šel proti deželi Egiptovski, kjer sem slišal govor neznan;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 7, '\"Odtegnil sem\", pravi, od bremena ramo njegovo; roke njegove ločile so se od čebriča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 8, 'Ko si vpil v oni stiski, rešil sem te, uslišal sem te v gromovem zakotji; izkušal sem te do vodâ Meribskih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 9, 'Poslušaj, ljudstvo moje, in spričeval ti bodem, o Izrael, ako me bodeš poslušal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 10, 'Ako ne bode v tebi boga mogočnega tujega, in se ne bodeš klanjal bogu mogočnemu tujerodnemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 11, 'Jaz sem Gospod, Bog tvoj, ki sem dal, da si prišel gor iz dežele Egiptovske; razširi usta svoja in napolnim jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 12, 'Ali ljudstvo moje ni poslušalo glasu mojega, in Izrael mi ni bil pokoren.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 13, 'Zatorej sem jih izpustil, da naj hodijo po srca svojega volji, govoreč: Gredó naj sè svojimi krivimi naklepi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 14, 'O ko bi me bilo poslušalo ljudstvo moje, ko bi bili Izraelci hodili po mojih potih!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 15, 'Kar mahoma bi bil potlačil njih neprijatelje, ko bi bil v njih sovražnike obrnil roko svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 16, 'Sovražniki Gospodovi bi se bili lažnjivo vdali njemu, in njih čas bi bil vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 17, 'Dà, živil bi ga bil z maščobo pšenično, tudi z medom iz skale bi te bil sitil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 1, 'Psalm Asafu. Bog biva v zboru Boga mogočnega, med oblastvi sodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 2, 'Doklej bodete sodili krivično, in potezali se za hudobne?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 3, 'Sodite za ubozega in siroto; nesrečnega in siromaka opravičite.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 4, 'Oprostite ubozega in potrebnega, iz roke krivičnih rešite.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 5, 'Ne vedó in ne pazijo, v temi hodijo neprestano; majó se vsi strebri zemlje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 6, 'Jaz pravim: \"Bogovi ste, in najvišjega sinovi vi vsi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 7, 'Todà, umrli bodete kakor navaden človek; tudi kakor kateri iz med ónih poglavarjev bodete padli.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 8, 'Vstani, o Bog, sodi zemljo; ti namreč imaš posest med vsemi narodi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 1, 'Pesem in psalm Asafu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 2, 'O Bog, ne molči, ne delaj se gluhega, in ne mirúj, o Bog mogočni!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 3, 'Ker glej, neprijatelji tvoji ropotajo, in sovražniki tvoji dvigujejo glavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 4, 'Zoper ljudstvo tvoje prekanjeno delajo naklep; in posvetujejo se zoper skrite tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 5, 'Rekoč: Dejte, potrebimo jih, da ne bodejo narod, da se ne bode več imenovalo ime Izraelovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 6, 'Ker naklep so storili z enakimi srci; zoper tebe so sklenili zavezo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 7, 'Šatori Idumejcev in Izmaeličanov, Moabljani in Agarenci;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 8, 'Gebaljani in Amonjani in Amalečani; Palestinjani s Tira prebivalci.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 9, 'Tudi Asirijan se jim je pridružil; roka so sinovom Lotovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 10, 'Stóri jim kakor Madijanom, kakor Sisaru, kakor Jabinu ob potoku Kisonu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 11, 'Ki so bili pokončani pri Endoru; postali so zemlje gnoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 12, 'Naredi njih plemenitnike same kakor Oreba, in kakor Zeba; kakor Zebaha in Salmuna vse njih poglavarje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 13, 'Kateri pravijo: Pridobimo prebivališča Božja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 14, 'Bog moj, naredi jih kakor kolo, kakor pleve pred vetrom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 15, 'Kakor ogenj požiga gozd, in kakor plamen vnema gore,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 16, 'Tako jih pódi z viharjem svojim; in z vrtincem svojim jih preplaši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 17, 'Sè sramoto napolni njih obličje; da se bode iskalo ime tvoje, o Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 18, 'Rudečica naj jih oblije, in zbegajo naj se večno; sramujejo se naj in poginejo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 19, 'Da se spozná, da si ti, kateremu edinemu je ime Gospod, vzvišen nad vesoljno zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 1, 'Načelniku godbe pri Giteji, sinovom Koretovim psalm.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 2, 'Kako ljuba so prebivališča tvoja, o Gospod vojnih krdél!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 3, 'Duša moja hrepeni in koprni, priti v veže Gospodove; srce moje in meso moje vpijeta v hrepenenji po živem Bogu mogočnem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 4, 'Celo vrabec najde dom in lastovka si gnezdo, da v njem izvali mladiče svoje – o oltarji tvoji, o Gospod vojnih krdél, kralj moj in Bog moj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 5, 'Blagor jim, ki so prebivali v hiši tvoji, ki te zdaj še hvalijo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 6, 'Blagor človeku, kateremu je dano v tebi stopati na steze tvoje po srca svojega želji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 7, 'Kateri gredé po murbini dolini, imajo njega za studenec, katere tudi pokriva dež blagoslova,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 8, 'Kateri hodijo od zbora do zbora, ki se prikaže pred Bogom na Sijonu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 9, 'Gospod, Bog vojnih krdél, čuj molitev mojo; poslušaj, o Bog Jakobov!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 10, 'Ščit naš, poglej, o Bog; in glej maziljenca svojega obličje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 11, 'Ker boljši en dan v vežah tvojih, nego tisoč drugjé; raji hočem stopati čez prag v hiši Boga mojega, nego prebivati v krivice šatorih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 12, 'Ker solnce in ščit je Gospod, Bog; milost in slavo daje Gospod; dobrega ne krati njim, ki hodijo v poštenosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 13, 'O Gospod vojnih krdél, blagor človeku, kateri ima zaupanje v tebe!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 1, 'Načelniku godbe med sinovi Koretovimi, psalm.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 2, 'Blagovoljen si bil, Gospod, deželi svoji; nazaj si bil pripeljal sužnje krdelo Jakobovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 3, 'Odpustil si bil krivico ljudstvu svojemu, pokril si bil ves njih greh.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 4, 'Potolažil si bil ves srd svoj, odvrnil, da ni kipela, jezo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 5, 'Postavi nas v prejšnji stan, o Bog blaginje naše; in potolaži nevoljo svojo proti nam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 6, 'Ali se bodeš večno jezil nad nami? raztezal jezo svoje od roda do roda?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 7, 'Ali ne bodeš vrnivši se nazaj nas postavil v življenje, da se ljudstvo tvoje raduje v tebi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 8, 'Pokaži nam, Gospod, milost svojo; in daj nam blaginjo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 9, 'Poslušal bodem, kaj govori, Bog ón mogočni Gospod, ker mir govori proti ljudstvu svojemu, in proti njim, katerim je milosten; ali k nespameti naj se ne povrnejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 10, 'Res, blizu je njim, ki se njega bojé, blaginja njegova; slava bode prebivala v deželi naši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 11, 'Milost in zvestoba se srečati; pravica in mir se poljubita.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 12, 'Zvestoba požene iz zemlje, in pravica pogleda z nebés.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 13, 'Tudi Bog bode dal, kar je dobro, da zemlja naša obrodi svoj sad.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 14, 'Storil bode, da pojde pravica pred njim, ko postavi noge svoje na pot.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 1, 'Molitev Davidova: Nagni, Gospod, uho svoje; usliši me, ker siromak sem in ubožen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 2, 'Reši dušo mojo, ker tisti sem, kateremu deliš milost; reši hlapca svojega, ti Bog moj, ko imam zaupanje v tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 3, 'Milost mi izkaži, Gospod; ker kličem te ves dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 4, 'Razveseli dušo svojega hlapca; ker do tebe, Gospod, povzdigujem dušo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 5, 'Ti namreč, Gospod, si dober in prizanašaš, in obilen v milosti vsem, ki te kličejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 6, 'Čuj molitev mojo, Gospod; in poslušaj prošenj mojih glas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 7, 'O času stiske svoje te kličem, ker uslišuješ me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 8, 'Ni ti enakega med vsemi bogovi, o Gospod; in dél ni tvojim enakih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 9, 'Vsi narodi, katerim jih deliš, prihajajočim, klanjajo se pred teboj, in čast dajó tvojemu imenu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 10, 'Ker velik si in čudovit, ti sam si Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 11, 'Uči me, Gospod, pot svoj; hodim naj dalje v resnici tvoji; zberi srce moje, da se boji tvojega imena.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 12, 'Slavil te bodem, Gospod Bog moj, iz vsega svojega srca; in čestil bodem imé tvoje vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 13, 'Ker velika je milost tvoja do mene, in rešil si dušo mojo iz spodnjega groba.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 14, 'O Bog, prevzetniki se spenjajo zoper mene, in silovitnikov krdela iščejo življenja mojega, ker te nimajo pred očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 15, 'Ti pa, Gospod, Bog mogočni, usmiljen si in milosten; potrpežljiv in obilen v milosti in zvestobi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 16, 'Ozri se v mé, in milost mi stórí; daj moč svojo hlapcu svojemu, in reši dekle svoje sina.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 17, 'Stóri znamenje nad menoj v dóbro; da naj vidijo sovražniki moji in se sè sramoto oblijó, ko mi bodeš ti, Gospod, pomagal, in potolažil me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 1, 'Sinom Koretovim psalm in pesem. Ustanovo svojo med svetosti gorami,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 2, 'Vrata Sijonska ljubi Gospod nad vsa prebivališča Jakobova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 3, 'Prečastno je karkoli se slaví o tebi, o mesto Božje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 4, 'Imenujem Egipčana in Babilonca med njimi, ki me poznajo; glej, Palestinca, in Tirca z Etijopjanom, da je ta rojen ravno tam;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 5, 'Zato se bode govorilo o Sijonu: Ta in ón mož jé rojen v njem; in on sam bode ga utrdil, Najvišji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 6, 'Gospod bode prišteval popisujoč ljudstva: ta je rojen ravno tam odlično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 7, 'Zatorej pojó enako in se radujejo vsi studenci življenja mojega v tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 1, 'Pesem in psalm med sinovi Koretovimi, načelniku godbe, da se poje na piščali, ukovit Emana Ezrajičana.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 2, 'O Gospod, Bog blaginje moje, podnevi kličem in ponoči v pričo tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 3, 'Pred obličje tvoje pridi molitev moja, nagni uho svoje mojemu vpitju.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 4, 'Ker nasitena je z nadlogami duša moja, in življenje moje se bliža grobu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 5, 'Prištevam se njim, ki gredó v grob; podoben sem možu, katerega zapušča krepost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 6, 'Prištevam se mrtvim, odločen; kakor prebodeni ležeči v grobu, katerih se ne spominjaš več, kateri so uničeni s tvojo roko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 7, 'Pokladaš me v grob, izmed vseh najglobočji, v najtamnejših, v krajih globokih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 8, 'Nad menoj leži jeza tvoja, dà, z vsemi valovi svojimi, ki me napadajo, pobijaš me presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 9, 'V stran od mene odvračaš znance moje, daješ me njim v najhujšo gnjusobo; tako zajetega, da pobegniti ne morem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 10, 'Oko moje žaluje od bridkosti; kličem te, Gospod, ves dan; k tebi razpenjam roke svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 11, 'Bodeš-li mrtvim delal dejanje čudovito? ali bodejo mrtvi vstali, da bi te slavili mogočno?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 12, 'Ali bi naj se v grobu oznanjala milost tvoja, zvestoba tvoja v pogubi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 13, 'Ali naj bi se v temini spoznalo čudovito dejanje tvoje, in pravica tvoja v pozabljivosti deželi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 14, 'In vendar jaz vpijem, Gospod, k tebi, in vsako jutro te prehiteva molitev moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 15, 'Zakaj me zametaš, o Gospod; skrivaš mi obličje svoje?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 16, 'Ubožen sem in umrjoč od potresa, strahove tvoje prenašam in sem zbegan,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 17, 'Jeze tvoje gredó čez mé, plašenje tvoje me uničuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 18, 'Obdajajo me kakor vode ves dan; obsezajo me vkup.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 19, 'Od mene v stran odvračaš prijatelja in tovariša; znancem svojim sem v tamnem kraji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 1, 'Ukovita pesem Etana Ezrajičana.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 2, 'Milosti Gospodove bodem prepeval vekomaj; od roda do roda bodem oznanjal z usti svojimi zvestobo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 3, 'Ker preverjen sem, da se bode vekomaj slavila milost tvoja; v samih nebesih bodeš utrdil zvestobo svojo, s katero si rekel:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 4, 'Sklenil sem zavezo z izvoljenim svojim, prisegel sem Davidu, svojemu hlapcu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 5, 'Da bodem na vekomaj utrdil seme tvoje in stavil prestol tvoj od roda do roda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 6, 'Zatorej slavé nebesa čudovito delo tvoje, Gospod; in zvestobo tvojo v zboru svetnikov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 7, 'Kdo namreč naj se enako čisla v gornjem oblaku Gospodu; primerja se Gospodu med sinovi mogočnih?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 8, 'Bog mogočni je strašán v zboru svetnikov, in čestit nad vse, kar ga obdaja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 9, 'O Gospod, Bog vojnih krdél, kdo je tebi enako mogočen, Gospod? Ker zvestoba tvoja te ogrinja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 10, 'Ti gospoduješ nad morja ponosom; ko se spenjajo valovi njegovi, ti jih krotiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 11, 'Ti si zdrobil, kakor prebodenega, Egipčana; z roko svoje moči si razkropil sovražnike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 12, 'Tvoja so nebesa in tvoja zemlja; vesoljni svet in česar je poln ustanovil si tí.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 13, 'Sever in jug, katera si ti ustvaril, Tabor in Hermon prepevajo o imenu tvojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 14, 'Ti imaš roko z močjo; krepka je tvoja roka, vzvišena desnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 15, 'Pravica in sodba sta za prebivališče tvojemu prestolu; milost in zvestoba hodita pred tvojim obličjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 16, 'Blagor ljudstvu, katero pozna trombe glas, hodi v svetlobi obličja tvojega, Gospod!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 17, 'V imenu tvojem radujejo se ves dan, in dvigujejo se v pravici tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 18, 'Ker slava si njih móči, in po blagovoljnosti tvoji dviguje se naš rog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 19, 'Gospod namreč je naš ščit in svetnika Izraelovega, našega kralja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 20, 'Tedaj si v prikazni nagovoril njega, kateremu milost deliš, ter mu rekel: \"Pomoč sem napravil zoper močnega, povzdignil izvoljenega iz ljudstva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 21, 'Našel sem Davida, svojega hlapca; pomazilil sem ga sè svetim oljem svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 22, 'Z njim bodi stanovitna roka moja, in dlan moja naj ga krepča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 23, 'Ne bode ga stiskal sovražnik, in krivici udani ga ne ne bode žalil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 24, 'Temuč starem izpred njegovega obličja neprijatelje njegove, in sovražnike udarim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 25, 'Tako mu bode pomagala zvestoba moja in milost moja, da se bode v mojem imenu povzdignil rog njegov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 26, 'Ker nad morje položim roko njegovo, in nad reke njegovo desnico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 27, 'On me bode klical: Ti oče moj; Bog moj mogočni in skala blaginje moje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 28, 'In jaz ga postavim za prvorojenca, povišanega nad zemeljske kralje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 29, 'Vekomaj mu ohranim milost svojo, in zaveza moja mu bode zvesta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 30, 'In vekomaj postavim seme njegovo in prestol njegov kakor so dnevi nebeški.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 31, 'Ako zapusté sinovi njegovi zakon moj, ne bodo hodili v sodbah mojih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 32, 'Ako oskrunijo postave moje, in se ne držé zapovedi mojih:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 33, 'Obiskal bodem sè šibo njih pregreho; z udarci njih krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 34, 'Milosti pa svoje mu ne odtegnem, in lagal ne bodem zoper zvestobo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 35, 'Oskrunil ne bodem zaveze svoje, ne izpremenil ust svojih besede.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 36, 'Enkrat sem prisegel pri svetosti svoji, Davidu ne bodem lagal:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 37, 'Da bode večno seme njegovo, in prestol njegov kakor solnce pred mano.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 38, 'Kakor luna bode stanoviten vekomaj, in kakor priče zveste na gornjem oblaku.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 39, 'Ti pa si zavrgel in zaničeval; razsrdil si se proti maziljencu svojemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 40, 'Zaničeval si hlapca svojega zavezo, oskrunil in vrgel na tla venčanje njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 41, 'Podrl si vse ograje njegove; trdnjave njegove si izpostavil razdrobljenju.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 42, 'Plenili so ga vsi popotniki, v zasramovanje je sosedom svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 43, 'Povzdignil si sovražnikov njegovih desnico, razveselil vse neprijatelje njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 44, 'Skrhal si tudi meča njegovega ostrino, in utrdil ga nisi v vojski.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 45, 'Storil si, da mine bleščoba njegova, in prestol njegov si pahnil na tla.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 46, 'Okrajšal si dnî mladosti njegove; pokril si ga sè sramoto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 47, 'Doklej, Gospod? bodeš li se skrival vekomaj? gorela bode kakor ogenj jeza tvoja?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 48, 'Spomni se mene, kako sem kratkih dni, kaj bi bil zastonj ustvaril vse otroke človeške?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 49, 'Kateri mož bi živel tako, da ne izkusi smrti, reši se sam groba?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 50, 'Kje so milosti one nekdanje, Gospod, katere si bil prisegel Davidu po zvestobi svoji?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 51, 'Spomni se, Gospod, sramote hlapcev svojih, da nosim v naročji svojem zasramovanje vseh ljudstev največjih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 52, 'S katerim so sramotili sovražniki tvoji, Gospod, s katerim so sramotili maziljenca tvojega stopinje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 53, 'Slava Gospodu vekomaj, zgódi se, še enkrat, zgódi se!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 1, 'Molitev Mojzesova, moža Božjega: O Gospod, ti si nam bil prebivališče od roda do roda,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 2, 'Ko niso bile še rojene gore, in nisi bil naredil zemlje in vesoljnega sveta, dà od vekomaj do vekomaj Bog si tí mogočni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 3, 'Pripraviš človeka tako daleč, da je potrt, govoreč: \"Povrnite se, sinovi človeški!\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 4, 'Ker če tisoč lét preide, v tvojih očéh so, kakor včerajšnji dan, in straža nočna.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 5, 'S povodnjo jih pokončaš, spanje so, zjutraj so kakor seno, ki mine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 6, 'Zjutraj, ko se je razcvelo, mine; pokosi in posuši se zvečer.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 7, 'Ker ginemo od jeze tvoje, in srd tvoj nas plaši:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 8, 'Pred oči si staviš krivice naše, skrivnosti naše v luč svojega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 9, 'Ker vsi dnevi naši ginejo v srdu tvojem; leta naša nam tekó misli enaka.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 10, 'V samih dnevih lét naših je sedemdeset let; ali (ako smo prav krepki) osemdeset let; celo kar je v njih najboljše, polno je truda in težav; ko to hitro mine, odletimo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 11, 'Kdo spozna jeze tvoje moč, ali srdú tvojega po strahu tvojem?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 12, 'Šteti nas úči naše dni tako, da dobimo srce modro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 13, 'Vrni se, Gospod! Doklej! in kesaj se zavoljo hlapcev svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 14, 'Nasiti nas vsako jutro z milostjo svojo, da pojemo in se radujemo vse svoje dni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 15, 'Razveséli nas, kakor si nas ponižaval mnogo dnî; mnogo let smo izkušali húdo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 16, 'Očitno bodi hlapcem tvojim delo tvoje, in lepota tvoja med njih sinovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 17, 'Na strani nam bodi prijetnost Gospoda, Boga našega, in delo naših rok podpiraj v nas; sámo delo, pravim, naših rok podpiraj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 1, 'Zaupajoč v zavetji Najvišjega, v senci Vsemogočnega neprestano prenočujoč');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 2, 'Pravim: V Gospodu je pribežališče moje in grad moj; Bog moj je, kateremu zaupam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 3, 'Ker on te bode rešil iz zanke tičarjeve, iz kuge pogubne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 4, 'S perotjo svojo te bode branil, ko bodeš pribežal pod peroti njegove; ščit in bran je zvestoba njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 5, 'Ne boj se nočnega strahú, pušice, ki leta podnevi;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 6, 'Pogube, ki lazi v temi, ne kuge, ki razsaja o poludné.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 7, 'Pade jih na eni strani tvoji tisoč, in desetkrat tisoč na desni tvoji, k tebi ne pride.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 8, 'Samo z očmi Svojimi bodeš pogledal in videl bodeš grešnikov povračilo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 9, 'Ko bodeš ti Gospoda, Boga pribežališča mojega, Najvišjega postavil za prebivališče svoje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 10, 'Ne bode priložnosti, da te zadene húdo, in šiba se ne približa tvojemu šatoru.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 11, 'Ker angelom svojim bode zapovedal zate, da te hranijo po vseh potih tvojih;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 12, 'Držé te z obema rokama, da ne zadeneš z nogo svojo ob kamen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 13, 'Po divjem levu bodeš hodil in po kači, teptal bodeš leva mladiča in zmaja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 14, '\"Ker je proti meni nagnen v ljubezni (pravi Bog), zato ga bodem otél; na višavo ga bodem postavil, ker pozna, ime moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 15, 'Kakor hitro me zakliče, uslišim ga; na strani mu bodem v stiski; otel ga bodem in počastil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 16, 'Nasitil ga bodem z dolgostjo lét, storil bodem, da uživa blaginjo mojo.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 1, 'Psalm in pesem, v sobote dan.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 2, 'Dobro je slaviti Gospoda, in prepevati tvojemu imenu, o Najvišji!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 3, 'Oznanjati vsako jutro milost tvojo, in zvestobo tvojo vsako noč;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 4, 'Na desetostrunje in na brenklje, na strune s premišljevanjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 5, 'Ker razveseljuješ me, Gospod, z delom svojim; prepeval bodem o dejanjih tvojih rôk.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 6, 'Kako velika so dela tvoja, Gospod; silno globoke so misli tvoje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 7, 'Mož neumen ne spozna, in nespameten ne zapazi tega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 8, 'Ko poganjajo krivični kakor trava in cvetó vsi, ki delajo krivico, zgodi se, da se pogubé vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 9, 'Ti pa, o Najvišji, si vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 10, 'Ker glej, sovražniki tvoji, Gospod, ker glej, sovražniki tvoji ginejo; razkropé se vsi, ki delajo krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 11, 'Rog moj pa zvišuješ kakor samorogov, oblivajoč me z oljem prisnim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 12, 'To gleda oko moje na zalezovalcih mojih, ušesa moja poslušajo o njih, ki se spenjajo v mé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 13, 'Kakor palma bode zelenel pravični, kakor cedra na Libanu bode rasel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 14, 'Vsajeni v hiši Gospodovi, v vežah Boga našega bodo poganjali mladike.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 15, 'V obilosti bodejo živeli še v sivosti, debeli bodejo in zeleneči;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 16, 'In oznanjali, da je pravičen Gospod, skala moja, in da ni nobene krivice v njem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 1, 'Gospod kraljuje z veličastvom oblečen, Gospod oblečen, z močjo se opasuje; utrjuje se vesoljni svet, da ne omahne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 2, 'Stanoviten je prestol tvoj, od onega časa, od vekomaj ti kraljuješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 3, 'Naj dvigujejo reke, o Gospod, dvigujejo naj reke šum svoj; dvigujejo naj reke bobnenje svoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 4, 'V šumu mnogih vodâ, ko se valé veličastni valovi morjá, veličastneji je Gospod v višavi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 5, 'Pričanja tvoja so trdna jako; v hiši tvoji je lepa svetost, o Gospod, na dnî dolžavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 1, '0 mogočni Bog maščevanj, Gospod, o mogočni Bog maščevanj, prisvéti!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 2, 'Dvigni se, o zemlje sodnik; daj povračilo prevzetnim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 3, 'Doklej prevzetni, Gospod, doklej se bodejo radovali prevzetni?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 4, 'Ustili se in govorili prevzetno, ponašali se vsi, ki delajo krivico?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 5, 'Zatirali ljudstvo tvoje, Gospod, in ponižávali tvoje posestvo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 6, 'Morili vdovo in tujca, in ubijali sirote?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 7, 'Govoreč: Ne vidi Gospod, in ne zapazi Bog Jakobov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 8, 'Čujte, o najneumnejši v ljudstvu, in najnespametnejši, kdaj bodete razumni?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 9, 'Ali on, ki je vsadil uho, ali bi on ne slišal? ali on, ki je naredil oko, ali bi ne videl?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 10, 'Ali on, ki pokori narode, ali bi ne grajal; ki uči ljudî modrosti, ali bi ne spoznal?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 11, 'Gospod pozna misli človeške, da so zgolj ničemurnost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 12, 'Blagor možu, katerega pokoriš, Gospod; in katerega učiš po zakonu svojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 13, 'Da mu pripraviš pokoj od dnî nadloge, ko se koplje krivičnemu jama.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 14, 'Ker Gospod ne zavrže ljudstva svojega, in posestva svojega ne zapusti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 15, 'Temuč noter do pravice se povrne sodba, in za njo vsi, ki so pravega srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 16, 'Kdo bi bil vstal záme zoper hudodelnike? kdo bi se bil postavil zame zoper one, ki delajo krivico?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 17, 'Ko bi mi ne bil Gospod, polna pomoč, malo da bi ne bilo življenje moje prebivalo v kraji molčanja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 18, 'Ko pravim: Omahuje noga moja, milost tvoja, o Gospod, me podpira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 19, 'Ko so mnoge misli moje pri meni, tolažbe tvoje razveseljujejo dušo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 20, 'Ali bi se družil s teboj prestol nadlog, njega, ki me nadleguje zoper postavo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 21, 'Njih, ki se četoma zbirajo proti pravičnega duši, in obsojajo kri nedolžnih?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 22, 'Dà, Gospod mi je za grad, in Bog moj za skalo mojega pribežališča,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 23, 'On obrača proti njim njih krivico, in njih hudobnost jih pokončuje, pokončuje jih Gospod, naš Bog.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 1, 'Dejte, prepevajmo Gospodu, ukajmo skali blaginje naše!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 2, 'Pojdimo pred obličje njegovo sè zahvaljevanjem, s psalmi mu ukajmo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 3, 'Ker Bog mogočni velik je Gospod, in velik kralj nad vse bogove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 4, 'V roki njegovi so najglobočji sledovi zemlje, v njegovi oblasti so gorâ moči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 5, 'Njegovo je sámo morje, ker on ga je naredil, in súha zemlja, katero so ustvarile roke njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 6, 'Pridite, priklonimo se in padimo na tla; pripognimo kolena pred Gospodom, kateri nas je naredil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 7, 'Ker on je Bog naš, mi pa ljudstvo paše njegove, in čeda vodbe njegove; danes če slišite glas njegov,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 8, '\"Ne okamenite srca svojega, kakor v prepiru, kakor o dnevi izkušnjave v puščavi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 9, 'Ko so me izkušali očetje vaši: izkusili so me in spoznali delo moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 10, 'Štirideset let sem imel preglavico s tistim rodom govoreč: Ljudstvo so srca tavajočega, in potov mojih ne poznajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 11, 'Njim sem prisegel v jezi svoji, da ne vnidejo v pókoj moj.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 1, 'Pójte Gospodu novo pesem, po vsej zemlji pojte Gospodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 2, 'Pojte Gospodu, blagoslavljajte ime njegovo, od dné do dné slavite blaginjo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 3, 'Oznanjujte med narodi čast njegovo, med vsemi ljudstvi čudovita dela njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 4, 'Velik je Gospod in hvaljen silno, čestit nad vse bogove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 5, 'Ker vsi bogovi ljudstev so maliki, Gospod pa je naredil nebesa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 6, 'Slava in lepota sta pred njim, moč in veličastvo v svetišči njegovem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 7, 'Dajajte Gospodu, ljudstev rodovine, dajajte čast in hvalo Gospodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 8, 'Dajajte Gospodu slavo njegovemu imenu; prinesite dar, in pridite k vežam njegovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 9, 'Uklanjajte se Gospodu v diki svetosti; vsa zemlja trepetaj pred obličjem njegovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 10, 'Govorile med narodi: Gospod kraljuje, utrdil se bode tudi vesoljni svet, da ne omahne; sodil bode ljudstva pravično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 11, 'Veselila se bodo nebesa, in zemlja se bode radovala: šumelo bode morje, in kar je v njem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 12, 'Radovalo se bode polje in kar je na njem; tedaj bode prepevalo vse drevje v gozdu;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 13, 'Pred obličjem Gospodovim, ko bode prišel; ker sodit pride zemljo; sodil bode vesoljni svet po pravici, in ljudstva po zvestobi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 1, 'Gospod kraljuje, radúj se zemlja, veselé se naj pokrajine premnoge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 2, 'Oblaki in temà ga obdajajo; pravica in sodba kraj njegovega prestola.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 3, 'Ogenj hodi pred njim in požiga okrog sovražnike njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 4, 'Bliski razsvetljujejo vesoljni svet njegov, vidi in trese se zemlja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 5, 'Goré se topé kakor vosek vpričo Gospoda, vpričo vse zemlje gospodarja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 6, 'Nebesa oznanjajo pravico njegovo; tako da vidijo vsa ljudstva čast njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 7, 'Osramoté se naj vsi, ki se ponašajo z maliki; klanjajo naj se mu vsi angeli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 8, 'Čuje in veseli se naj Sijon, in radujejo se hčere Judovske, zavoljo sodeb tvojih, Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 9, 'Ti namreč si Gospod, vzvišen nad vso zemljo; silno povišan si nad vse angele.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 10, 'Kateri ljubite Gospoda, sovražite húdo; duše svojih, katerim izkazuje milost, hrani, iz rok krivičnih jih otima.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 11, 'Luč se je rodila pravičnemu, in poštenim v srci radost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 12, 'Veselite se, pravični v Gospodu, in slavite spomin svetosti njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 1, 'Psalm. Pojte Gospodu novo pesem, ker storil je čudovita dela; blaginjo mu je prinesla desnica njegova, in dlan njegova, in roka njegove svestosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 2, 'Naznanil je Gospod blaginjo svojo, vpričo narodov samih razodel je pravico svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 3, 'Spomnil se je milosti svoje in zvestobe svoje proti hiši Izraelovi; vse pokrajine zemlje vidijo Boga našega blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 4, 'Ukajte Gospodu, vsa zemlja; s kričanjem pojte in prepevajte.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 5, 'Prepevajte Gospodu sè strunami, sè strunami in psalmovanjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 6, 'S trombami in bučanjem trobite pred kraljem Gospodom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 7, 'Morje šúmi in kar je v njem, vesoljni svet in prebivalci njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 8, 'Reke naj ploskajo z rokami, vkup naj pojó goré,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 9, 'Pred Gospodom, ki gré sodit zemljo; sodil bode vesoljni svet pravično, in ljudstva po pravici.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 1, 'Gospod kraljuje, trepetajo naj ljudstva, sedeč na Kerubih kraljuje, majaj se zemlja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 2, 'Kraljuje Gospod na Sijonu velik, in visok je nad vsa ljudstva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 3, 'Slavé naj ime tvoje veliko, čestito je in sveto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 4, 'Ti tudi kralj premočni, ki ljubiš sodbo; ti ustanavljaš, kar je pravično; sodbo in pravico doprinašaš ti v Jakobu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 5, 'Povišujte Gospoda, Boga našega, in priklanjajte se do podnožja nog njegovih; ker svet je.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 6, 'Mojzesa in Arona z duhovniki svojimi in Samuela z njimi, ki so klicali ime njegovo, uslišal je Gospod, takoj ko so ga klicali.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 7, 'V oblačnem stebru jih je ogovoril, ko so hranili pričanja njegova, in postavo, katero jim je bil dal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 8, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 9, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 1, 'Psalm v zahvaljevanje. Ukajte Gospodu vsi prebivalci zemlje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 2, 'Čestite Gospoda z radostjo; s petjem pridite pred obličje njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 3, 'Spoznajte, da je Gospod Bog, on je nas ustvaril (ne pa mí sebe), ljudstvo svoje in čredo paše svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 4, 'Vnidite skozi vrata njegova sè zahvaljevanjem, s hvalo v veže njegove; zahvaljujte se mu, blagoslavljajte ime njegovo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 5, 'Ker dober je Gospod, vekomaj je njegova milost; in od roda do roda zvestoba njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 1, 'Psalm Davidov: Milost in pravico bodem pel, tebi, o Gospod, prepeval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 2, 'Zapazil bodem na poštenem potu, ko prideš k meni; neprestano bodem hodil v poštenosti svojega srca v hiši svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 3, 'Stavil si ne bodem pred óči stvari pregrešne; delo njih sovražim, ki zavijajo v stran, držalo se me ne bode.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 4, 'Izprijeno srce bode daleč od mene; hudega ne bodem poznal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 5, 'Njega, ki pred menoj skrivno obrekuje bližnjega svojega, bodem iztrebil; človeka s prevzetnim očesom, srcem napihnenim ne bodem mogel trpeti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 6, 'Oči moje bodo se vpirale na resnične v deželi, da naj sedajo z menoj; kdor hodi po poštenem potu, on bode mi stregel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 7, 'Stanoval ne bode v moji hiši, kdor dela zvijačo; kdor govori laž, ne bode obstal pred mojimi očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 8, 'Vsako jutro bodem iztrebil vse krivične iz dežele, da potrebim iz mesta Gospodovega vse, ki delajo krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 9, '');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 1, 'Molitev za ubozega, ko je v stiski in pred Gospoda izliva premišljevanje svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 2, 'Gospod, čuj molitev mojo, in vpitje moje pridi do tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 3, 'Ne skrivaj mi obličja svojega, ko sem v stiski; nagni mi uho svoje, ko kličem; naglo me usliši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 4, 'Ker ginejo kakor dim dnevi moji; in kosti moje se sušé kakor pogorišče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 5, 'Zadeto vene kakor trava srce moje, ker pozabljam použivati svojo jed.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 6, 'Od glasú zdihovanja mojega drži se kost moja mojega mesa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 7, 'Podoben sem pelikanu v puščavi; kakor sova sem v podrtinah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 8, 'Vedno sem podoben samotnemu vrabcu na strehi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 9, 'Ves dan me sramoté sovražniki moji; zoper mene divjajoč prisezajo pri meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 10, 'Ker pepel jem kakor kruh; in pijače svoje mešam z jokom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 11, 'Zaradi nevolje tvoje in srdite jeze tvoje; ker vzdignil si me in vrgel me na tla.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 12, 'Dnevi moji so podobni senci, ki se je nagnila; in jaz sem se posušil kakor trava.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 13, 'Ti pa, Gospod, ostajaš vekomaj, in spomin tvoj od roda do roda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 14, 'Ti bodeš vstal in usmilil se Sijona, ker čas je storiti mu milost, ker prišel je čas določeni,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 15, 'Ko se naj hlapci tvoji veselé njegovega kamenja, in milost storé njegovemu prahu;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 16, 'Da česté narodi ime Gospodovo, in vsi kralji zemlje čast tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 17, 'Ko bode Gospod zidal Sijon in prikazal se v časti svoji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 18, 'Ozrl se bode v nazega molitev, in ne bode zametal njih molitve.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 19, 'Zapiše se naj to naslednjemu rodu, da ljudstvo poživljeno hvali Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 20, 'Ker pogledal bode z višave svetosti svoje Gospod, ozrl se z nebés na zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 21, 'Da usliši jetnika zdihovanje, da oprosti njé, ki se že izdajajo smrti;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 22, 'Da oznanjajo na Sijonu ime Gospodovo, in hvalo njegovo v Jeruzalemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 23, 'Ko se zbirajo ljudstva in kralji čestit Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 24, 'Pobija sicer na tem poti moči moje, dnî moje krajša,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 25, 'Ali govorim: Bog moj mogočni, ne vzemi me v sredi mojih dnî; skozi vse rodove so dnevi tvoji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 26, 'Predno si ustanovil zemljo, in so bila nebesa delo tvojih rok;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 27, 'Tisto bode prešlo, ti pa ostaneš; tisto, pravim, vse postara se kakor oblačilo; kakor obleko jih izpremeniš in izpremené se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 28, 'Ti pa si isti, in let tvojih ni konca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 29, 'Sinovi hlapcev tvojih bodo prebivali, in njih seme se utrdi pred teboj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 1, 'Davidova. Blagoslavljaj, duša moja, Gospoda; in vse osrčje moje svetost njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 2, 'Blagoslavljaj, duša moja, Gospoda; in ne pozabi nobene dobrote njegove,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 3, 'Kateri ti odpušča vse tvoje krivice, kateri ozdravlja vse bolezni tvoje;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 4, 'Kateri otima iz jame življenje tvoje, kateri te odeva z milostjo in usmiljenjem;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 5, 'Kateri napolnjuje z vsem dobrim usta tvoja, da se hraniš čilega kakor orel, kakor otročja leta tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 6, 'Kar je pravično, dela Gospod, in sodbe vsem zatiranim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 7, 'Razodel je Mojzesu pota svoja, naslednikom Izraelovim svoja dela.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 8, 'Usmiljen je in milosten Gospod; potrpežljiv in obilen v dobrotah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 9, 'Ne prepira se vekomaj; in večno ne hrani jeze.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 10, 'Ne dela nam po grehih naših, in ne povrača nam po naših krivicah;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 11, 'Temuč, kakor visoka so nebesa nad zemljo, močna je milost njegova proti njim, kateri se ga bojé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 12, 'Kakor daleč je vzhod od zahoda, daleč od nas odvrača pregreške naše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 13, 'Kakor se usmili oče otrok, usmili se Gospod njih, ki se ga bojé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 14, 'Ker on pozna podobo našo, spominja se, da smo prah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 15, 'Da so senu podobni človeka dnevi, kakor poljska cvetica, tako on cveté.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 16, 'Ko veter potegne čeznjo, skoraj je ni, in je ni več zagledati na mestu njenem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 17, 'Milost pa Gospodova je od veka do veka proti njim, ki se ga bojé, in pravica proti vnukom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 18, 'Proti njim, ki hranijo zavezo njegovo, in proti njim, ki se spominjajo njegovih zapovedi, da jih izpolnjujejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 19, 'Gospod je v nebesih postavil prestol svoj, in kraljestvo njegovo gospoduje ljudém.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 20, 'Blagoslavljajte Gospoda, angeli njegovi, premogočni v moči, ki izpolnjujete besedo njegovo in poslušate glas njegove besede.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 21, 'Blagoslavljajte Gospoda, vse vojske njegove, služabniki njegovi izpolnjujoči voljo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 22, 'Blagoslavljajte Gospoda, vsa dela njegova po vseh krajih njegovega gospostva; blagoslavljaj, duša moja Gospoda!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 1, 'Blagoslavljaj, duša moja Gospoda. Gospod, Bog moj, velik si silno, lepoto in veličastvo si oblekel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 2, 'Odevaš se z lučjo kakor z obleko; nebesa razpenjaš kakor zagrinjalo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 3, 'Kateri stavi v vode gornje hrame svoje; kateri nareja oblake za voz svoj, kateri hodéva po vetrov perotih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 4, 'Kateri dela vetrove za poslance svoje, za služabnike svoje ogenj plameneči,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 5, 'Ustanovil je zemljo na podstave njene, da se ne gane na vedno večne čase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 6, 'Z breznom si jo bil odél kakor z odejo, ko so vode stale čez gore.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 7, 'Na karanje tvoje so pobegnile, pred groma tvojega glasom bežale so urno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 8, 'Dvignile so se gore, pogreznile se doline na mesto, katero si jim bil ustanovil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 9, 'Mejo si postavil, da ne idejo čez, da se ne povrnejo, pokrit zemljo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 10, 'Kateri izpuščaš studence po dolinah, da hodijo med gorami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 11, 'Napajajo naj vse poljske živali; žejo svojo gasé divji osli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 12, 'Poleg njih prebivajo tice nebeške, glasijo se iz med listja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 13, 'Kateri móči goré iz gornjih hramov svojih, da se sè sadom dél tvojih zemlja pase.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 14, 'Daješ, da seno raste živini, in zelišče človeku za rabo, da jemlje hrano iz zemlje;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 15, 'Kateri z vinom razveseljuje srce človeku; z oljem svetlo dela čelo, in z jedjo podpira srce človeku.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 16, 'Siti se drevje Gospodovo; cedre na Libanonu, katere je vsadil;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 17, '(Kjer gnezdijo tički), jelke prebivališče štorklji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 18, 'Gore previsoke divjim kozlom, skale prebivališče gorskim mišim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 19, 'Postavil je mesec za čase gotove, solnce, ki pozna záhod svoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 20, 'Temé narejaš, da je noč, ko prilezejo vse gozdne živali.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 21, 'Mladi levi rjoveč po plenu, in iskajoč od Boga mogočnega hrane svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 22, 'O solnčnem vzhodu se poskrijejo in ležé v brlogih svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 23, 'Človek gre na delo svoje, in na polje svoje do večera.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 24, 'Kako veličastna so dela tvoja, o Gospod; kako modro si jih naredil vsa; kako polna je zemlja posesti tvoje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 25, 'V morji samem velikem in prostornem: tu so lazeče živali, in brez števila živali z velikimi male.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 26, 'Tod hodijo ladije; som, katerega si ustvaril, igrá se v njem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 27, 'Vse tó čaka tebe, da jim daš živeža o svojem času.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 28, 'Ko jim daješ ti, pobirajo; ko jim odpreš roko svojo sitijo se z dobroto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 29, 'Ko jim skriješ obličje svoje, zbegajo se; ko jim vzameš sapo, ginejo in povračajo se v svoj prah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 30, 'Ko izpuščaš sapo svojo, oživljajo se, obličje obnavljaš zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 31, 'Čast bodi Gospodu vekomaj; raduj se, Gospod, v delih svojih!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 32, 'Ko pogleda na zemljo, trese se ona; ko se dotakne gorâ, kadé se.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 33, 'Pel bodem Gospodu v življenji svojem; prepeval Bogu svojemu, dokler bodem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 34, 'Prijetno bode o njem premišljevanje moje, radoval se bodem jaz v Gospodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 35, 'Izginejo naj grešniki sè zemlje, in krivičnih več ne bódi; blagoslavljaj, duša moja, Gospoda. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 1, 'Slavite Gospoda, razglasujte ime njegovo; med ljudstvi oznanjujte dejanja njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 2, 'Pojte mu, prepevajte mu, razgovarjajte se o vseh čudovitih delih njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 3, 'Hvalite se v svetem imenu njegovem; veseli se naj srce njih, ki iščejo Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 4, 'Iščite Gospoda in moči njegove; iščite vedno njegovega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 5, 'Spominjajte se čudovitih del njegovih, katera je storil; čudežev njegovih in sodbâ ust njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 6, 'O seme Abrahama, njegovega hlapca; o izvoljeni sina njegovega Jakoba!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 7, 'Ta je Gospod, Bog naš, po vsej zemlji so sodbe njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 8, 'Spominja se vekomaj zaveze svoje, besede, katero je zapovedal na tisoč rodov,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 9, 'Katero je sklenil z Abrahamom, in prisege svoje Izaku,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 10, 'Katero je dal Jakobu v postavo; Izraelu v vedno zavezo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 11, 'Govoreč: Tebi hočem dati deželo Kanaansko, vrvco posesti vaše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 12, 'Dasí je bilo ljudî malo, prav malo, in tujci v njej,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 13, 'In so hodili od naroda do naroda, iz kraljestva k drugemu ljudstvu;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 14, 'Ni dovolil zatíratí jih nikomur; dà, strahoval je zavolje njih kralje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 15, 'Ne dotaknite se maziljencev mojih, in ne storite žalega prerokom.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 16, 'Ko je bil poklical lakot nad deželo, in kruhu strl vso podporo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 17, 'Poslal je bil moža pred njimi odličnega; kateri je bil v sužnjost prodan, Jožefa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 18, 'Noge njegove so vklenili z vezjo, v železo se je on podal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 19, 'Noter do časa, ko je imela priti beseda njegova; govor Gospodov ga je potrdil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 20, 'Poslal je kralj in velel ga razvezati; in poglavar ljudstev ga je oprostil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 21, 'Postavil ga je za gospoda družini svoji, in za poglavarja vsej svoji posesti,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 22, 'Da bi zvezaval kneze po volji svoji, in podučeval njih starejšine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 23, 'Nato je prišel Izrael v Egipt, in Jakob je tujčeval po deželi Kamovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 24, 'Ko je bil tam storil Bog, da je bilo ljudstvo njegovo silno rodovitno, in ga je bil močnejšega naredil od sovražnikov njegovih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 25, 'Izpremenil je njih srce, da so sovražili ljudstvo njegovo, da so naklepe delali zoper hlapce njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 26, 'Poslal je Mojzesa, hlapca svojega, Arona, katerega je bil izvolil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 27, 'Razlagala sta pred njimi besede znamenj njegovih, in čudežev v deželi Kamovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 28, 'Poslal je temé, in otemnile so jo, in upirala se niso znamenja zoper besedo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 29, 'Izpremenil je bil v kri njih vodé, in pokončal je bil njih ribe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 30, 'Obilo je rodila njih dežela žab, ki so napadle kraljev samih stanice.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 31, 'Ko je izrekel, prišlo je krdelo živali; uši na vso njih pokrajino.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 32, 'Dež jim je naredil v točo, ogenj silno plameneč v njih kraji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 33, 'S tem je zadel njih trte in njih smokve, in polomil njih pokrajine drevesa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 34, 'Ko je izrekel, prišla je kobilica in hrošč, in ta brez števila.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 35, 'On je požrl vso travo njih kraja, in požrl sad njih dežele.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 36, 'Slednjič je udaril vse prvorojeno v njih kraji; prvino vse njih moči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 37, 'Tedaj jih je izpeljal sè srebrom in zlatom, in ni ga bilo, da bi pešal, med njih rodovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 38, 'Veselili so se Egipčani, ko so izhajali tí; ker njih strah jih je bil obšel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 39, 'Razgrnil je oblak za odejo, in ogenj, da je noč razsvetljeval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 40, 'Prosili so, in poslal jim je prepelic, in s kruhom nebeškim jih je sitil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 41, 'In odprl je skalo, in pritekle so vode, ter šle so po suhih krajih, kakor reka.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 42, 'Ker se je spominjal besede svetosti svoje, z Abrahamom, hlapcem svojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 43, 'Zató je izpeljal ljudstvo svoje, z veseljem, s petjem izvoljene svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 44, 'In dal jim je kraje narodov, in delo ljudstev so posedli;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 45, 'Da se držé postav njegovih, in hranijo zakone njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 1, 'Aleluja! Slavite Gospoda, ker je dober, ker je vekomaj milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 2, 'Kdo bi dopovedal najvišjo moč Gospodovo, oznanil vso hvalo njegovo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 3, 'O blagor jim, ki se držé postave té, ki delajo pravico vsak čas!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 4, 'Spomni se me, Gospod, po blagovoljnosti, katero izkazuješ svojemu ljudstvu, obišči me z blaginjo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 5, 'Da uživam izvoljenih tvojih dobroto, da se radujem radosti naroda tvojega; da se s posestjo tvojo ponašam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 6, 'Grešili smo z očeti svojimi: krivično smo delali, ravnali hudobno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 7, 'Očetje naši niso umeli v Egiptu čudovitih dél tvojih; spominjali se niso milosti tvojih obilosti; temuč priliko so dajali izpremeniti jih pri morji, ko so stopali v morje trstovito.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 8, 'Vendar jih je rešil zavoljo imena svojega, da bi pokazal svojo moč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 9, 'Ker zarotil je trstovito morje, in posušilo se je; in peljal jih je skozi valove kakor skozi puščavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 10, 'Tako jih je rešil roke sovražnikove; otel jih je neprijateljeve roke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 11, 'Pokrile pa so vode njih sovražnike; eden izmed njih ni ostal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 12, 'Da sì so verjeli besedam njegovim, peli hvalo njegovo,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 13, 'Pozabili so naglo dél njegovih; čakali niso sveta njegovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 14, 'Ampak iz poželjivosti v puščavi izkušali so Boga mogočnega v samoti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 15, 'Tako da je podelivši jim, kar so prosili, poslal kugo nad nje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 16, 'Potem ko so bili nevoščljivi Mojzesu v šatorji, Aronu svetniku Gospodovemu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 17, 'Odprla se je zemlja in požrla Datana in zagrnila je drhal Abiramovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 18, 'In vnel se je ogenj v njih drhal, in s plamenom požgal krivične.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 19, 'Naredili so tele na Horebu, in klanjali so se podobi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 20, 'In premenivši čast svojo v podobo vola, ki travo jé,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 21, 'Pozabili so Boga mogočnega, rešitelja svojega, kateri je bil storil velike reči v Egiptu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 22, 'Čudovita dela v deželi Kamovi, strašna pri trstovitem morji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 23, 'Zatorej je rekel, da jih bode pogubil; ko bi ne bil Mojzes, izvoljenec njegov, stopil v ón predór pred njim, da bi odvrnil jezo njegovo, da jih ne pogubi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 24, 'Zavrgli so tudi zaželeno deželo, ne verujoč besedi njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 25, 'In godrnjaje v šatorih svojih niso poslušali glasú Gospodovega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 26, 'Zatorej je dvignil roko svojo ter prisegel, da jih podere v sami puščavi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 27, 'In da podere seme njih med narodi, in razkropi jih po deželah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 28, 'Razen tega so se združili tudi z malikom Peorjem, in jedli mrtvih daritve.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 29, 'Klicali so tako Boga v nevoljo z deli svojimi, da je pridrla nad nje nadloga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 30, 'Dokler ni vstal Pineas in storil sodbo, ter je bila ustavljena tista nadloga;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 31, 'Kar se mu je štelo za pravico, od roda do roda vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 32, 'Enako so razdražili gorečo jezo pri vodah prepira, tako da se je slabo godilo Mojzesu zavoljo njih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 33, 'Ko so bili razdražili duha njegovega, in je izgovoril z ustnami svojimi razdraženje svoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 34, 'Pokončali niso onih ljudstev, za katera jim je bil zapovedal Gospod;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 35, 'Ampak pomešali so se z onimi narodi in naučili se njih dél.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 36, 'In čestili so njih podobe, katere so bile njim v izpotiko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 37, 'Ker darovali so sinove svoje in hčere svoje hudobnim duhovom;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 38, 'In prelivali so nedolžno kri, kri sinov svojih in hčer svojih, katere so darovali podobam Kanaanskim, tako da je bila zemlja onečiščena z njih moritvami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 39, 'In oskrunjali so se sè svojimi deli; prešestvovali z dejanji svojimi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 40, 'Zatorej se je razsrdil Gospod nad ljudstvom svojim in studil svojo posest,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 41, 'Tako da jih je dal v roko narodom, da bi jim gospodovali njih sovražniki, črtilci,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 42, 'In jih zatirali njih neprijatelji, in da bi se poniževali pod njih roko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 43, 'Mnogokrat jih je rešil, dasì so ga bili razsrdili z naklepom svojim, in so bili ponižani zavoljo krivice svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 44, 'Ozrl se je na njih stisko, slišal je njih vpitje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 45, 'In spomnivši se zá nje zaveze svoje, kesal se je po obilosti milosti svojih;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 46, 'Tako da jim je izkazal usmiljenje pred vsemí, kateri so jih v sužnjosti imeli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 47, 'Reši nas, Gospod, Bog naš, in zberi nas izmed tistih narodov, da slavimo sveto ime tvoje, in se s hvaljenjem priporočamo v hvali tvoji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 48, 'Blagoslovljen Gospod, Izraelov Bog, od veka do veka in vse ljudstvo naj govori: Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 1, 'Slavite Gospoda, ker dober je; ker vekomaj je dobrota njegova!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 2, 'Govoré naj rešenci Gospodovi, katere je rešil iz stiske;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 3, 'Katere je zbral iz dežél od vzhoda in od zahoda, od severja in od morja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 4, 'Tavali so po puščavi, po potih samotnih, mesta za prebivališče niso našli;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 5, 'Lačni in žejni, njih duša je hirala v njh.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 6, 'Klicali so Gospoda v stiski svoji; iz njih nadloge jih je rešil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 7, 'In vodil jih je po pravem potu, da so prišli v prebivališča mesto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 8, 'Slavé naj pred Gospodom milost njegovo, in čudovita dela njegova pri sinovih človeških:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 9, 'Da on siti dušo potrebno, in dušo gladno napolnjuje z dobrim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 10, 'Kateri sedevajo v temoti in smrtni senci, v bridkosti sponah in v železu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 11, 'Ker so dali priliko, izpremeniti besedo Boga mogočnega, in zavrgli so sklep Najvišjega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 12, 'Srce njih ponižuje s tisto nadlogo; omahujejo in nihče ne pomaga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 13, 'Klicali so Gospoda v stiski svoji; rešil jih je iz njih nadloge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 14, 'Izpeljal jih je iz temin in smrtne sence, raztrgal je njih vezí.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 15, 'Slavé naj pri Gospodu milost njegovo, in čudovita dela njegova pri sinovih človeških.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 16, 'Da on razbija bronasta vrata, in razlomi zapahe železne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 17, 'Nespametni, zavoljo pota pregrehe, zavoljo krivic svojih so v bridkosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 18, 'Njih srce studi vsako hrano; bližajo se smrtnim durim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 19, 'Klicali so Gospoda v stiski svoji, rešil jih je iz njih nadloge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 20, 'Poslal je besedo svojo in ozdravil jih; in rešil iz njih jam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 21, 'Slavé naj pri Gospodu milost njegovo, in čudovita dela njegova pri sinovih človeških.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 22, 'In darujejo naj hvalne daritve ter oznanjajo s petjem dela njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 23, 'Kateri so šli na morje v ladijah, in so opravljali delo na širnih vodah;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 24, 'Oni vidijo dela Gospodova in čuda njegova v globočini:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 25, 'Kako ukaže in naplavi vihar, kateri dviguje valove njegove,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 26, 'Kako se spenjajo do neba, in padajo v globočine; njih duša koprni v nadlogi;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 27, 'Opotekajo se in gibljejo kakor pijani; in vsa njih spretnost gine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 28, 'Klicali so Gospoda v stiski svoji, rešil jih je iz njih nadloge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 29, 'Premenil je vihar v tišino, in utihnili so njih valovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 30, 'In vesele, ko so potihnili valovi, peljal jih je v brodišče zaželeno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 31, 'Slavé naj pri Gospodu milost njegovo, in dela čudovita njegova pri sinovih človeških.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 32, 'In poveličujejo naj ga v zboru ljudstva, in v seji starejšin naj ga hvalijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 33, 'Reke izpreminja v puščavo, in vode tekoče v tla suhotna;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 34, 'Zemljo rodovitno v solnato zavoljo hudobnih prebivalcev njenih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 35, 'Puščavo izpreminja v stoječo vodo in zemljo suhotno v vode tekoče.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 36, 'Storivši, da prebivajo tam lakotni, in ustanové mesto za prebivališče,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 37, 'In da posejejo njive in zasadé vinograde ter prideljujejo sad rodoviten.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 38, 'Blagoslavlja jih tako, da se množijo silno, in živine njih ne zmanjšuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 39, 'A zmanjšujejo se in uklanjajo hudobni v stiski in žalovanji,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 40, 'Ko izliva zaničevanje nad prvake in dela, da tavajo po praznoti brez potov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 41, 'In stavi na višavo siromaka, in kakor čedo množi rodovine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 42, 'Vidijo naj pravični in se veselé; vsa malopridnost pa zapri usta svoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 43, 'Kdorkoli je moder, vidi to in pazi na milost Gospodovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 1, 'Pesem in psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 2, 'Z radostnim srcem svojim, o Bog, bodem pel in prepeval, tudi slava moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 3, 'Vstanite, brenklje in citre; zbudim se sè zarijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 4, 'Slavil te bodem med ljudstvi, Gospod; in prepeval ti bodem med narodi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 5, 'Velika je nad nebesa milost tvoja, in noter do gornjih oblakov resnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 6, 'Povzdigni se nad nebesa, o Bog; in čez vso zemljo slava tvoja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 7, 'Da se rešijo izvoljeni tvoji, pomagaj z desnico svojo in usliši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 8, 'Bog jo govoril po svetosti svoji; radoval se bodem, v dél dobodem Sihem, in dolino Sukotsko merim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 9, 'Moj je Gilead, moj Manase, in Efrajm moč glave moje, Juda poveljnik moj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 10, 'Moab umivalnik moj; čez Edom vržem svoj čevelj; proti Palestini bodem ukal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 11, 'Kdo me popelje v utrjeno mesto, kdo me popelje do Edoma?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 12, 'Ali nisi bil ti, o Bog, zavrgel nas? da nisi hodil, o Bog, med našimi vojskami?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 13, 'Daj nam pomoč zoper sovražnika; drugače je ničevost pomoč človeška.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 14, 'V Bogu delajmo vrlo, in on bode poteptal sovražnike naše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 1, 'Načelniku godbe, psalm Davidov. O Bog hvale moje, ne delaj se gluhega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 2, 'Ker usta krivičnega in usta zvijačna so so odprla zoper mene; govorila so zoper mene z lažnjivim jezikom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 3, 'In z besedami sovražnimi so me obdali; pobijajo me po krivem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 4, 'Nasprotovali so mi za ljubezen mojo, s katero sem bil v molitvi,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 5, 'Vračajoč mi hudo za dobro, in sovraštvo za ljubezen mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 6, 'Daj mu krivičnega za gospoda, kateri mu naj nasprotujoč stoji na desni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 7, 'Ko pride pred sodbo, odide naj obsojen; in molitev njegova bodi mu v greh.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 8, 'Malo bodi dnî njegovih; drugi dobodi službo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 9, 'Otroci njegovi bodijo sirote, in vdova žena njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 10, 'In neprestano naj se klatijo in beračijo otroci njegovi, in iščejo naj miloščine iz krajev svojih zapuščenih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 11, 'Odrtnik naj zagrabi, karkoli ima, in tujci naj uplenijo delo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 12, 'Ne bodi mu nikogar, da mu dobroto pomolí, in ne bodi ga, da izkaže milost sirotam njegovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 13, 'Pokončan bodi zarod njegov, v drugem rodu bodi izbrisano njih ime.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 14, 'V spominu bodi krivica očetov njegovih pri Gospodu; in greh matere njegove se ne izbriši.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 15, 'Bodo naj vedno pred Gospodom, da iztrebi sè zemlje njih spomin.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 16, 'Zato ker se ni domislil izkazovati milost, ampak preganjal je moža ubozega in potrebnega in žalujočega, da ga usmrti;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 17, 'In želel je, da ga zadene prokletstvo, in ni se veselil blagoslova, temuč, da naj bode daleč od njega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 18, 'Da se obleče s prokletstvom, kakor z oblačilom svojim, in da vnide kakor voda vanj, in kakor olje v kosti njegove');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 19, 'Pridi mu, kakor sè suknjo naj se ogrinja, in kakor s pasom naj se opasuje z njim vedno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 20, 'To bodi plačilo nasprotujočih meni od Gospoda, in njih, kateri hudo govoré zoper dušo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 21, 'Ti pa, o Gospod, izkazuj mi milost zavoljo imena svojega, ker je dobra milost tvoja, reši me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 22, 'Ker ubožen sem in potreben, in srce moje je prebodeno sredi mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 23, 'Kakor senca, ko se nagiblje, odhajati sem primoran; kakor kobilico me podé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 24, 'Kolena moja se šibé od posta, in meso moje hujša, ker je pošla debelost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 25, 'Vrhu tega sem jim jaz v zasramovanje; ko me vidijo, majó z glavo svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 26, 'Pomagaj mi, o Gospod, Bog moj, reši me po milosti svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 27, 'Spoznajo naj, da je ta roka tvoja, da si ti, Gospod, to storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 28, 'Preklinjajo naj, ti blagoslavljaj; ko se osramoté, kateri so vstali, veseli se naj hlapec tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 29, 'Z nečastjo naj se odenejo nasprotniki moji, in ogrnejo se naj kakor s plaščem sè sramoto svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 30, 'Slavil bodem močno z usti svojimi Gospoda, in sredi mnogih bodem ga hvalil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 31, 'Ker stoji na desni siromaku, da ga reši njih, ki mu odsojajo življenje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 1, 'Psalm Davidov. Rekel je Gospod Gospodu mojemu: \"Sédi meni na desni, dokler ne denem sovražnikov tvojih nogam tvojim za podnožje.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 2, 'Palico močno tvojo bode poslal Gospod sè Sijona, govoreč: Gospoduj sredi sovražnikov svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 3, 'Ljudstvo tvoje je radovoljno o dnevi tvojih čét; v lepih krajih svetosti od materinega telesa bode ti mladosti tvoje rosa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 4, 'Prisegel je Gospod, in ne bode se kesal: Ti si duhovnik vekomaj po redu Melhizedekovem.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 5, 'Gospod na desni tvoji potare kralje o dnevi jeze svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 6, 'Sodil bode narode napolnjujoč z mrliči; razbijal glavo v premnogih krajih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 7, 'Iz potoka bode pil na potu, zatorej dvigne glavo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 1, 'Alejuja! Slavil bodem Gospoda iz vsega srca, v zboru pravičnih in shodu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 2, 'Velika dela Gospodova, razložena vsem, kateri se jih veselé,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 3, 'Slavno in krasno delo njegovo, in pravico njegovo, ki ostane vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 4, 'Spomin je napravil s čudeži svojimi; milosten in usmiljen je Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 5, 'Jedi je dal njim, ki se ga bojé; spominjal se vekomaj zaveze svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 6, 'Moč del svojih je naznanil ljudstvu svojemu, dal jim je posest narodov;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 7, 'Dela rok njegovih so resnica in pravica; stanovitne vse zapovedi njegove,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 8, 'Utrjene na večno in vekomaj, storjene zvesto in pravično.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 9, 'Rešenje je poslal ljudstvu svojemu in na vekomaj sklenil zavezo svojo; sveto in čestito je ime njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 10, 'Vir modrosti je strah Gospodov; najbolji uspeh vsem, ki delajo tako; hvala njegova ostane vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 1, 'Aleluja! Blagor mu, kdor, koli se boji Gospoda, v zapovedih njegovih raduje se močno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 2, 'Mogočno bode na zemlji seme njegovo; pravičnih rod se blagoslavlja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 3, 'Moč in bogastvo v hiši njegovi in pravica njegova ostane vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 4, 'V temi blišči luč pravičnih; milosten je, usmiljen in pravičen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 5, 'Kdor je dober, darí deli milostno in posoja; svoje reči vlada po dolžnosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 6, 'Ker vekomaj ne omahne; v večnem spominu je pravični.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 7, 'Hudega glasu se ne boji, z mirnim srcem svojim zaupajoč v Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 8, 'V srci svojem podprt se ne boji, dokler ne vidi hudega na sovražnikih svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 9, 'Razsiplje, daje potrebnim, pravica njegova ostane vekomaj; rog njegov se dviguje v časti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 10, 'Krivični pa vidi in se huduje, sè zobmí svojimi škripajoč koprní; krivičnih želja bode minila.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 1, 'Aleluja! Hvalite hlapci Gospodovi, hvalite ime Gospodovo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 2, 'Blagoslovljeno bodí ime Gospodovo, od zdaj na vekomaj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 3, 'Od vzhoda solnčnega do zahoda, hvaljeno ime Gospodovo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 4, 'Vzvišen nad vse narode je Gospod, nad sama nebesa slava njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 5, 'Kdo je enak Gospodu, Bogu našemu, kateri prebiva visoko?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 6, 'Kateri nizko dol gleda, v nebesih in na zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 7, 'Iz prahu povišuje ubozega, iz blata dviguje siromaka.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 8, 'Posaja ga med prvake, med ljudstva svojega prvake.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 9, 'Daje, da ona, ki je bila nerodovitna v družini, sedí mati otrok vesela. Aleluja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 1, 'Ko je izhajal Izrael iz Egipta, družina Jakobova izmed ljudstva tujega jezika:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 2, 'Bil je Juda svetišče njegovo, Izrael gospostvo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 3, 'Morje samo je videlo in bežalo, Jordan sam se je obrnil nazaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 4, 'Sami hribi so poskakovali kakor ovni, kakor mlada jagnjeta griči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 5, 'Kaj ti je bilo, morje, da si bežalo? o Jordan, da si se obrnil nazaj?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 6, 'O hribi, zakaj bi poskakovali kakor ovni? griči kakor jagnjeta mlada?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 7, 'Pred obličjem Gospodovim potresi se zemlja; pred obličjem Boga Jakobovega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 8, 'Kateri izpremeni samo skalo v stoječo vodo; kremenje v studenec vodâ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 1, 'Ne nam, Gospod, ne nam; temuč imenu svojemu daj čast, zavoljo milosti svoje, zavoljo zvestobe svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 2, 'Zakaj bi govorili narodi: Kje je sedaj njih Bog?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 3, 'Saj Bog naš je v samih nebesih, storí, karkoli mu je po volji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 4, 'Maliki njih sreberni in zlati, delo rok človeških,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 5, 'Usta imajo, pa ne govoré; oči, pa ne vidijo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 6, 'Ušesa imajo, pa ne slišijo; nos imajo, pa ne duhajo;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 7, 'Roke, pa ne tipajo; noge, pa ne hodijo; z grlom svojim ne črhnejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 8, 'Podobni so njim, ki jih delajo, kdorkoli jim zaupa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 9, 'Izrael, zaupaj Gospodu; pomoč je tém in ščit je tém.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 10, 'Vi iz družine Aronove, zaupajte Gospodu, pomoč je tém in ščit je tém.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 11, 'Boječi se Gospoda zaupajte Gospodu, pomoč je tém in ščit je tém.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 12, 'Gospod spomnivši se nas bode blagoslavljal; blagoslavljal družino Izraelovo, blagoslavljal družino Aronovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 13, 'Blagoslavljal boječe se Gospoda, male in velike vred.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 14, 'Množil vas bode Gospod, vas in otroke vaše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 15, 'Blagoslovljeni bodete Gospodu, kateri je narodil nebo in zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 16, 'Sama nebesa, nebesa so Gospodova; in zemlja, katero je dal sinom človeškim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 17, 'Ne kateri so umrli, hvalijo Gospoda; ne katerikoli gredó dol v kraj molčanja,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 18, 'Ampak mi bodemo blagoslavljali Gospoda; od sedaj do vekomaj. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 1, 'Dovolj mi je, da Gospod usliši glas moj, molitve moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 2, 'Ker je uho svoje nagnil meni, zatorej ga bodem klical svoje dni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 3, 'Ko me obdajajo smrtne bolečine, in me obhajajo grobne stiske; nadlogo in žalost nahajam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 4, 'Če kličem ime Gospodovo, govoreč: \"Rotim te, Gospod, reši dušo mojo!\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 5, 'Milosten je Gospod, in pravičen, Bog naš, pravim, usmiljen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 6, 'Preproste rešuje Gospod; ko sem ponižan, prinese mi blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 7, 'Povrni se v pokoj svoj, duša moja, ker Gospod je dobrotljiv tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 8, 'Ker si otél mene samega smrti, oči moje sólz, nogo mojo padca,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 9, 'Neprestano bodem hodil pred Gospodom, v krajih živečih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 10, 'Veroval sem, ko sem hotel to govoriti; jaz sem bil aboten čez mero.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 11, 'Jaz sem rekel hiteč: Vsak človek je lažnjiv.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 12, 'Kaj naj povrnem Gospodu? Vse dobrote njegove me premagujejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 13, 'Čašo vse blaginje bodem povzdignil in slavil ime Gospodovo,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 14, 'Obljube svoje opravljajoč Gospodu, skôraj pred vsem ljudstvom njegovim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 15, 'Draga je pred obličjem Gospodovim smrt njih, katerim izkazuje milost.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 16, 'Prosim, Gospod, ko sem jaz hlapec tvoj, hlapec tvoj sem, dekle tvoje sin; raztrgal si vezí moje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 17, 'Tebi naj darujem hvalno daritev, in slavim ime Gospodovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 18, 'Obljube svoje bodem opravljal Gospodu skoraj pred vsem ljudstvom njegovim;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 19, 'V vežah hiše Gospodove, sredi tebe, Jeruzalem. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 117, 1, 'Hvalite Gospoda vsi narodi, slavite ga vsa ljudstva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 117, 2, 'Ker obveljala je do nas milost njegova, in zvestoba Gospodova vekomaj. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 1, 'Slavite Gospoda, ker dober je, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 2, 'Reci sedaj Izrael, da je vekomaj milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 3, 'Rekó naj sedaj, kateri so iz rodovine Aronove, da je vekomaj milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 4, 'Rekó naj sedaj, kateri se bojé Gospoda, da je vekomaj milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 5, 'Iz stiske same sem klical Gospoda, odgovoril je in postavil me na širjavo Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 6, 'Gospod mi je na strani; ne bodem se bal, kaj bi mi storil človek?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 7, 'Gospod mi je na strani z mojimi pomočniki; zatorej jaz zaničujem sovražnike svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 8, 'Boljše je pribegati h Gospodu, nego zaupanje imeti v kakega človeka.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 9, 'Boljše je pribegati h Gospodu, nego zaupanje imeti v prvake.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 10, 'Vsi narodi so me bili obdali; ali v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 11, 'Zopet in zopet so me bili obdali, ali v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 12, 'Obdali so me bili kakor čebele; ugasnili so kakor trnjev ogenj, ker v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 13, 'Močno si me bil pahnil, da bi padel; ali Gospod mi je bil na pomoč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 14, 'Moč moja in pesem Gospod, on mi je bil v blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 15, 'Glas petja in blaginje je v šatorih pravičnih, govoreč: Desnica Gospodova dela vrlo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 16, 'Desnica Gospodova povzdignena, desnica Gospodova dela vrlo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 17, 'Ne bodem umrl, ampak živel, da oznanjam dela Gospodova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 18, 'Ostro me je pokoril Gospod; ali smrti ni me izdal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 19, 'Odprite mi vrata pravice, da vnidem skozi njé in slavim Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 20, 'Ta so prava vrata do Gospoda, skozi katera vhajajo pravični.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 21, 'Slavil te bodem, ker si me uslišal in bil mi v blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 22, 'Kamen, katerega so bili zavrgli zidarji, on je za vogelni kamen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 23, 'Od Gospoda je on, čudovit je v naših očéh.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 24, 'Ravno ta dan je storil Gospod, radujmo in veselimo se v njem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 25, 'Prosim, Gospod, reši zdaj; prosim, Gospod, dobro srečo daj zdaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 26, 'Slava mu, ki gre v imenu Gospodovem; blagoslavljamo vas, iz hiše Gospodove,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 27, 'Boga mogočnega Gospoda, ki nas je razsvetlil. Zvezujte daritve praznične z vrvmi noter do oltarjevih rogóv.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 28, 'Bog mogočni si moj, zato te bodem slavil, Bog moj, bodem te poviševal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 29, 'Slavite Gospoda, ker dober je, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 1, 'Alef. Blagor poštenim na potu, kateri hodijo po postavi Gospodovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 2, 'Blagor njim, ki hranijo pričanja njegova, ki ga iščejo iz vsega srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 3, 'Kateri tudi ne delajo krivice, ampak hodijo po potih njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 4, 'Ti si zapovedal ukaze svoje, da naj se spolnjujejo pridno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 5, 'O da bi bila pota moja obernena spolnjevat postave tvoje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 6, 'Tedaj se ne osramotim, ko bodem gledal vse zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 7, 'Slavil te bodem s pravim srcem; učil se sodbâ pravice tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 8, 'Postave tvoje bodem spolnjeval, ne zapusti me tako!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 9, 'Bet. Kako bode deček čistil stezo svojo? Držeč se je poleg besede tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 10, 'Iz vsega srca svojega te iščem, ne daj, da izgrešim zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 11, 'V srci svojem hranim govor tvoj, da ne grešim zoper tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 12, 'Ti blagoslavljeni Gospod, uči me postave svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 13, 'Z ustnami svojimi preštevam vse pravice tvojih ust,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 14, 'Veselim se pota pričanj tvojih, kakor vseh zakladov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 15, 'Zapovedi tvoje premišljujem in gledam steze tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 16, 'V postavah tvojih se razveseljujem, besede tvoje ne zabim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 17, 'Gimel. Dobroto podéli hlapcu svojemu, dokler živim spolnjujem naj besedo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 18, 'Odgrni oči moje, da gledam čuda po zakonu tvojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 19, 'Tujec sem na tej zemlji, ne skrivaj mi zapovedi svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 20, 'Ginem od hrepenenja po pravicah tvojih vsak čas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 21, 'Ti pogubljaš prevzetne, proklete, kateri izgrešajo zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 22, 'Odvali od mene sramoto in zaničevanje, ker hranim pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 23, 'Tedaj prvaki sedé in govoré zoper mene, hlapec tvoj premišlja postave tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 24, 'Tedaj so pričanja tvoja razveseljevanja moja, svetovalci moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 25, 'Dalet. V prahu tiči življenje moje, živega me ohrani po besedi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 26, 'Pota svoja sem prešteval, in ti si me uslišal; úči me postave svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 27, 'Daj, da umem pot zapovedi tvojih, da premišljam čuda tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 28, 'Od otožnosti solzi duša moja, dvigni me po besedi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 29, 'Krivičnosti pot odvrni od mene, in zakon svoj mi podéli milostno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 30, 'Resnice pot volim, sodbe tvoje imam pred očmi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 31, 'Držim se pričanj tvojih, Gospod; ne daj, da se osramotim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 32, 'Po potih zapovedi tvojih bodem tekal, ko bodeš razširil srce moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 33, 'He. Uči me, Gospod, postav tvojih pót, katero bodem hranil do konca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 34, 'Daj, da umem, da hranim zakon tvoj, in da ga spolnjujem iz vsega srca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 35, 'Daj, da hodim po zapovedi tvojih poti, ker tá me razveseljuje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 36, 'Nagni srce moje k postavam svojim, in ne k dobičku.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 37, 'Odvrni oči moje, da ne gledajo ničemurnosti; po potih tvojih daj da živim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 38, 'Stóri govor svoj hlapcu svojemu, kateri je vdan strahu pred teboj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 39, 'Odvrni sramoto mojo, katere se bojim, ker dobre so pravice tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 40, 'Glej, ukazov tvojih želim, v pravici tvoji daj mi živeti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 41, 'Vav. Ko mi bodejo prišle milosti tvoje, Gospod; blaginja tvoja po govoru tvojem,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 42, 'Odgovoril bodem njemu, ki me sramoti, kakor je; ker zaupanje imam v besedo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 43, 'Ali od ust mojih ne odvzemi besede svoje resnične; ker pravic tvojih čakam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 44, 'In spolnjeval bodem zakon tvoj vedno, vekomaj in vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 45, 'In neprestano bodem hodil po sami širjavi, ker povelj tvojih iščem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 46, 'In govoril bodem o pričanjih tvojih pred kralji, in ne bode me sram.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 47, 'In razveseljujoč se v zapovedih tvojih, katere ljubim,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 48, 'Dvignil bodem roke svoje do povelj tvojih, katera ljubim, in premišljeval postave tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 49, 'Zajin. Spomni se besede svoje s hlapcem svojim, o kateri si mi dal upanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 50, 'To je tolažilo moje v bridkosti moji; da me govor tvoj oživlja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 51, 'Prevzetniki se mi posmehujejo silno, od postave tvoje ne zavijem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 52, 'Spominjam so sodbà tvojih od vekomaj, Gospod, in samega sebe tolažim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 53, 'Vihar me grabi od krivičnih, ki zapuščajo zakon tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 54, 'Prepevanju predmet so mi postave tvoje v kraji popotovanj mojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 55, 'Ponoči se spominjam imena tvojega, Gospod; in zakon tvoj spolnjujem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 56, 'To je tolažba meni, da hranim zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 57, 'Het. Delež moj si, Gospod, pravim, da spolnjujem besede tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 58, 'Obličje tvoje molim iz vsega srca svojega; milost mi izkaži po govoru svojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 59, 'Pota svoja premišljam, da obračam noge svoje po pričanjih tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 60, 'Hitim in se ne mudim spolnjevat zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 61, 'Krdela krivičnih me plenijo, a postave tvoje ne zabim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 62, 'O polunoči vstajam slavit te, zavoljo zapovedi tvojih pravičnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 63, 'Tovariš sem vsem, kateri te česté in spolnjujejo povelja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 64, 'Milosti tvoje, o Gospod, polna je zemlja; postave svoje me úči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 65, 'Tet. Dobro si storil hlapcu svojemu, Gospod; po besedi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 66, 'Izvrstnost pameti in vednosti me úči; ker zapovedim tvojim verujem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 67, 'Ko nisem še govoril, motil sem se; sedaj pa spolnjujem govor tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 68, 'Dober si in dobrotljiv, úči me postave svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 69, 'Ko zvijačo napravljajo zoper mene prevzetniki, jaz iz vsega srca hranim povelja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 70, 'Debelí se kakor z mastjo njih srce; jaz se zakona tvojega radujem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 71, 'Na dobro mi je bila bridkost, da bi se učil postav tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 72, 'Boljši mi je zakon tvojih ust nego mnogo tisoč zlatnikov in srebernikov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 73, 'Jod. Roke tvoje so me naredile in napravile me; storí me razumnega, da se učim povelj tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 74, 'Boječi se tebe naj me vidijo ter se veselé, ker imam v besedi tvoji nado svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 75, 'Spoznavam, Gospod, da so pravične sodbe tvoje; in da si me v zvestobi ponižal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 76, 'Pridi skoraj milost tvoja, da me tolaži, po govoru tvojem s tvojim hlapcem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 77, 'Dojdejo naj mi usmiljenja tvoja, da živim; ker zakon je vse razveseljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 78, 'Osramoté se naj prevzetniki, ker mi hudo delajo po krivem, ko premišljujem povelja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 79, 'Povrnejo se naj k meni boječi se tebe in poznajoči pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 80, 'Srce moje bode pošteno v postavah tvojih, da se ne osramotim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 81, 'Kaf. Duša moja koperni po blaginji tvoji; v besedi tvoji imam nado.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 82, 'Oči moje koperné po govoru tvojem, ko govorim: Kedaj me bodeš potolažil?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 83, 'Dasì sem podoben mehu v dimu, postav tvojih nisem pozabil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 84, 'Koliko bode dnî hlapca tvojega? Kedaj bodeš sodil nje, ki me preganjajo?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 85, 'Jame mi kopljejo prevzetniki, kateri se ne ravnajo po zakonu tvojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 86, 'Vsa povelja tvoja zgolj resnica; po krivem me preganjajo, pomagaj mi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 87, 'Skoraj so me uničili vrženega na tla; jaz pa se nísem izneveril postavam tvojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 88, 'Po milosti svoji ohrani me živega, da spolnjujem pričanja tvojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 89, 'Lamed. Vekomaj, o Gospod, biva beseda tvoja v nebesih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 90, 'Od roda do roda zvestoba tvoja; ko si ustanavljal zemljo, stala je ona.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 91, 'Po sodbah tvojih stoji vse še danes; ker vse ono služi tebi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 92, 'Ako bi ne bil zakon tvoj vse razveseljevanje moje, zdavnaj že bi bil poginil v nadlogi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 93, 'Vekomaj ne pozabim povelj tvojih, ker z njimi hraniš me živega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 94, 'Tvoj sem, hrani me, ker povelj tvojih iščem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 95, 'Ko me čakajo krivični, da me pogubé, pregledujem pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 96, 'Sleherne popolnosti vidim da je konec; povelje tvoje pa je obširno silno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 97, 'Mem. Kako ljubim zakon tvoj! ves dan je premišljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 98, 'Modrejšega od sovražnikov mojih me dela po poveljih tvojih; ker vekomaj mi je na strani.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 99, 'Razumnejši postajam od vseh učenikov svojih; ker pričanja tvoja so premišljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 100, 'Razumnejši sem od starcev, ker hranim povelja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 101, 'Od vsake hudobne steze zadržujem noge svoje, da spolnjujem besedo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 102, 'Od sodbâ tvojih se ne ganem, ker ti me učiš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 103, 'Kako sladki so mojemu grlu govori tvoji! sladkejši od medú ustom mojim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 104, 'Po poveljih tvojih sem razumen, zatorej sovražim vsako stezo krivičnosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 105, 'Nun. Svetilo nogi moji je beseda tvoja, in poti moji luč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 106, 'Prisegel sem, kar bodem držal, da bodem spolnjeval pravične sodbe tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 107, 'Ponižan sem silno, Gospod; živega me ohrani, po besedi svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 108, 'Prostovoljne daritve ust mojih sprejemaj, prosim, Gospod; in pravice svoje me úči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 109, 'Duša moja je vedno v roki moji; vendar ne zabim tvojega zakona.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 110, 'Mogočni krivičniki mi stavijo zanko, vendar od povelj tvojih ne zajdem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 111, 'Pričanja tvoja imam vekomaj, ker so veselje mojemu srcu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 112, 'Srce svoje nagibljem, da spolnjuje postave tvoje, vekomaj, večno!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 113, 'Sameh. Misli druge sovražim, zakon pa tvoj ljubim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 114, 'Zatišje si moje in ščit moj; v besedi tvoji imam nado.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 115, 'Umaknite se od mene, hudobni, da hranim ukaze svojega Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 116, 'Podpiraj me po govoru svojem, da živim; in ne osramoti me v nadi moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 117, 'Podpiraj me, da bodem otét, in da gledam vedno na postave tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 118, 'Vse, kateri izgrešujejo postave tvoje, teptaš; ker krivična je njih zvijača.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 119, 'Kakor žlindro odpravljaš vse krivične sè zemlje; zatorej ljubim pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 120, 'Od strahú pred teboj trepeče meso moje; tako me je strah tvojih sodbâ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 121, 'Hajin. Po sodbi delam in pravici; ne izročaj me njim, ki me stiskajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 122, 'Porok bodi hlapcu svojemu na dobro; da me ne zatirajo prevzetni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 123, 'Oči moje koperné po blaginji tvoji, in po pravičnem govoru tvojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 124, 'Ravnaj po milosti svoji s hlapcem svojim; in postave svoje me úči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 125, 'Hlapec sem tvoj, storí me razumnega, da spoznam pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 126, 'Čas je, da dela Gospod; v nič dévajo zakon tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 127, 'Zatorej bolj ljubim ukaze tvoje, ko zlato in sicer najčistejše.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 128, 'Zato spoznavam vse ukaze za prave; vsako stezo krivičnosti sovražim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 129, 'Pe. Čudovita so pričanja tvoja; zatorej jih hrani duša moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 130, 'Dohod besed tvojih razsvetljuje; z razumnostjo podučuje preproste.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 131, 'Usta svoja raztezam in sopiham; ker želján sem ukazov tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 132, 'Ozri se v mé in storí mi milost; kakor je prav proti njim, kateri ljubijo ime tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 133, 'Noge moje utrdi v govoru svojem, in ne daj da gospoduje kaka krivica z menoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 134, 'Otmi me zatiranja ljudî, da spolnjujem postave tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 135, 'Daj, da sveti tvoje obličje pred hlapcem tvojim; in úči me postave svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 136, 'Potoki vodâ tekó iz mojih oči, zaradi njih, ki ne spolnjujejo tvojega zakona.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 137, 'Sade. Pravičen si, Gospod, in raven v sodbah svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 138, 'Ukazal si pravična pričanja svoja, in silno zvesta.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 139, 'Od gorečnosti svoje ginem, ker besede tvoje zabijo sovražniki moji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 140, 'Čist je govor tvoj močno; zatorej ga ljubi hlapec tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 141, 'Majhen sem jaz in zaničevan; povelj tvojih ne zabim,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 142, 'Pravice tvoje, vedne pravice, in postave tvoje resnične.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 143, 'Zatiranje in stiska me obhajati; ukazi tvoji so razveseljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 144, 'Pravica pričanj tvojih je vekomaj; razumnega me naredi, da živim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 145, 'Kof. Ko te kličem iz vsega srca, usliši me, Gospod, da hranim postave tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 146, 'Ko te kličem, reši me, da spolnjujem pričanja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 147, 'Préd te pridem v somraku, da vpijem; v besedo tvojo imam upanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 148, 'Oči moje prehitujejo straže, premišljat govor tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 149, 'Glas moj poslušaj po milosti svoji, Gospod; po sodbah svojih ohrani me živega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 150, 'Ko se bližajo pregrehe učenci, ki so daleč od zakona tvojega,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 151, 'Blizu si, Gospod; in vsi ukazi tvoji so resnica.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 152, 'Zdavnaj vem o pričanjih tvojih, da si jih ustanovil vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 153, 'Reš. Ozri se v nadlogo mojo, in reši me; ker zakona tvojega ne zabim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 154, 'Prevzemi pravdo mojo in reši me; po govoru svojem ohrani me živega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 155, 'Daleč od krivičnih bodi blaginja, ker ne iščejo postav tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 156, 'Usmiljenje tvoje je obilo, Gospod; po sodbah tvojih, ohrani me živega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 157, 'Dasì je mnogo preganjalcev mojih in sovražnikov mojih, od pričanj tvojih ne krenem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 158, 'Kakor hitro vidim izdajalce, mučim z gnjusom samega sebe, ker se ne držé govora tvojega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 159, 'Glej, da ljubim povelja tvoja, Gospod; po milosti svoji ohrani me živega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 160, 'Preblaga beseda tvoja je sama resnica; in vekomaj je vsaka pravična sodba tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 161, 'Šin. Ko me preganjajo po nedolžnem prvaki; boji se besede tvoje moje srce.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 162, 'Veselim se govora tvojega; kakor kdor je našel plen obilen.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 163, 'Krivičnost sovražim in studim, zakon tvoj ljubim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 164, 'Sedemkrat te hvalim na dán za pravične sodbe tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 165, 'Velik mir imajo, kateri ljubijo zakon tvoj, in ní jim izpotike.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 166, 'Blaginje tvoje čakam, Gospod; in ukaze tvoje spolnjujem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 167, 'Duša moja spolnjuje pričanja tvoja, in ljubim jih močno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 168, 'Povelja tvoja spolnjujem in pričanja tvoja, ker vsa pota moja so pred teboj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 169, 'Tav. Vpitje moje se bližaj tvojemu obličju, Gospod; po besedi svoji naredi me umnega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 170, 'Molitev moja pridi pred obličje tvoje; po govoru svojem otmi me.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 171, 'Hvala bodo vrela z ustnic mojih, ko me bodeš učil postave svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 172, 'Jezik moj bode prepeval govor tvoj, da so prepravične vse zapovedi tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 173, 'V pomoč mi bodi na strani roka tvoja; ker volim povelja tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 174, 'Po blaginji tvoji hrepenim, Gospod; in zakon tvoj je vse razveseljevanje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 175, 'Živi duša moja, da hvali tebe; in sodbe tvoje naj pomagajo meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 176, 'Potikam se kakor ovca izgubljena, išči svojega hlapca; ker povelj tvojih ne zabim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 1, 'Pesem preizvrstna. Gospoda sem klical v največji stiski svoji, in uslišal me je.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 2, 'Gospod, reši me ustne lažnjive, zvijačnega jezika.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 3, 'Kaj naj ti dá, ali kaj pridene jezik zvijačni?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 4, 'Besede podobne ostrim pušicam mogočnega, primérne žarjavici brinjevi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 5, 'Gorjé meni, ker popotujem toliko časa, stanujem kakor prebivalci šatorov Kedarski.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 6, 'Predolgo zdí se duši moji da je prebivala pri sovražniku mirú.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 7, 'Jaz ljubim mir, ali ko govorim, kličejo oni na boj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 1, 'Pesem preizvrstna. Oči svoje naj bi povzdignil na one gore? Od kod naj mi pride pomoč?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 2, 'Pomoč moja bodi od Gospoda, kateri je naredil nebesa in zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 3, 'Naj ne dopusti, da omahne noga tvoja, varuh tvoj naj ne spí.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 4, 'Glej, ne dremlje in ne spí varuh Izraelov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 5, 'Gospod varuh tvoj, Gospod je senca tvoja na desni roki tvoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 6, 'Podnevi te ne bode zadevalo solnce, ali mesec ponoči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 7, 'Gospod te bode varoval vsega zlega, varoval bode dušo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 8, 'Gospod bode varoval hojo tvojo, od tega časa do vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 1, 'Pesem preizvrstna Davidova. Veselim se tega, ker se mi pravi: Pojdimo v hišo Gospodovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 2, 'Noge naše stojé med vrati tvojimi, o Jeruzalem!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 3, 'Jeruzalem, prelepo zidan, mesto, katero je popolnem zvezano med sabo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 4, 'Kamor hodijo rodovi, rodovi Gospodovi po pričanji Izraelcev, slavit ime Gospodovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 5, 'Ker tam stojé prestoli pravice, prestoli hiše Davidove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 6, 'Prosite mir Jeruzalemu govoreč: Mirni naj bodejo kateri ljubijo tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 7, 'Mir bodi v ozidji tvojem, pokoj v palačah tvojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 8, 'Zavoljo bratov mojih in prijateljev mojih govorim sedaj: Mir v tebi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 9, 'Zavoljo hiše Gospodove, Boga našega, pripravim ti dobro.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 1, 'Pesem preizvrstna. K tebi dvigam oči svoje, o ti, ki sediš v nebesih!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 2, 'Glej, kakor hlapcev oči gledajo na roke gospodov svojih, kakor dekle oči na roke gospodinje svoje, tako oči naše v Gospoda, Boga našega, dokler nas ne pomilosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 3, 'Pomilosti nas, Gospod, pomilosti; ker dovolj je, siti smo zaničevanja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 4, 'Dovolj je sita duša naša; tisto zasmehovanje onim pokojnim, tisto zaničevanje prevzetnim!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 1, 'Pesem preizvrstna Davidova. Ako bi nam Gospod ne bil pomagal, reci zdaj Izrael;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 2, 'Ako bi nam Gospod ne bil pomagal, ko so vstajali zoper nas ljudje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 3, 'Žive bi nas bili tedaj pogoltnili, ko je njih jeza togotila se zoper nas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 4, 'Tedaj bi nas bile poplavile one vode; hudournik bi bil šel čez nas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 5, 'Tedaj bi bil šel čez nas hudournik vode silno prevzetne.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 6, 'Blagoslovljen Gospod, ki nas ni izpostavil za plen njih zobom!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 7, 'Duša naša je bila kakor tičica oteta tičarjev zanke; iz zanke pretrgane smo bili mi oteti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 8, 'Pomoč naša v imenu Gospoda, ki je naredil nebesa in zemljo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 1, 'Pesem preizvrstna. Kateri zaupajo Gospodu, podobni so gori Sijonski, ki se ne gane, vekomaj ostane.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 2, 'Kakor obdajajo Jeruzalem gore, tako obdaja Gospod ljudstvo svoje; od tega časa na vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 3, 'Ker šiba krivice ne počiva nad deležem pravičnih; da ne iztegnejo pravični na nobeno krivico rok svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 4, 'Blagoslovi, Gospod, dobre in pravične v srcih svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 5, 'Kateri pa zavijajo na kriva pota svoja, pokori jih naj Gospod z njimi, ki delajo krivico. Mir Izraelu!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 1, 'Pesem preizvrstna. Ko je peljal Gospod množico vjetnikov Sijonskih nazaj, bili smo kakor katerim se sanja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 2, 'Tedaj so se smeha napolnila usta naša, in jezik naš s petjem; tedaj se je reklo med narodi: Veličastne reči dela Gospod z njimi!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 3, 'Veličastne reči dela Gospod z nami, veseli smo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 4, 'Pelji nazaj, Gospod, množico vjetnikov naših, kakor presilne vode v suho deželo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 5, 'Kateri so sejali sè solzami, žanjejo naj s petjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 6, 'Kateri je pridobljeno seme noseč hodil neprestano jokaje, vrne se naj s petjem domóv noseč snope svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 1, 'Pesem preizvrstna za Salomona. Ako Gospod ne zida hiše, zastonj bi se trudili zanjo zidarji; ako Gospod ne varuje mesta, zastonj bi bil priden čuvaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 2, 'Zastonj vam bodijo, kateri vstajajo pred svitom, ki sedévajo pozno, ki uživajo jed bolečin; tako daje ljubljencu svojemu spanje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 3, 'Glej, posest Gospodova so sinovi; plačilo sad telesni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 4, 'Kakor pušice v močnega roki, tako so dečki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 5, 'Blagor možu, kateri bode napolnil tul z njimi; ne bode jih sram, temuč sovražnike pokončajo v njih vratih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 1, 'Pesem preizvrstna. Blagor mu, kdorkoli se boji Gospoda, kateri hodi po potih njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 2, 'Delo namreč rok svojih bodeš užival, srečen bodeš in dobro ti bode.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 3, 'Žena tvoja kakor trta rodovitna na strani hiše tvoje; sinovi tvoji, kakor mlade oljke, obdajali bodo mizo tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 4, 'Glej, tako bode blagoslovljen kateri se boji Gospoda!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 5, 'Blagoslavlja te Gospod sè Sijona; uživaj torej srečo Jeruzalemsko vse dnî svojega življenja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 6, 'In poglej sinov svojih otroke; mir nad Izraelom!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 1, 'Pesem preizvrstna. Mnogo so me stiskali od mladosti moje, govori naj sedaj Izrael.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 2, 'Mnogo so me stiskali od mladosti moje; vendar me niso zmogli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 3, 'Po hrbtu so mi orali orači, potegnili so vsako črto svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 4, 'Gospod pravični presekal je debele vrvi krivičnih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 5, 'Osramotili se bodo in nazaj pognali vsi sovražniki Sijonovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 6, 'Bodo kakor seno na strehah, katero usahne, predno se izdere,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 7, 'S katerim ne napolni roke svoje žanjec, ali naročja svojega, kdor veže snope.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 8, 'In ne porekó mimo gredoči: Blagoslov Gospodov bodi z vami; blagoslavljamo vas v imenu Gospodovem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 1, 'Pesem preizvrstna. Iz globočin sem te klical, Gospod:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 2, 'Gospod, poslušaj glas moj; ušesa tvoja naj pazijo na prošinj mojih glas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 3, 'Ako bodeš na krivice gledal, Gospod, kdo bi mogel obstati?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 4, 'Ker pri tebi je odpuščenje, da te česté v svetem strahu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 5, 'Čakal sem Gospoda, čakala je duša moja; tudi v besedi njegovi imam nado.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 6, 'Srce moje hrepeni po Gospodu, bolj ko straže po jutru, ki čujejo noter do jutra.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 7, 'Nado imej Izrael v Gospodu, ker pri Gospodu je milost, in pri njem največ rešenja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 8, 'In on bode rešil Izrael vseh krivic njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 1, 'Pesem preizvrstna Davidova. Gospod, visok ni bil moj duh in ne povzdignene moje očí; in nisem se lotil reči velikih ali visokih, bolj ko se spodobi meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 2, 'Ali nisem pomiril in utešil srca svojega, podoben njemu, ki se odstavlja od mleka pri materi svoji: podobno odstavljenemu od mleka bilo je pri meni srce moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 3, 'Nado imej Izrael v Gospodu, od tega časa na vekomaj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 1, 'Pesem preizvrstna. Spominjaj se, Gospod, Davida, z vso bridkostjo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 2, 'Da je prisegel Gospodu, obljubil mogočnemu Bogu Jakobovemu');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 3, '\"Ne pojdem v hišo svoje šator, stopil ne bodem v ležišče postelje svoje;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 4, 'Spanja ne bodem dal svojim očém, dremanja trepalnicam svojim:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 5, 'Dokler ne najdem mesta za Gospoda, bivališča za mogočnega Boga Jakobovega.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 6, 'Glej, slišali smo, da je bilo v Efratski deželi; našli smo ga bili v pokrajinah Jarovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 7, 'Bližamo se šatorom njegovim, priklanjamo se pred nog njegovih podnožjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 8, 'Vstani, Gospod, v svoj počitek, ti in skrinja moči tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 9, 'Duhovniki tvoji naj se oblečejo s pravico, in pojó naj, katere milostno sprejemlješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 10, 'Zavoljo Davida, hlapca svojega, ne odvrni maziljenca svojega obličja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 11, 'Prisegel je Gospod Davidu resnico, od katere ne bode odstopil, govoreč: \"Od telesa tvojega sadú bodem posadil na prestol tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 12, 'Ako se bodo držali zaveze moje sinovi tvoji in pričanj mojih posameznih, katera jih bodem učil, bodo tudi njih sinovi vekomaj sedeli na prestoli tvojem.\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 13, 'Ker Gospod je izvolil Sijon, želel si ga je za prebivališče svoje:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 14, '\"To je počitek moj vekomaj, tu bodem prebival, ker to sem si želel.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 15, 'Brašno njegovo bodem mogočno blagoslovil; potrebne njegove bodem nasitil z jedjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 16, 'In duhovnike njegove bodem oblekel z blaginjo, in katere v nji blagovoljno sprejemam, bodejo peli.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 17, 'Tam bodem storil, da bode poganjal rog Davidov, kjer sem pripravil svetilo maziljencu svojemu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 18, 'Sovražnike njegove bodem oblekel sè sramoto, nad njim pa bode cvèlo venčanje njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 1, 'Pesem preizvrstna Davidova. Glej, kako dobro, in kako prijetno, da vkup prebivajo bratje!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 2, 'Kakor ono najbolje mazilo razlito čez glavo, cedeče se na brado, brado Aronovo, ki seza dol do roba obleke njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 3, 'Kakor rosa na Hermonu, kakor katera kaplje nad gore Sijonske, ker tja pošilja Gospod blagoslov svoj, življenje vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 1, 'Pesem preizvrstna. Glejte, blagoslavljajte Gospoda, vsi hlapci Gospodovi, kateri stojite v hiši Gospodovi vsako noč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 2, 'Povzdignite roke svoje sveto in blagoslavljajte Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 3, 'Blagoslavjal te bode sè Sijona Gospod, kateri je naredil nebesa in zemljo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 1, 'Aleluja! Hvalite ime Gospodovo, hvalite gospodovi hlapci!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 2, 'Kateri stojite v hiši Gospodovi, v vežah hiše našega Boga.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 3, 'Hvalite Gospoda, ker dober je Gospod; prepevajte imenu njegovemu, ker je prijetno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 4, 'Ker Jakoba si je izvolil Gospod, Izraela v svojo last.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 5, 'Ker jaz vem, da je velik Gospod, in kralj naš nad vse bogove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 6, 'Karkoli mu je po volji, stori Gospod; v nebesih in na zemlji, po morjih in vseh breznih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 7, 'Ki pripelje sopare od kraja zemlje, bliske dela z dežjem, vetrove jemlje iz zakladnic svojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 8, 'Ki je udaril prvorojeno v Egiptu, od ljudî in od živine.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 9, 'Poslal je znamenja in čuda v sredo tvojo, Egipt, zoper Faraona in zoper vse hlapce njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 10, 'Kateri je udaril narode mogočne, in pobil silne kralje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 11, 'Sihona, kralja Amorejskega in Oga, kralja Basanskega, in vsa kraljestva Kanaanska.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 12, 'In dal je njih deželo v posest, v posest Izraelu, svojemu ljudstvu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 13, 'O Gospod, ime tvoje je vekomaj; Gospod, spomin tvoj od roda do roda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 14, 'Ker Gospod sodi ljudstvo svoje, žal mu je kmalu za hlapce svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 15, 'Maliki narodov zlati in srebrni, rok človeških dela,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 16, 'Usta imajo, ali ne govoré, oči, ali ne vidijo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 17, 'Ušesa imajo, ali ne slišijo; tudi sape ni nič v njih ustih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 18, 'Podobni njim bodejo, kateri jih delajo; kdorkoli vanje zaupa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 19, 'Hiša Izraelova, blagoslavljajte Gospoda! hiša Aronova, blagoslavljajte Gospoda!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 20, 'Hiša Levijeva, blagoslavljajte Gospoda; Gospoda boječi se, blagoslavljajte Gospoda;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 21, '\"Slava Gospodu sè Sijona, ki prebiva v Jeruzalemu! Aleluja!\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 1, 'Slavite Gospoda, ker dober je, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 2, 'Slavite bogov Boga, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 3, 'Slavite gospodov Gospoda, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 4, 'Njega, ki dela čudovita dela, velika sam, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 5, 'Kateri je naredil z umnostjo nebesa; ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 6, 'Kateri razpenja zemljo nad vodami, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 7, 'Kateri je naredil luči veliko, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 8, 'Solnce, da gospoduje podnevi, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 9, 'Mesec sè zvezdami, da gospodujejo ponoči, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 10, 'Kateri je udaril Egipčane v njih prvorojenih, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 11, 'In izpeljal je Izraela iz med njih, ker vekomaj je milost njegova;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 12, 'Z močno pestjo in z iztegneno roko, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 13, 'Kateri je razdelil morje trstovito na kose, ker vekomaj je milost njegova;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 14, 'In peljal Izraela po sredi njegovi, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 15, 'In podrl je Faraona in krdela njegova v morje trstovito, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 16, 'Kateri je peljal ljudstvo svoje skozi puščavo, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 17, 'Kateri je udaril kralje velike, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 18, 'In pobil je kralje veličastne, ker vekomaj je milost njegova:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 19, 'Sihona, kralja Amorejskega, ker vekomaj je milost njegova;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 20, 'In Oga, kralja Basanskega, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 21, 'In dal je njih deželo v posest, ker vekomaj je milost njegova;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 22, 'Posest Izraelu, svojemu hlapcu, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 23, 'Kateri v ponižanji našem spominja se nas, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 24, 'In otima nas sovražnikov naših, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 25, 'Ki daje hrane vsemu mesu, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 26, 'Slavite Boga mogočnega nebes, ker vekomaj je milost njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 1, 'Ob rekah Babilonskih, ondi smo sedeli ter jokali, spominjajoč se Sijona.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 2, 'Na vrbe v deželi obesili smo strune svoje,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 3, 'Dasì so tam hoteli od nas veselih pesmi, ki so nas odpeljavali vjete, in ki so mučili nas govoreč: Pojte nam katero pesmi Sijonskih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 4, 'Kako bi bili peli pesem Gospodovo v tujcev deželi?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 5, 'Če pozabim tebe, Jeruzalem, pozabi naj se desnica moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 6, 'Jezik moj naj se mi prijemlje neba, ako se ne spominjam tebe, ako ne povzdigujem Jeruzalema nad glavo radosti svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 7, 'Spomni se, Gospod, zoper Edomejce dneva Jeruzalemskega; kateri so rekli: \"Razvalite, razvalite; dokler bode kaj podzidja v njem!\"');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 8, 'Rod Babilonski naj se pokončá; blagor mu, kdor ti bode povrnil hudodelstvo, katero si nam storil.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 9, 'Blagor, kdor zgrabi in razdrobi otroke tvoje ob skalo!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 1, 'Davidova. Slavil te bodem iz vsega srca svojega; v pričo oblastev bodem ti prepeval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 2, 'Priklanjal se bodem proti svetišču svetosti tvoje, in slavil ime tvoje, zavoljo milosti tvoje in zavoljo tvoje zvestobe; ker poveličuješ z vsem imenom svojim govor svoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 3, 'Kateri dan sem vpil, tisti dan si me uslišal; storil si, da me je povzdignila v srci mojem moč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 4, 'Slavili te bodo, Gospod, vsi kralji zemeljski, ko bodo slišali govor tvojih ust.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 5, 'In peli bodo s potov Gospodovih, da je velika slava Gospodova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 6, 'Dasì je vzvišen Gospod, vendar gleda na nizkega; dasi visok, spoznava iz daljave.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 7, 'Ako hodim po sredi stiske, ohraniš me živega; v obraz sovražnikov mojih iztegneš roko svojo, in desnica tvoja me ohrani.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 8, 'Gospod naj doprinese zame; Gospod, milost tvoja je vekomaj; od rok svojih dél ne odjenjaj!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 1, 'Načelniku godbe: psalm Davidov. Gospod, preiskuješ me in spoznavaš.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 2, 'Ti poznavaš sedenje moje in vstajanje moje; misel mojo umeš od daleč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 3, 'Hojo mojo in ležo mojo obsezaš, in znana so ti vsa pota moja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 4, 'Ko ni še govor na jeziku mojem, glej, Gospod, poznaš ga vsega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 5, 'Zadaj in spredaj me obdajaš, in name pokladaš roko svojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 6, 'Prečudovita je vednost tvoja, da bi te varal; visoka je, ne morem je preseči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 7, 'Kam naj grem pred duhom tvojim, ali kam naj bežim pred tvojim obličjem?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 8, 'Ko bi stopil na nebesa, tam si; ali bi ležišče izbral v grobu, glej tu si.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 9, 'Ko bi si vzel zarije peroti, da bi prebival na pokrajini morja,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 10, 'Tudi tja bi me spremljala tvoja roka, in zgrabila bi me desnica tvoja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 11, 'Ko bi pa rekel: Temé me bodo vsaj pokrile kakor z mrakom; vendar noč je svetloba okolo mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 12, 'Tudi temé ne morejo tako omračiti, da bi ti ne videl skozi; ampak noč razsvetljuje kakor dan, tako so temé kakor luč.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 13, 'Ti namreč imaš v lasti ledvice moje; pokrival si me v telesu matere moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 14, 'Slavim te zato, ker ogledujoč tista dela strmim, čudovita dela tvoja predobro pozna srce moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 15, 'Skrita ni tebi moja moč, odkar sem ustvarjen bil na skrivnem; umetno narejen, kakor v zemlje globočinah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 16, 'Testo moje vidijo tvoje oči, in v knjigi tvoji je pisano vse to; od kar se je narejalo, ko ni bilo še nič tega.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 17, 'Zatorej pri meni, o kako dražestne so misli tvoje, o Bog mogočni! Kako preobila njih števila!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 18, 'Našteval bi jih, a več jih je ko peska, čujem naj še s teboj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 19, 'O da bi pokončal, o Bog, krivičnega; in može krvoločne, rekoč: Poberite se izpred mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 20, 'Kateri zoper tebe govoré pregrešno; kateri povzdigujejo nično sovražnike tvoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 21, 'Ali ne sovražim, o Gospod, sovražnikov tvojih, in se ne mučim v zaničevanji do njih, ki se spenjajo zoper tebe?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 22, 'S popolnim sovraštvom jih sovražim; za neprijatelje so meni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 23, 'Preiskuj me, Bog mogočni, in spoznaj srce moje; izkusi me in spoznaj misli moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 24, 'In glej, hodim li po potu, tebi nadležnem; in vodi me po večnem potu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 1, 'Načelniku godbe, psalm Davidov.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 2, 'Reši me, Gospod, hudobnih ljudî; mož presilovitih brani me,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 3, 'Kateri mislijo hudo v srci; vsak dan se shajajo – na vojsko.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 4, 'Brusijo jezik svoj, podoben kačjemu; strup gadji je pod njih ustnami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 5, 'Reši me, Gospod, rok krivičnih, mož presilovitih brani me, ki mislijo izpodbiti mi noge.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 6, 'Skrivali so mi prevzetniki zanko in vrvi; razgrinjali mi mrežo poleg pota.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 7, 'Rekel sem Gospodu; Bog mogočni si moj; čuj, Gospod, molitev mojih glas.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 8, 'Gospod, Bog, moč blaginje moje; glavo si mojo pokril o boja času.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 9, 'Ne dopústi, Gospod, kar želi krivični; pregrešne misli njegove ne pospešuj; povzdigovali bi se presilno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 10, 'Glave njih, ki me obdajajo, – ustnic njih nadloga naj jih pokrije.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 11, 'Žarjavica pridi nadnje; v ogenj naj jih vrže, v jame, da ne vstanejo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 12, 'Mož prokleti ne utrdi se na zemlji; mož silovitosti, njega naj udari pogin.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 13, 'Vem, da bode Gospod pravdo vodil siromaku, pravico potrebnim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 14, 'Dà, pravični bodo slavili ime tvoje; pošteni sedeli pred tvojim obličjem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 1, 'Psalm Davidov. O Gospod, kličem te, hiti k meni; čuj glas moj, ko te kličem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 2, 'Molitev moja pridi kakor kadilo pred te; povzdigovanje mojih rok kakor dar večerni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 3, 'Zloži Gospod, opazuj usta moja; straži karkoli izhaja z ustnic mojih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 4, 'Ne daj, da se srce moje nagne k hudobni reči, dela doprinašat po krivici z možmi, ki delajo krivico; tudi naj ne uživam njih slaščic.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 5, 'Udari naj me nazaj pravični, milost bode, in posvari me, mazilo bode izvrstno; ne brani se glava moja; čim bolj, tem bolj bode: molitev moja v njih nesrečah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 6, 'Ali planejo dol raz skale njih sodniki; dasi umejo, da so govori moji prijetni.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 7, 'Kakor bi kdo razsekal in razklal zemljo, raztresejo se naše kosti, v groba žrelo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 8, 'Ko se v té, Gospod, ozirajo moje oči, k tebi pribegnem, ne zapústi duše moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 9, 'Reši me zadrge, katero so mi razpeli, in zank njih, ki delajo krivico.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 10, 'Padejo naj v mreže svoje vsi krivični, jaz pa pojdem mimo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 1, 'Pesem ukovita Davidova, ko je bil v jami, molitev.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 2, 'Z glasom svojim kličem Gospoda; z glasom svojim prosim pred Gospodom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 3, 'Pred njim iztresam premišljevanje svoje; stisko svojo oznanjam pred njim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 4, 'Ko je omagoval moj duh v meni, takrat si ti spoznal stezo mojo, ko so mi skrivali zanko, kamorkoli sem popotoval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 5, 'Ozri se na desno in poglej; ni ga, da bi me poznal; izginilo mi je zavetje, ni ga, da bi skrbel za življenje moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 6, 'K tebi kličem, Gospod, govoreč: Ti si zavetje moje, delež moj v deželi živečih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 7, 'Poslušaj vpitje moje, ker ponižan sem silno; otmi me njih, ki me preganjajo, ker močnejši so od mene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 8, 'Izpelji iz zapora življenje moje, da slavim ime tvoje; obdajali me bodo pravični, ko mi bodeš izkazal dobroto.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 1, 'Psalm Davidov. O Gospod, sliši molitev mojo; ušesa nagni k prošnjam mojim; po zvestobi svoji usliši me, po pravici svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 2, 'In ne hodi v sodbo s hlapcem svojim, ker pravičen bi ne bil pred teboj nihče, ki živi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 3, 'Sovražnik namreč preganja dušo mojo; tlači na tla krdelo moje; dela, da sedevam v teminah; smo, kakor mrliči nekdaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 4, 'Tako, da duh moj v meni omaguje; sredi mene zdí se samo sebi zapuščeno srce moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 5, 'Spominjam se dnî nekdanjih, premišljujem vse delo tvoje, dejanje tvojih rok preudarjam.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 6, 'Roke svoje razprostiram proti tebi; duša moja, kakor zemlja razsušena, hrepeni po tebi:');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 7, 'Hiti, usliši me, Gospod, duh moj hira; ne skrivaj mi obličja svojega, ker podoben postajam njim, ki gredó v grob dol.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 8, 'Daj, da slišim zgodaj milost tvojo, ker v té imam zaupanje; naznani mi pot, po kateri bodem hodil, ker do tebe povzdigujem srce svoje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 9, 'Otmi me sovražnikov mojih, Gospod; pri tebi sem skrit.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 10, 'Uči me delati voljo tvojo, ker ti si moj Bog, z dobrim duhom svojim spremljaj me po ravni zemlji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 11, 'Zavoljo imena svojega, Gospod, ohrani me živega; zavoljo pravice svoje izpelji iz stiske dušo mojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 12, 'In zavoljo milosti svoje iztrebi sovražnike moje, pokončaj vse, ki stiskajo dušo; ker jaz sem hlapec tvoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 1, 'Davidova. Blagoslovljen bodi Gospod, skala moja, kateri uči boj roke moje, prste moje vojsko;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 2, 'Milost moja in grad moj; višava moja in rešitelj moj: pomočnik, ščit moj, do katerega pribegam, ki mi podložno dela ljudstvo moje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 3, 'Gospod, kaj je človek, da ga spoznaš, sin umrjoči, da se zmeniš zanj?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 4, 'Človek je podoben ničemurnosti, dnevi njegovi so kakor mimo gredočega senca.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 5, 'Gospod, nagni nebesa svoja ter stopi dol; dotakni so tistih gorâ, in kadé se naj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 6, 'Strelo zaženi in razkropi jih; proži pušice svoje in izbegaj jih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 7, 'Iztegni roko svojo z višave; reši me in otmi me iz mnogih vodâ, iz tujcev roke.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 8, 'Njih usta govoré nično, in njih desnica je krivičnosti desnica.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 9, 'Bog, novo pesem bodem ti pel; na deseterostrunje bodem ti prepeval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 10, 'Tebi, ki daješ blaginjo kraljem, otimaš Davida, hlapca svojega, od hudobnega meča.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 11, 'Réši me in otmi me iz tujcev roke, katerih usta govoré nično, in njih desnica je krivičnosti desnica.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 12, 'Da bodo sinovi naši kakor rastline dobro zrejene v nežni dobi svoji, in hčere naše kakor vogelni kameni obdelani v svetišči.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 13, 'Žitnice naše polne naj dajo obilen živež; naše ovce naj tisočero rodévajo, tisočkrat naj bodo pomnožene v stajah naših.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 14, 'In voli naši predebeli; nič napada, nič izpada, in tožbe naj ne bode v ulicah naših.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 15, 'Blagor onemu ljudstvu, kateremu se tako godi; blagor ljudstvu, kogar Bog je Gospod.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 1, 'Hvala Davidova. Poviševal te bodem, Bog moj, kralj; in blagoslavljal bodem ime tvoje vekomaj in vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 2, 'Vsak dan te bodem blagoslavljal, in hvalil ime tvoje vekomaj in vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 3, 'Velik je Gospod in hvale vreden jako; dà, velikosti njegove ni preiskati.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 4, 'Rod naj rodú slavi dela tvoja; kakor ona oznanjajo vsakotero mogočnost tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 5, 'Lepoto in slavo tvojega veličastva, in čudovite stvari tvoje bodem oznanjal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 6, 'In moč čudovitih dél tvojih naj slavé; in posamezna velika dela tvoja bodem pripovedoval.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 7, 'Spomin obile dobrote tvoje naj vrè iz njih; pravico tvojo naj pojó.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 8, 'Milosten in usmiljen je Gospod; potrpežljiv in velik v milosti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 9, 'Dober je Gospod vsem; in usmiljenje njegovo v vseh delih njegovih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 10, 'Slavé te naj, Gospod, vsa dela tvoja; in blagoslavljajo te naj, katerim milost izkazuješ.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 11, 'Slavo kraljestva tvojega naj slavé, in naznanjajo mogočnost tvojo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 12, 'Da sinom človeškim oznanjajo mogočnost njegovo, in slavo in lepoto njegovega kraljestva.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 13, 'Kraljestvo tvoje je vseh vekov kraljestvo, in gospostvo tvoje od roda do roda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 14, 'Gospod podpira vse padajoče, in kvišku pomaga vsem omahujočim.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 15, 'Vseh oči gledajo v té; ti jim daješ jedi o svojem času.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 16, 'Roko svojo odpreš in nasitiš karkoli živi, po volji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 17, 'Pravičen je Gospod po vseh potih svojih, in dobrotljiv v vseh svojih delih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 18, 'Blizu je Gospod vsem, ki ga kličejo; vsem, kateri ga kličejo v zvestobi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 19, 'Voljo spolnjuje boječim se njega; vpitje njih sliši in daje jim blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 20, 'Gospod hrani vse, kateri ga ljubijo; vse hudobne pa pogublja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 21, 'Hvalo Gospodovo naj govoré usta moja; in vse meso naj blagoslavlja sveto ime njegovo, vekomaj in vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 1, 'Aleluja! Hvali, duša moja, Gospoda.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 2, 'Hvalil bodem Gospoda v življenji svojem; prepeval bodem Bogu svojemu, dokler bodem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 3, 'Ne imejte zaupanja v prvake, v sina človeškega, pri katerem ni blaginje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 4, 'Duh njegov izide, povrne se v zemljo svojo; isti dan minejo misli njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 5, 'Blagor, komur je na pomoč Bog mogočni Jakobov; katerega nada je v Gospodu, njegovem Bogu,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 6, 'Kateri je naredil nebesa in zemljo, morje in kar je v njiju, kateri hrani zvestobo vekomaj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 7, 'Kateri dela pravico zatiranim, hrane daje lačnim, Gospod oprašča jetnike.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 8, 'Gospod odpira očí slepim, Gospod vzdiguje potrte, Gospod ljubi pravične.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 9, 'Gospod brani tujce, siroto in vdovo podpira; pot pa hudobnih razdira.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 10, 'Vladal bode Gospod vekomaj; Bog tvoj, o Sijon, od roda do roda. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 1, 'Hvalite Gospoda; ker dobro je prepevati Bogu našemu; ker prijetno, spodobno je hvaljenje.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 2, 'Zidar Jeruzalema Gospod, Izraelce zbira razkropljene.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 3, 'On ozdravlja potrte v srci in obvezuje v njih bolečinah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 4, 'Prešteva zvezd število, kliče jih, kolikor jih je, po imenih.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 5, 'Velik je Gospod, Bog naš, in mnoga moč njegova, razumnost njegova brezmerna.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 6, 'Krotke podpira Gospod, hudobne potiska noter do tal.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 7, 'Pojte hvalne pesmi Gospodu, na strune prepevajte našemu Bogu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 8, 'On zagrinja z gostimi oblaki nebesa; dež napravlja zemlji, daje, da seno rodevajo gore.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 9, 'Živež svoj daje živini, mladim krokarjem, ki čivkajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 10, 'Moči konjeve se ne veseli, stegna odličnega moža mu niso po volji;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 11, 'Po volji so Gospodu boječi se njega, kateri imajo nado v milosti njegovi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 12, 'S hvalo slávi Jeruzalem Gospoda, hvali Boga svojega, o Sijon.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 13, 'Ker zapahe tvojih vrát utrjuje, sinove tvoje blagoslavlja sredi tebe.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 14, 'Mir daje pokrajinam tvojim, z mozgom pšenice te siti.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 15, 'Ko pošlje govor svoj na zemljo, urno izteče beseda njegova.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 16, 'Sneg daje kakor volno, slano razsiplje kakor pepél.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 17, 'Led svoj meče dol, kakor koščke; pred mrazom njegovim kdo prebije?');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 18, 'Besedo svojo pošlje in jih raztaja; kakor hitro pihne veter svoj, iztekó vodé.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 19, 'Besede svoje naznanja Jakobu; postave svoje in pravice svoje Izraelu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 20, 'Ni storil tako nobenemu narodu; zatorej ne poznajo tistih pravic. Aleluja.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 1, 'Aleluja! Hvalite Gospoda, nebeščani, hvalite ga v višavah.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 2, 'Hvalite ga vsi angeli njegovi, hvalite ga vse vojske njegove.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 3, 'Hvalita ga solnce in mesec; hvalite ga vse svetle zvezde.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 4, 'Hvalite ga nebes nebésa, in vode, katere so nad tem nebom.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 5, 'Hvali naj ime Gospodovo, kar je na povelje njegovo ustvarjeno bilo takoj.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 6, 'Kar je ustanovil vekomaj, na veke; dal je zapoved, katere naj nobeno ne prestopi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 7, 'Hvalite Gospoda, zemeljske stvari; zmaji in brezna vsa.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 8, 'Ogenj in toča, sneg in sopara, veter viharni spolnjujoč besedo njegovo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 9, 'Same gore in hribi, drevesa rodovitna, cedre vse;');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 10, 'Same zveri in živina vsa, laznina in tiči krilati.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 11, 'Kralji zemeljski in narodi vsi; knezi in vsi zemljé sodniki.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 12, 'Mladeniči in tudi device, starci z dečki');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 13, 'Hvalijo naj ime Gospodovo, ker vzvišeno je njega samega ime; lepota njegova nad zemljo in nebo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 14, 'In rog povišuje svojemu ljudstvu, hvalo vseh, katere sprejema prijazno, Izraelcev, ljudstva bližnjega njemu. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 1, 'Aleluja! Pojte Gospodu pesem novo; hvalo njegovo v zboru njih, katere sprejema prijazno.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 2, 'Veséli se Izrael v njem, ki ga je ustvaril; sinovi Sijonski naj se radujejo v kralji svojem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 3, 'Hvalijo naj ime njegovo s piščaljo; z bobnom in strunami naj mu prepevajo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 4, 'Ker milosten je Gospod z ljudstvom svojim; krotke diči z blaginjo.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 5, 'Radujejo se naj v slavi prijazno sprejeti; pojó naj na ležiščih svojih,');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 6, 'Hvalo povišujočo Boga mogočnega v grlu svojem, in meč dvorezni v roki svoji.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 7, 'Da se mašujejo nad narodi, ljudstva pokoré.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 8, 'Da zvežejo z verigami njih kralje; in njih plemenitnike z vezmi železnimi.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 9, 'Da nad njimi spolnijo pisano pravico; kar je čast vsem onim, katere sprejema prijazno. Aleluja!');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 1, 'Aleluja! Hvalite Boga, mogočnega o svetosti njegovi; hvalite ga v veličastva njegovega gradu.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 2, 'Hvalite ga o obili mogočnosti njegovi, hvalite ga po velikem veličastvu njegovem.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 3, 'Hvalite ga s trombe glasom; hvalite ga z brenkljami in strunami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 4, 'Hvalite ga z bobnom in piščaljo, hvalite ga z orgljami.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 5, 'Hvalite ga s cimbali donečimi, hvalite ga sè sistri.');
INSERT INTO `SloStritar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 6, 'Vsaka duša hvali naj Gospoda! Aleluja!');
